// ── One status per script (Karen, 2026-09-27) ──────────────────────────────
// "Real Consolidated Status" is a script's ONE stage: Script, Review Script,
// Shoot, Attach Raw, To Design, To Edit, In Progress, Need Changes, Approve
// Media, Approve Post, To Schedule, Scheduled, Published, Publish Failed. The
// four old stage fields (Status, Scripting status, Shooting status,
// Post-production status) are still written next to it for the flows and
// rollups that have not moved yet. Every Content write goes through
// withStage(), which reads the stage off the old fields that write sets, so
// the two can never disagree. Field maps name it `stage`.
type StageCtx = { isStatic?: boolean; hasFootage?: boolean; current?: string };
// Airtable renamed the stages on 2026-10-02 (the Creative Studio's OLD_STATUS
// list). A stage still in the old words reads as the new one, and only the new
// words are ever written: an option Airtable no longer has can't be saved.
const STAGE_RENAMES: Record<string, string> = {
  "Drafting": "Script", "Review Draft": "Review Script", "To Shoot": "Shoot",
  "Attach Media": "Attach Raw", "To Approve": "Approve Media", "Ready to Schedule": "To Schedule",
};
const currentStageName = (s: string) => STAGE_RENAMES[s] || s;
function labelOf(v: any): string {
  if (v == null) return "";
  if (Array.isArray(v)) return labelOf(v[0]);
  if (typeof v === "object") return String(v.label ?? v.name ?? "");
  return String(v);
}
// The stage a write lands on, or "" when the write does not move the stage: a
// visibility change, a refine's busy flag, a stalled card put back, a discard.
function stageForWrite(w: any, ctx: StageCtx): string {
  const val = (k: string) => (Object.prototype.hasOwnProperty.call(w, k) ? labelOf(w[k]) : undefined);
  const ph = val("status"), sc = val("scriptingStatus"), sh = val("shootingStatus"), pp = val("postProductionStatus");
  const edit = ctx.isStatic ? "To Design" : "To Edit";
  if (pp === "Discard") return "";
  if (ph === "Posted") return "Published";
  if (ph === "Posting Failed" || ph === "Scheduling Failed") return "Publish Failed";
  if (ph === "Scheduled") return "Scheduled";
  if (ph === "Ready to Post" || pp === "Ready to Post") return "To Schedule";
  if (pp === "In Progress") return "In Progress";
  if (pp === "To Approve") return "Approve Media";
  if (pp === "To Design") return "To Design";
  if (pp === "New Shots" || pp === "Creatives Queue" || pp === "Flowy's Queue"
    || sh === "Sent to Post Production" || ph === "Post Production") return edit;
  // Filmed: straight on to editing when the footage is already on the card,
  // otherwise it waits in Attach Raw for it (Karen 2026-09-27).
  if (sh === "Shot Taken") return ctx.hasFootage ? edit : "Attach Raw";
  if (sh === "To Shoot" || ph === "Shoot Plan") return "Shoot";
  if (ph === "Scripting") return sc === "Queued" || sc === "Writing" ? "Script" : "Review Script";
  const current = ctx.current ? currentStageName(ctx.current) : "";
  if (sc === "To Review" && (!current || current === "Script" || current === "Review Script")) {
    return "Review Script";
  }
  return "";
}
// The four old fields that belong to a stage, keyed like the field maps.
function legacyStageFields(stage: string, isStatic: boolean): Record<string, string | null> {
  switch (currentStageName(stage)) {
    case "Review Script":
      return { status: "Scripting", scriptingStatus: "To Review", shootingStatus: null, postProductionStatus: null };
    case "Shoot":
      return { status: "Shoot Plan", scriptingStatus: "Shoot Plan", shootingStatus: "To Shoot", postProductionStatus: null };
    case "Attach Raw":
      return { status: "Shoot Plan", scriptingStatus: "Shoot Plan", shootingStatus: "Shot Taken", postProductionStatus: null };
    case "To Edit":
    case "To Design":
      return {
        status: "Post Production", scriptingStatus: "Shoot Plan", shootingStatus: "Sent to Post Production",
        postProductionStatus: isStatic ? "To Design" : "New Shots",
      };
    default:
      return {};
  }
}
// Adds the stage to a Content write. Takes the create shape (the fields
// themselves) or the update shape ({ recordId, fields }).
function withStage(args: any, ctxOf?: (id: string) => StageCtx | undefined, base?: StageCtx): any {
  const isUpdate = !!args && typeof args === "object" && "recordId" in args && "fields" in args;
  const fields = isUpdate ? args.fields : args;
  if (!fields || typeof fields !== "object" || Object.prototype.hasOwnProperty.call(fields, "stage")) return args;
  const ctx: StageCtx = { ...(base || {}), ...((isUpdate && ctxOf && ctxOf(args.recordId)) || {}) };
  const stage = stageForWrite(fields, ctx);
  if (!stage) return args;
  let next: any = { ...fields, stage };
  // Marked filmed with the footage already on it: the card moves straight on,
  // so the old fields follow it there too.
  if ((stage === "To Edit" || stage === "To Design") && labelOf(fields.shootingStatus) === "Shot Taken") {
    next = { ...next, ...legacyStageFields(stage, !!ctx.isStatic) };
  }
  return isUpdate ? { ...args, fields: next } : next;
}
// Wraps a Content create/update hook so every write carries its stage.
function useStageWrites<T>(m: T, ctxOf?: (id: string) => StageCtx | undefined, base?: StageCtx): T {
  const ref = useRef({ ctxOf, base });
  ref.current = { ctxOf, base };
  return useMemo(() => {
    const src: any = m;
    return {
      ...src,
      mutate: (a: any, o?: any) => src.mutate(withStage(a, ref.current.ctxOf, ref.current.base), o),
      mutateAsync: typeof src.mutateAsync === "function"
        ? (a: any, o?: any) => src.mutateAsync(withStage(a, ref.current.ctxOf, ref.current.base), o)
        : src.mutateAsync,
    } as T;
  }, [m]);
}
// A card's stage as the screens show it. Rows written before the field
// existed fall back to reading it off the old fields.
function stageOf(item: any): string {
  const f = item?.fields || {};
  const s = labelOf(f.stage);
  if (s) return currentStageName(s);
  return stageForWrite(
    {
      status: f.status ?? "", scriptingStatus: f.scriptingStatus ?? "",
      shootingStatus: f.shootingStatus ?? "", postProductionStatus: f.postProductionStatus ?? "",
    },
    { isStatic: isStaticItem(item), hasFootage: hasFootage(item) },
  );
}
// A static post is designed, not edited. "Static Post" is the Content type's
// planned new name for Graphic, so both are accepted.
function isStaticItem(item: any): boolean {
  if (!item?.fields) return false;
  return isGraphicItem(item) || labelOf(item.fields.contentType) === "Static Post";
}

