// Pull display names out of a lookup / linked-record value, whatever shape
// Softr hands it in (array of strings, array of {label|name}, or Airtable's
// raw {valuesByLinkedRecordId} lookup shape).
function lookupNames(v: any): string[] {
  if (v == null) return [];
  if (Array.isArray(v)) {
    return v.map((x) => (typeof x === "string" ? x : (x?.label || x?.name || ""))).filter(Boolean);
  }
  if (typeof v === "object") {
    if (v.label || v.name) return [String(v.label || v.name)];
    if (v.valuesByLinkedRecordId) {
      const out: string[] = [];
      for (const arr of Object.values(v.valuesByLinkedRecordId)) {
        if (Array.isArray(arr)) for (const it of arr as any[]) out.push(String(it?.name || it?.label || it));
      }
      return out.filter(Boolean);
    }
    return [];
  }
  return [String(v)];
}

// Shape one raw Brands record into the Brand object the wizard consumes —
// the client-side twin of Z06's "Shape Brands Response" code node.
function shapeBrand(r: any): Brand {
  const f = r.fields || {};
  // A formula or count can arrive as a number, a numeric string ("21", "150%")
  // or a one-item array, depending on how the datasource serves it. All of
  // those are the number; anything else is the default.
  const num = (v: any, d = 0): number => {
    const x = Array.isArray(v) ? v[0] : v;
    if (typeof x === "number") return Number.isFinite(x) ? x : d;
    if (typeof x === "string") {
      const s = x.trim();
      const n = parseFloat(s.replace(/[^0-9.+-]/g, ""));
      if (!Number.isFinite(n)) return d;
      return s.endsWith("%") ? n / 100 : n;
    }
    if (x && typeof x === "object") return num(x.value ?? x.label ?? x.name, d);
    return d;
  };
  const str = (v: any) => {
    if (v == null) return "";
    if (typeof v === "string") return v;
    if (Array.isArray(v)) return v.length ? str(v[0]) : "";
    return String(v.label || v.name || v);
  };
  // A formula that can be a number OR the text "Not required" — pass through.
  const raw = (v: any) => (v == null ? 0 : (typeof v === "object" ? (v.label ?? v.name ?? 0) : v));
  return {
    id: r.id,
    name: str(f.name).trim(),
    createdDate: r.createdTime || r.createdDate || null,
    averageHealth: num(f.averageHealth),
    priorityToGenerate: str(f.priorityToGenerate).trim(),
    prioritySocial: str(f.prioritySocial),
    safetyTarget: num(f.safetyTarget),
    filmingAvailability: str(f.filmingAvailability),
    priorityCategories: [f.topicCatP1, f.topicCatP2, f.topicCatP3, f.topicCatP4, f.topicCatP5]
      .map((v: any) => lookupNames(v)[0])
      .filter(Boolean) as string[],
    priorityFormats: {
      video: [f.videoFmtP1, f.videoFmtP2, f.videoFmtP3, f.videoFmtP4, f.videoFmtP5]
        .map((v: any) => lookupNames(v)[0]).filter(Boolean) as string[],
      graphic: [f.graphicFmtP1, f.graphicFmtP2, f.graphicFmtP3, f.graphicFmtP4, f.graphicFmtP5]
        .map((v: any) => lookupNames(v)[0]).filter(Boolean) as string[],
    },
    talkingSplit: (() => {
      const v = Array.isArray(f.talkingSplit) ? f.talkingSplit[0] : f.talkingSplit;
      const n = Number(typeof v === "object" && v ? (v.label ?? v.name ?? v) : v);
      return Number.isFinite(n) && n > 0 && n <= 1 ? n : null;
    })(),
    video: {
      cadenceTargetPerWeek: num(f.videoCadence),
      currentPipelineDays: num(f.videoCurrent),
      healthPercentage: num(f.videoHealthPct),
      suggestedToApprove: raw(f.videoSuggested),
      pipelineCount: num(f.videoPipeline),
    },
    graphic: {
      cadenceTargetPerWeek: num(f.graphicCadence),
      currentPipelineDays: num(f.graphicCurrent),
      healthPercentage: num(f.graphicHealthPct),
      suggestedToApprove: raw(f.graphicSuggested),
      pipelineCount: num(f.graphicPipeline),
    },
  };
}

// The rail's own count of a brand's pipeline (2026-10-22): which brand, which content type, and whether it is on
