// The Brands row's pipeline numbers again, from a count of the scripts: the same formulas Airtable runs on
// Brands (Current Pipeline = count / per day, health = days / target, Suggested to approve, the 70/30 average),
// so the strips match Airtable the moment a script lands. No count (the read failed) keeps Airtable's numbers.
function withLivePipeline(b: Brand, live: { Video: number; Graphic: number } | null): Brand {
  if (!live) return b;
  const safety = b.safetyTarget || 0;
  const block = (cur: BrandFormatBlock, count: number): BrandFormatBlock => {
    if (count === cur.pipelineCount) return cur;
    // Per day the way Airtable divides: its own count over its own days, else the weekly cadence over 7.
    const perDay = cur.pipelineCount > 0 && cur.currentPipelineDays > 0
      ? cur.pipelineCount / cur.currentPipelineDays
      : (cur.cadenceTargetPerWeek || 0) / 7;
    const days = perDay > 0 ? count / perDay : 0;
    return {
      ...cur,
      pipelineCount: count,
      currentPipelineDays: days,
      healthPercentage: safety > 0 ? days / safety : cur.healthPercentage,
      suggestedToApprove: safety > 0 ? (safety - days < 0 ? 0 : Math.ceil((safety - days) * perDay - 1e-9)) : cur.suggestedToApprove,
    };
  };
  const video = block(b.video, live.Video);
  const graphic = block(b.graphic, live.Graphic);
  if (video === b.video && graphic === b.graphic) return b;
  const averageHealth = safety > 0 ? video.healthPercentage * 0.7 + graphic.healthPercentage * 0.3 : b.averageHealth;
  return { ...b, video, graphic, averageHealth };
}

