type WizardCat = { id: string; name: string; categoryType: string; brandIds: string[]; status: string };
function shapeWizardCat(r: any): WizardCat {
  const f = r.fields || {};
  const brandLink = Array.isArray(f.brand) ? f.brand : (f.brand ? [f.brand] : []);
  return {
    id: r.id,
    name: String((f.name && (f.name.label || f.name.name)) || f.name || "").trim(),
    categoryType: String((f.categoryType && (f.categoryType.label || f.categoryType.name)) || f.categoryType || ""),
    brandIds: brandLink.map((b: any) => b?.id || b).filter(Boolean),
    status: String((f.status && (f.status.label || f.status.name)) || f.status || ""),
  };
}

// One answered step of Create Scripts, kept in the conversation (Karen 2026-10-23: one continuous thread, like
