const FORMAT_FILMING_MINUTES: Record<string, number> = {
  "Tutorial": 20, "Mini-vlog": 20,
  "Talking Head": 15, "Reaction": 15,
  "Silent Tutorial": 12, "Silent Mini-vlog": 12,
  "Skit": 8, "BROLL & Voiceover": 8, "Lip-sync trend": 8,
  "Loop Broll": 3, "Trending template": 3,
  // Everything below needs no new filming: graphics, carousels, and the video
  // formats built from footage that already exists.
  "Long form clips": 0, "Movie & TV clips": 0, "Collaboration": 0,
  "Visual Explainer": 0, "Product Features": 0, "Before | After Post": 0,
  "Meme Post": 0, "Quotes Post": 0, "Testimonial Post": 0,
  "Storytelling Carousel": 0, "Credibility carousel": 0,
  "Meme Carousel": 0, "Quotes Carousel": 0,
};
// "Heavy" = needs real time on camera. Karen's numbers split cleanly at the
// 8-to-12 gap, so heavy is the six above 10 minutes: Talking Head, Reaction,
// Tutorial, Mini-vlog, Silent Tutorial, Silent Mini-vlog. The filming tilt caps
// how many of these a batch may hold. It never spends minutes as a budget.
const isHeavyFormat = (f: string) => (FORMAT_FILMING_MINUTES[String(f || "").trim()] ?? 0) > 10;

// Formats whose subformats need a real personal story (maps the handoff's
// STORY_FORMATS onto the live Formats table names).
const STORY_FORMATS = [
  "Mini-vlog", "Skit", "Reaction", "Testimonial Post",
  "Before | After Post", "Storytelling Carousel", "Credibility carousel",
];

// Until the strategy fills Video Format P1..P5 / Graphic Format P1..P5 for a
// brand, the rail deals from these phase-1 defaults so the flow is walkable.
const DEFAULT_PRIORITIES: Record<FormatKey, string[]> = {
  video: ["Talking Head", "Mini-vlog", "Loop Broll", "Skit", "Tutorial"],
  graphic: ["Visual Explainer", "Storytelling Carousel", "Quotes Post", "Meme Post", "Credibility carousel"],
};

// Content's Format dropdown was aligned to the Formats table by hand on
// 2026-09-03, so a dealt format is normally already a valid option. Both are
// still hand-kept lists, so match case- and space-blind and hand back the
// dropdown's exact spelling ("Credibility Carousel" from the Formats table vs
// "Credibility carousel" in the dropdown would otherwise refuse the draft).
// Unknown names pass through; genForIdx falls back to a known format on failure.
const contentFormatName = (name: string) => {
  const key = String(name || "").trim().toLowerCase();
  return [...VIDEO_FORMATS, ...GRAPHIC_FORMATS].find((f) => f.toLowerCase() === key) || String(name || "").trim();
};
// Content's old Format dropdown still labels the board's cards, and a draft is
// refused when the name is not one of its options. A menu door carries the
// Formats table's name ("Talking Head Video"), the dropdown spells it "Talking
// Head": exact match first, then the same name without a trailing " Video".
// The Formats table renamed one format since the dropdown was aligned.
const FORMAT_RENAMES: Record<string, string> = { "explainer carousel": "Visual Explainer" };
const dropdownFormatName = (name: string): string => {
  const list = [...VIDEO_FORMATS, ...GRAPHIC_FORMATS];
  const n = String(name || "").trim().toLowerCase();
  const exact = list.find((f) => f.toLowerCase() === n);
  if (exact) return exact;
  if (FORMAT_RENAMES[n]) return FORMAT_RENAMES[n];
  const bare = n.replace(/\s+video$/, "");
  return list.find((f) => f.toLowerCase() === bare) || String(name || "").trim();
};
// Whether a name is one of the dropdown's options. A format the dropdown never
// had (Informational Carousel, Brand Announcement...) is left off the draft, so
// the draft is not refused; the writer fills the linked Formats field anyway.
const isDropdownFormat = (name: string): boolean =>
  [...VIDEO_FORMATS, ...GRAPHIC_FORMATS].some((f) => f.toLowerCase() === String(name || "").trim().toLowerCase());
// A door's filming minutes: the Formats table's number when the menu carries it,
// else the old list below by name.
const doorMinutes = (d: { format: string; formatName?: string; minutes?: number }): number => {
  if (typeof d.minutes === "number" && Number.isFinite(d.minutes)) return d.minutes;
  return FORMAT_FILMING_MINUTES[dropdownFormatName(d.formatName || d.format)] ?? 0;
};
// The filming step's three answers, as minutes on camera for the whole batch
// (Karen 2026-10-10). Approximate on purpose: about a fifth over still fits.
const FILMING_BUDGET_MIN: Record<FilmTilt, number> = { none: 30, some: 60, full: Infinity };
const FILMING_LEEWAY = 1.2;

// The strategy's format ranks point at SUBFORMATS since 2026-09-27, while the
// dealer still deals Content's Format options. Until the rail deals subformats
// itself, a ranked subformat is read back to its format by name: an exact
// option, the part before " - " ("Talking Head - Extended Value"), or an option
// named inside it ("Fake advice Meme Carousel"). A name that matches none is
// dropped, so a rank of unreadable subformats falls back to the defaults.
const priorityFormatName = (name: string, family: FormatKey): string => {
  const list = family === "graphic" ? GRAPHIC_FORMATS : VIDEO_FORMATS;
  const n = String(name || "").trim().toLowerCase();
  if (!n) return "";
  const head = n.split(" - ")[0].trim();
  return list.find((f) => f.toLowerCase() === n)
    || list.find((f) => f.toLowerCase() === head)
    || [...list].sort((a, b) => b.length - a.length).find((f) => n.includes(f.toLowerCase()))
    || "";
};

// Which review-card sections each batch type gets (handoff §5). Mirrors the
// Formats table's "Fields it uses" at content-type grain.
// Slide copy is written as one text, one slide per paragraph (or per line when
// there are no blank lines). Split once, here, for the save and for the count
// the review pill shows on a static post.
function slideRowsOf(text: string): string[] {
  const raw = String(text || "");
  const parts = raw.split(/\n\s*\n/).map((x) => x.trim()).filter(Boolean);
  return parts.length > 1 ? parts : raw.split(/\n/).map((x) => x.trim()).filter(Boolean);
}
function splitSlides(text: string): Record<string, string> {
  const rows = slideRowsOf(text);
  const out: Record<string, string> = {};
  rows.slice(0, 10).forEach((row, i) => { out[`slide${i + 1}Copy`] = row.replace(/^Slide\s*\d+\s*[:.-]\s*/i, ""); });
  if (rows.length) out.slidesCount = `${Math.min(10, rows.length)} Slide${rows.length === 1 ? "" : "s"}`;
  return out;
}

