const TRENDING_LIFE_MS = 60 * 24 * 3600 * 1000;
// "bloomberg.com" out of a full link, for the small source line on a card.
const sourceHost = (u: string) => {
  try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return "link"; }
};
const trendingAlive = (t: any, now: number) => {
  const anchor = t.momentDate || t.createdTime;
  return !!anchor && (now - new Date(anchor).getTime()) < TRENDING_LIFE_MS;
};
