// The thread is text only: each message capped, the whole field kept under Airtable's long-text size.
const THREAD_MSG_CAP = 1000;
const THREAD_FIELD_CAP = 90000;
const threadClip = (t: any) => { const s = String(t ?? "").replace(/\s+\n/g, "\n").trim(); return s.length > THREAD_MSG_CAP ? s.slice(0, THREAD_MSG_CAP - 1) + "\u2026" : s; };
// Flowy's lines out of a snapshot of a rail step: tags off, one line per block.
function threadLinesOfHtml(html: string): string[] {
  const txt = String(html || "")
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(div|p|li|h\d|section)>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  const out: string[] = [];
  for (const l of txt.split("\n").map((x) => x.replace(/\s+/g, " ").trim()).filter(Boolean)) if (out[out.length - 1] !== l) out.push(threadClip(l));
  return out.slice(0, 40);
}
// Keep the field under its cap: the oldest chat lines go first, then the oldest steps' Flowy lines.
function threadToJson(t: any): string {
  let json = JSON.stringify(t);
  if (json.length <= THREAD_FIELD_CAP) return json;
  const chat = t.chat || {};
  const keys = Object.keys(chat).sort((a, b) => Number(a) - Number(b));
  while (json.length > THREAD_FIELD_CAP && keys.some((k) => chat[k].length)) {
    const k = keys.find((x) => chat[x].length)!;
    chat[k].shift();
    if (!chat[k].length) delete chat[k];
    json = JSON.stringify(t);
  }
  for (const st of t.steps || []) {
    if (json.length <= THREAD_FIELD_CAP) break;
    st.flowy = [];
    json = JSON.stringify(t);
  }
  return json.length <= THREAD_FIELD_CAP ? json : JSON.stringify({ v: 1, route: t.route, brandId: t.brandId, startedAt: t.startedAt, steps: [], scripts: t.scripts, chat: {}, cut: true });
}

