// The cook (Rail — Subtopic Cook) stores the delivery menu as JSON text on the
// subtopic. Anything unparseable is treated as "no menu", which sends serve down
// the old format dealer instead of throwing: a thin or half-cooked bank has to
// degrade, never break, because that is what every new brand looks like.
type MenuDish = {
  format: string;
  subformat: string;
  wayIn: string;
  // The door's format as the Formats table has it, and that format's Filming
  // time (min). Sent by n8n "Rail — Subtopics (read)" since 2026-10-10.
  formatName?: string;
  formatId?: string;
  minutes?: number;
  // Whether this door is a talking video, from the subformat's own content
  // type (n8n "Rail — Subtopics (read)" since 2026-10-18). Unset on old menus.
  talking?: boolean;
  // The visual twins the cook collapsed into one dish (with photos / without
  // photos / meme in frame). Serve picks among these by what assets exist.
  variants: { id: string; name: string }[];
};
type DeliveryMenu = {
  version: number;
  cookedAt: string;
  // djb2 of the stance at cook time, so a run can tell the stance has since
  // been corrected and the menu is stale.
  stanceHash: string;
  video: MenuDish[];
  graphic: MenuDish[];
};
const parseDeliveryMenu = (raw: any): DeliveryMenu | null => {
  const text = String(raw ?? "").trim();
  if (!text) return null;
  try {
    const m = JSON.parse(text);
    if (!m || typeof m !== "object") return null;
    const dishes = (list: any): MenuDish[] => (Array.isArray(list) ? list : [])
      .map((d: any) => ({
        format: String(d?.format || "").trim(),
        subformat: String(d?.subformat || "").trim(),
        wayIn: String(d?.wayIn || "").trim(),
        formatName: String(d?.formatName || "").trim() || undefined,
        formatId: String(d?.formatId || "").trim() || undefined,
        minutes: typeof d?.minutes === "number" && Number.isFinite(d.minutes) ? d.minutes : undefined,
        talking: typeof d?.talking === "boolean" ? d.talking : undefined,
        variants: (Array.isArray(d?.variants) ? d.variants : [])
          .map((v: any) => ({ id: String(v?.id || ""), name: String(v?.name || "") }))
          .filter((v: { id: string }) => !!v.id),
      }))
      .filter((d: MenuDish) => !!d.format && !!d.subformat);
    const video = dishes(m.video);
    const graphic = dishes(m.graphic);
    if (!video.length && !graphic.length) return null;
    // v1 menus carry a `priority` per dish that v2 dropped. The shape is
    // otherwise identical, so an old menu still serves; it simply has no rank
    // baked in, and the brand's ranking is applied live either way.
    return {
      version: Number(m.version) || 1,
      cookedAt: String(m.cookedAt || ""),
      stanceHash: String(m.stanceHash || ""),
      video,
      graphic,
    };
  } catch {
    return null;
  }
};

// Z07 — returns the logged-in user's Member context (Role + Strategist intro seen).
