const MARK_INTRO_SEEN_WEBHOOK = "https://flowshift.app.n8n.cloud/webhook/mark-strategist-intro-seen";

type UserContext = {
  id: string;
  email: string;
  displayName: string;
  role: string;
  strategistIntroSeen: boolean;
};

type FormatKey = "video" | "graphic";

type BrandFormatBlock = {
  cadenceTargetPerWeek: number;
  currentPipelineDays: number;
  // Direct % from Airtable (0–1 fraction). Different from currentPipelineDays
  // / safetyTarget when the brand's formula uses a different denominator.
  healthPercentage: number;
  // Suggested to approve may be a number OR the string "Not required" when the
  // pipeline is over target — front-end decides how to render either case.
  suggestedToApprove: number | string;
  pipelineCount: number;
};

type Brand = {
  id: string;
  name: string;
  // Airtable's built-in createdTime (ISO 8601 string). Z06 returns this on
  // every brand. Screen 2.D uses it to pick the 3 OLDEST brands when a user
  // has more than 3, then re-sorts those 3 by averageHealth for display order.
  createdDate?: string | null;
  averageHealth: number;
  priorityToGenerate: string;
  prioritySocial: string;
  safetyTarget: number;
  // The brand's default per-session filming availability ("1 hour", "2 hours"…).
  filmingAvailability: string;
  // Active strategy's ranked categories P1→P5 (names, in priority order).
  priorityCategories: string[];
  // Active strategy's ranked formats P1→P5 per family (Formats table names).
  priorityFormats: Record<FormatKey, string[]>;
  // The strategy's talking cap as a share of all posts, or null when unset.
  talkingSplit: number | null;
  video: BrandFormatBlock;
  graphic: BrandFormatBlock;
  // Fields intentionally NOT on the Brand object — read from the active
  // Script Request's lookup fields when their screen is built:
  //   • Default Filming Availability → Screen 4.A
  //   • Niche → Screen 7.A1
  //   • All Topic Categories → Screen 6.B (swap pool)
  //   • Topic Category P1-P5 → Screens 5.A / 6.A
};

// "14 Video scripts" → "video"; "8 Graphic scripts" → "graphic"; default video.
function parsePriorityFormat(priorityToGenerate: string): FormatKey {
  return /graphic/i.test(priorityToGenerate || "") ? "graphic" : "video";
}

// Convert a per-week cadence number into a day-based human label so the math
// grid stays consistent with the "X days" pipeline target. Used by both the
// brand-level grid (2.D) and the format-level grid (1, 1b, 2, 3a, 3b).
//   • ≥7/week  → "N {format}(s) every day" (rounds to integer if within 0.05)
//   • >0,<7    → "1 {format} every N days"
//   • 0 / null → returns null (caller filters out)
function cadenceToDayLabel(perWeek: number, formatNounSingular: string): string | null {
  if (!perWeek || perWeek <= 0) return null;
  if (perWeek >= 7) {
    const perDay = perWeek / 7;
    const rounded =
      Math.abs(perDay - Math.round(perDay)) < 0.05
        ? Math.round(perDay)
        : Math.round(perDay * 10) / 10;
    const noun = rounded === 1 ? formatNounSingular : `${formatNounSingular}s`;
    return `${rounded} ${noun} every day`;
  }
  const interval = Math.round(7 / perWeek);
  return `1 ${formatNounSingular} every ${interval} days`;
}

// Color thresholds for the pipeline bar fill AND for current-pipeline number
// tinting in the math grid. Same thresholds everywhere so the visual link
// between bar color and number color is consistent.
//   • ≥80% → healthy green
//   • 51-79% → caution yellow
//   • ≤50% → critical red
function pipelineHealthColor(pct: number): string {
  if (pct >= 80) return "#426E54";
  if (pct >= 51) return "#C9A93D";
  return "#dc2626";
}

// Screen 2.E format-strategy variant. Picks one of four lines based on per-
// format pipeline state + the brand's priority format.
//   • p-empty  — priority format pipeline count = 0
//   • np-empty — non-priority format pipeline count = 0 (priority not empty)
//   • p-thin   — priority format health is lower than non-priority AND
//                priority is itself <80% (so not just "both healthy")
//   • default  — everything else (both healthy, or non-priority thinner)
// Priority order: p-empty > np-empty > p-thin > default.
type FormatRecState = "both-empty" | "p-empty" | "np-empty" | "p-thin" | "default";
function detectFormatRecState(brand: Brand): FormatRecState {
  const priority = parsePriorityFormat(brand.priorityToGenerate);
  const np: FormatKey = priority === "video" ? "graphic" : "video";
  // Empty only when nothing says there is content: no scripts counted, no
  // days of runway and no health. Any one of the three above zero means the
  // pipeline is not empty, whichever field the datasource failed to hand over
  // (Karen 2026-09-13: "video pipeline is still empty" while Airtable held 9
  // scripts and 21 days). Brands with no cadence targets land here as zeros.
  const emptyOf = (k: FormatKey) =>
    (brand[k]?.pipelineCount ?? 0) <= 0
    && (brand[k]?.healthPercentage ?? 0) <= 0
    && (brand[k]?.currentPipelineDays ?? 0) <= 0;
  if (emptyOf(priority) && emptyOf(np)) return "both-empty";
  if (emptyOf(priority)) return "p-empty";
  if (emptyOf(np)) return "np-empty";
  const priorityHealth = brand[priority]?.healthPercentage ?? 0;
  const npHealth = brand[np]?.healthPercentage ?? 0;
  if (priorityHealth < npHealth && priorityHealth < 0.80) return "p-thin";
  return "default";
}

// Screen 2.D recommendation state. Determines which context-line variant the
// bot shows AND whether the top brand's chip gets the gradient styling.
//   • empty   — top brand has 0% OVERALL Average pipeline health. Per-format
//               pipeline counts are intentionally NOT considered here — a
//               brand with one format empty but the other healthy is an
//               "outlier", not "empty". Wins over outlier (more urgent).
//   • outlier — top brand is ≥10 percentage points below the next-lowest brand.
//   • even    — all displayed brands are within 10 points of each other.
type BrandRecState = "empty" | "outlier" | "even" | "all-empty";
function detectRecState(brands: Brand[]): BrandRecState {
  if (brands.length === 0) return "even";
  // Every brand's pipeline is empty — there is no leader to recommend, so let
  // the user pick whichever they like rather than pushing the lowest/oldest.
  if (brands.every((b) => (b.averageHealth || 0) <= 0)) return "all-empty";
  const top = brands[0];
  const topAvg = top.averageHealth || 0;
  if (topAvg === 0) return "empty";
  if (brands.length === 1) return "even";
  const next = brands[1];
  const gap = (next.averageHealth || 0) - topAvg;
  if (gap >= 0.10) return "outlier";
  return "even";
}

// Pull the user's first name from their Softr session so the bot greets them
// by name. Falls back gracefully if any of the identity fields is missing.
function deriveFirstName(currentUser: any): string {
  const u = currentUser || {};
  const candidate = u.firstName || u.displayName || u.name || u.fullName || u.email || "";
  if (!candidate) return "there";
  const first = String(candidate).trim().split(/\s+/)[0];
  return first.split("@")[0] || "there";
}

