const BRAND_GRADIENT = "linear-gradient(135deg, #EC4899 0%, #A855F7 50%, #6366F1 100%)";

// Section accents — the card's left bar + section dot take the color of the
// section the card lives in.
const SECTION_ACCENTS = {
  review: "#E5484D",         // to-review red
  reviewBright: "#FF5A5F",   // calendar tags — bright, not burnt
  generating: "#A3A3A3",     // neutral gray
  shootPlan: "#D9882F",      // orange — Approved · Shooting Plan
  completed: "#16A34A",      // green — a shoot that's been done
  postProduction: "#C9A93D", // yellow — Approved · Post Production
  trash: "#CBD5E1",          // very cold, very light gray — Trash
};

// Board field map (Content table).
// ── Files, per kind ────────────────────────────────────────────────────────
// Karen added a rollup per file type on Content. Put its EXACT Airtable field
// name here AND add the same key to `boardSelect` below; the modal reads these
// first and only falls back to the naming convention when a kind has no field
// mapped. Leave a kind as "" until its name is confirmed — a wrong name in a
// select is worse than the fallback.
const FILE_KIND_FIELDS: Record<string, string> = {
  "Raw footage": "rawFiles",
  "Reference files": "referenceFiles",
  "Voiceover": "voiceoverFiles",
  "Edited videos": "editedVideo",
  "Designed slides": "designedSlides",
  "Designed thumbnail": "thumbnailFile",
};

// Fallback while those are unmapped: uploads are named "<Kind> · <file>".
// Anything with NO kind prefix — a teleprompter take saves itself as a plain
// "recording-….mp4" — shows under Videos rather than vanishing entirely.
// One tab strip, used by the Captions platforms and the Files kinds. Both
// were rows of small pill icon buttons, which read as decoration rather than
// as a choice you make. Underlined tabs say "pick one" without any chrome.
// Scrolls sideways rather than wrapping, so six kinds never become two rows.
function TabStrip({ items, active, onPick, isDesktop }: {
  items: { key: string; label: string; count?: number; Icon?: any }[];
  active: string;
  onPick: (key: string) => void;
  isDesktop: boolean;
}) {
  return (
    <div
      className="fs-tabs"
      style={{
        display: "flex", gap: isDesktop ? "26px" : "24px", marginBottom: "20px",
        // The strip's own hairline, with each tab's marker sitting ON it, is
        // what makes these read as tabs rather than as a row of words.
        borderBottom: "1px solid #ECECEF",
        overflowX: "auto", overflowY: "hidden",
        WebkitOverflowScrolling: "touch", scrollbarWidth: "none",
      }}
    >
      {items.map(({ key, label, count, Icon }) => {
        const on = active === key;
        return (
          <button
            key={key}
            onClick={() => onPick(key)}
            title={label}
            aria-selected={on}
            role="tab"
            style={{
              display: "inline-flex", alignItems: "center", gap: "6px", flexShrink: 0,
              background: "transparent", border: "none",
              borderBottom: `2px solid ${on ? "#A855F7" : "transparent"}`,
              marginBottom: "-1px",
              padding: isDesktop ? "0 0 9px" : "0 0 10px",
              color: on ? "#171717" : "#A1A1AA",
              cursor: "pointer", whiteSpace: "nowrap",
              fontFamily: "'Geist', sans-serif",
              fontSize: isDesktop ? "13.5px" : "14.5px",
              fontWeight: 500,
            }}
          >
            {Icon && <Icon size={14} strokeWidth={1.9} style={{ flexShrink: 0 }} />}
            {label}
            {/* A count only where there is something to count, so empty tabs
                stay quiet and six of them never read as clutter. */}
            {typeof count === "number" && count > 0 && (
              <span style={{
                fontFamily: "'Geist Mono', monospace",
                fontSize: isDesktop ? "10.5px" : "11px", fontWeight: 500,
                color: on ? "#A855F7" : "#C4C4C8",
              }}>
                {count}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

function uploadsOfKind(fields: any, kind: string): any[] {
  const all = Array.isArray(fields?.uploads) ? fields.uploads : [];
  const known = Object.keys(FILE_KIND_FIELDS);
  if (kind === "Raw footage") {
    return all.filter((u: any) => {
      const n = String(u?.label || "");
      return n.startsWith(kind) || !known.some((k) => n.startsWith(k));
    });
  }
  return all.filter((u: any) => String(u?.label || "").startsWith(kind));
}

