// Pull a freshly-created record's id out of the datasource response.
function newRecordId(data: any): string | null {
  return data?.record?.id || data?.id || (data?.records?.[0]?.id) || null;
}
// A promise with a deadline: past it, the fallback. The original keeps running.
function withTimeout<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {
  return new Promise((resolve) => {
    let settled = false;
    const timer = setTimeout(() => { if (!settled) { settled = true; resolve(fallback); } }, ms);
    p.then(
      (v) => { if (!settled) { settled = true; clearTimeout(timer); resolve(v); } },
      () => { if (!settled) { settled = true; clearTimeout(timer); resolve(fallback); } },
    );
  });
}
// Wrap a useRecordCreate mutate in a promise that resolves the new id.
function createRecordAsync(hook: any, fields: any): Promise<string | null> {
  return new Promise((resolve) => {
    hook.mutate(fields, {
      onSuccess: (d: any) => resolve(newRecordId(d)),
      onError: () => resolve(null),
    });
  });
}

