// ── Card templates (Karen, 2026-10-06) ─────────────────────────────────────
// A template decides which sections a new card has, in what order, and what
// each one starts with. One record per template in "Card Templates", shared
// by the whole workspace. A new template is a blank page with only its name,
// and sections are added one at a time, the way blocks go on a Notion page.
// Sections is JSON, for example
//   [{"key":"script","prefill":""},{"key":"slides","count":3,"prefill":["","",""]}]
// Default marks the one Create and every column's New card start from (none
// means the blank canvas). An archived template leaves the menus, but cards
// made from it keep its sections.
type TemplateSectionKey = "slides" | "visualHook" | "textOverlay" | "itemsOverlay" | "script"
  | "shootingInstructions" | "notes" | "inspoLink" | "captions";
type TemplateSection = { key: TemplateSectionKey; prefill: any; count?: number };
type CardTemplate = {
  id: string; name: string; contentType: string; sections: TemplateSection[];
  isDefault: boolean; active: boolean;
};
// Karen's set, in her order. Visual Hook and Items Overlay are used at
// editing time, Text Overlay and Script at planning time.
const TEMPLATE_SECTIONS: { key: TemplateSectionKey; label: string; hint: string; Icon: any }[] = [
  { key: "slides", label: "Slides Copy", hint: "The copy for each slide, 1 to 10", Icon: Layers },
  { key: "visualHook", label: "Visual Hook", hint: "The hook shown on screen", Icon: Eye },
  { key: "textOverlay", label: "Text Overlay", hint: "The text on screen over B-roll", Icon: TextIcon },
  { key: "itemsOverlay", label: "Items Overlay", hint: "A call-out for each item, step or tutorial step", Icon: ListOrdered },
  { key: "script", label: "Script", hint: "What you say on camera", Icon: FileText },
  { key: "shootingInstructions", label: "Shooting Instructions", hint: "How to film it", Icon: Camera },
  { key: "notes", label: "Notes", hint: "Anything else the team should know", Icon: StickyNote },
  { key: "inspoLink", label: "Inspo Link", hint: "A post that inspired it", Icon: LinkIcon },
  { key: "captions", label: "Captions", hint: "One each for Instagram, TikTok, LinkedIn and Facebook", Icon: MessageSquare },
];
const templateSectionLabel = (key: string) => TEMPLATE_SECTIONS.find((s) => s.key === key)?.label || key;
// Where each single-text section is kept on a card (field-map keys).
const TEMPLATE_FIELD: Record<string, string> = {
  visualHook: "visualHook", textOverlay: "textOverlay", itemsOverlay: "itemsOverlay", script: "body",
  shootingInstructions: "shootingInstructions", notes: "creativeInstructions", inspoLink: "inspoLinkInput",
};
const CAPTION_PLATFORM_NAMES = ["Instagram", "TikTok", "LinkedIn", "Facebook"];
// Read leniently: an unknown key or a repeat is dropped, never shown.
function parseTemplateSections(raw: any): TemplateSection[] {
  let list: any = [];
  const text = String(raw || "").trim();
  try { list = JSON.parse(text || "[]"); } catch {
    try { list = JSON.parse(stripRichText(text) || "[]"); } catch { list = []; }
  }
  if (!Array.isArray(list)) return [];
  const known = TEMPLATE_SECTIONS.map((s) => s.key as string);
  const seen = new Set<string>();
  const out: TemplateSection[] = [];
  for (const s of list) {
    const key = String(s?.key || "") as TemplateSectionKey;
    if (!known.includes(key) || seen.has(key)) continue;
    seen.add(key);
    if (key === "slides") {
      const count = Math.min(10, Math.max(1, parseInt(String(s.count || 1), 10) || 1));
      const pre = Array.isArray(s.prefill) ? s.prefill : [];
      out.push({ key, count, prefill: Array.from({ length: count }, (_, i) => String(pre[i] ?? "")) });
    } else if (key === "captions") {
      const pre = s.prefill && typeof s.prefill === "object" ? s.prefill : {};
      out.push({ key, prefill: Object.fromEntries(CAPTION_PLATFORM_NAMES.map((p) => [p, String(pre[p] ?? "")])) });
    } else {
      out.push({ key, prefill: String(s.prefill ?? "") });
    }
  }
  return out;
}
// Slides keep the text of slides past the count while the template is open,
// so going from 5 to 3 and back loses nothing. Only the counted ones save.
const serializeTemplateSections = (list: TemplateSection[]) => JSON.stringify(list.map((s) => (
  s.key === "slides"
    ? { key: s.key, count: s.count, prefill: (s.prefill || []).slice(0, s.count || 1) }
    : { key: s.key, prefill: s.prefill })));
function templateFromRow(r: any): CardTemplate {
  const f = r?.fields || {};
  return {
    id: String(r?.id || ""),
    name: String(f.name || "").trim(),
    contentType: labelOf(f.contentType),
    sections: parseTemplateSections(f.sections),
    isDefault: !!f.isDefault,
    active: labelOf(f.status) !== "Archived",
  };
}
const templateDisplayName = (t: { name: string } | null | undefined) => (t?.name || "").trim() || "Untitled template";
// The section that takes the words typed into the blank canvas when a card
// starts from a template: the copy's home first, so a pasted script lands in
// Script, then the slides, and so on. Notes when the template has none.
const TEMPLATE_TEXT_HOME: TemplateSectionKey[] = [
  "script", "slides", "textOverlay", "notes", "itemsOverlay", "shootingInstructions", "visualHook", "captions",
];
// A new card's fields from a template: every section's starting text, plus
// the typed words added after the starting text of their home section.
function templateCardFields(t: CardTemplate, words: string): any {
  const out: any = { cardTemplate: [t.id] };
  for (const s of t.sections) {
    if (s.key === "slides") {
      const n = s.count || 1;
      out.slidesCount = `${n} ${n === 1 ? "Slide" : "Slides"}`;
      (s.prefill as string[]).forEach((p, i) => { if (String(p || "").trim()) out[`slide${i + 1}Copy`] = p; });
    } else if (s.key === "captions") {
      CAPTION_PLATFORMS.forEach((p) => { const v = String(s.prefill?.[p.name] || ""); if (v.trim()) out[p.key] = v; });
    } else if (String(s.prefill || "").trim()) {
      out[TEMPLATE_FIELD[s.key]] = s.prefill;
    }
  }
  if (words) {
    const home = TEMPLATE_TEXT_HOME.find((k) => t.sections.some((s) => s.key === k)) || "notes";
    const field = home === "slides" ? "slide1Copy" : home === "captions" ? "captionsInstagram" : TEMPLATE_FIELD[home];
    out[field] = out[field] ? `${out[field]}\n\n${words}` : words;
  }
  return out;
}
