const SOFTR_NAV_OFFSET = "80px";

// iOS installed-PWA strip. Softr's page viewport tag has no
// `viewport-fit=cover`, so iOS keeps the page above the home indicator and
// fills that strip itself. Rewriting the viewport tag at runtime does NOT
// work — iOS won't re-read it after load — so nothing inside the block can
// draw into it. What iOS DOES use is the page background colour, so a
// full-screen panel tints the page to match itself and the strip disappears
// into the design. Restored on close.
//
// The permanent fix is one line of custom head code on the Softr page:
//   <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
// What iOS says is actually on screen right now. Layout units (vh, dvh,
// inset:0) measure the LAYOUT viewport, which does not shrink while Safari's
// chrome is showing, so a bottom sheet trusting them sits too low.
function useVisualViewport() {
  const [vv, setVv] = useState<{ h: number; top: number } | null>(null);
  useEffect(() => {
    const vp = (window as any).visualViewport;
    if (!vp) return;
    const read = () => setVv({ h: vp.height, top: vp.offsetTop });
    read();
    vp.addEventListener("resize", read);
    vp.addEventListener("scroll", read);
    return () => { vp.removeEventListener("resize", read); vp.removeEventListener("scroll", read); };
  }, []);
  return vv;
}

function usePageBackdrop(color: string | null) {
  useEffect(() => {
    if (!color) return;
    const body = document.body;
    const html = document.documentElement;
    const prevBody = body.style.backgroundColor;
    const prevHtml = html.style.backgroundColor;
    const themeMeta = document.querySelector('meta[name="theme-color"]') as HTMLMetaElement | null;
    const prevTheme = themeMeta?.content ?? null;
    body.style.backgroundColor = color;
    html.style.backgroundColor = color;
    if (themeMeta) themeMeta.content = color;
    return () => {
      body.style.backgroundColor = prevBody;
      html.style.backgroundColor = prevHtml;
      if (themeMeta && prevTheme !== null) themeMeta.content = prevTheme;
    };
  }, [color]);
}

// ── One way in and out of every sheet ──────────────────────────────────────
// The rule, so no two dialogs disagree: a BARE back chevron on the left when
// there is a step behind you, a CIRCLED ✕ on the right when there isn't.
// Never both. Tapping the scrim always closes as well.
function SheetCloseButton({
  onClick, isDesktop = false, label = "Close",
}: { onClick: () => void; isDesktop?: boolean; label?: string }) {
  return (
    <button
      onClick={onClick}
      aria-label={label}
      style={{
        width: isDesktop ? "30px" : "32px", height: isDesktop ? "30px" : "32px",
        borderRadius: "50%", flexShrink: 0, padding: 0,
        background: "white", border: "1px solid #EDEDED", color: "#737373",
        cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center",
      }}
    >
      <X size={isDesktop ? 15 : 16} strokeWidth={2} />
    </button>
  );
}
function SheetBackButton({
  onClick, isDesktop = false, disabled = false,
}: { onClick: () => void; isDesktop?: boolean; disabled?: boolean }) {
  return (
    <button
      onClick={onClick}
      aria-label="Back"
      disabled={disabled}
      style={{
        width: "28px", height: "28px", marginLeft: "-6px", flexShrink: 0, padding: 0,
        background: "transparent", border: "none", color: "#171717",
        cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? 0.35 : 1,
        display: "inline-flex", alignItems: "center", justifyContent: "center",
      }}
    >
      <ChevronLeft size={isDesktop ? 18 : 20} strokeWidth={2} />
    </button>
  );
}

// The overflow (⋯ / ⋮) menu — one list, used identically on expanded cards,
// table rows and inside the script modal. Trimmed to what actually applies at
// the scripting stage; editing / design / post-setup actions live downstream
// in the Production block.
type CreativeEntry = {
  label: string; icon: any; onClick: () => void;
  danger?: boolean; disabled?: boolean;
  // A rule across the list rather than a row of its own.
  divider?: boolean;
  // A choice list (Group by on the phone): a purple tick on the picked row
  // and a quiet line under the label.
  checked?: boolean; desc?: string;
};
// ── What a card can do, per format and per state ──────────────────────────
// Karen's "Cards visibility" sheet. Formats fall into four behaviour groups,
// and a card is in one of three states — that pair decides every button.
//
// AIRTABLE's exact Format names — audited against the live field 2026-09-03,
// after Karen aligned the dropdown to the Formats table (23 options; the
// Formats table's "Collaboration" has no option on purpose). The record is
// what arrives at runtime, so the record wins over the spec sheet wherever
// they differ. Still trimmed on comparison: "Meme" carried a trailing space
// for a while and that class of typo is invisible until something breaks.
const RECORD_FIRST_FORMATS = [
  "Talking Head", "Reaction", "Mini-vlog", "Skit",
  "Tutorial", "Silent Tutorial", "Silent Mini-vlog",
  // The voiceover is recorded in the teleprompter's audio mode, so the card
  // behaves like a talking head you don't appear in (Body = voiceover script).
  "BROLL & Voiceover",
];
const POST_FIRST_FORMATS = ["Loop Broll", "Lip-sync trend", "Trending template"];
// Cut from footage that already exists — there is nothing to shoot, so Shoot
// plan and Record are offered but disabled rather than hidden.
const CLIP_ONLY_FORMATS = ["Long form clips", "Movie & TV clips"];
// Graphics are matched by NAME, off the shared GRAPHIC_FORMATS list above.
// Content Type is only the fallback: a record with an empty Content Type was
// otherwise treated as a video and got the wrong buttons.
type FormatGroup = "recordFirst" | "postFirst" | "clipOnly" | "graphic";
function formatGroupOf(item: any): FormatGroup {
  const f = String(item?.fields?.format?.label || "").trim();
  if (GRAPHIC_FORMATS.includes(f)) return "graphic";
  if (RECORD_FIRST_FORMATS.includes(f)) return "recordFirst";
  if (POST_FIRST_FORMATS.includes(f)) return "postFirst";
  if (CLIP_ONLY_FORMATS.includes(f)) return "clipOnly";
  if (isGraphicItem(item)) return "graphic";
  // An unrecognised video format behaves like the common case rather than
  // losing its buttons — a new Airtable option shouldn't break the board.
  return "recordFirst";
}

// ── What a card SHOWS, per format ─────────────────────────────────────────
// Also from the spec sheet. Several "new" fields are existing ones under a
// different name, per Karen: Text overlay IS the Script field, Cover headline
// IS the On-screen hook, and a still graphic's Design brief IS Slide 1 copy.
// Straight off the card-visibility sheet: the spoken hook and the on-screen
// call to action only appear where they earn a place.
const FORMATS_WITH_SPOKEN_HOOK = [
  "Talking Head", "Mini-vlog", "Tutorial", "Silent Tutorial", "Silent Mini-vlog",
  "BROLL & Voiceover",
];
const FORMATS_WITH_VISUAL_CTA = [
  "Talking Head", "Tutorial", "Silent Tutorial", "Loop Broll", "Long form clips",
  "BROLL & Voiceover",
];
const TEXT_OVERLAY_FORMATS = [
  "Loop Broll", "Lip-sync trend", "Trending template", "Movie & TV clips",
];

// ── Which formats show which content field ────────────────────────────────
// DERIVED from the lists above, never hand-written, so renaming a format can
// never again silently delete the box the user typed into. Each one mirrors
// what the CARD already renders, so compose / modal / card always agree:
//   FORMATS_WITH_SCRIPT  ↔ expandedCardFields' "Script" row
//   ..._TEXT_OVERLAY     ↔ cardTitleSpec's "Text overlay" title
//   ..._VISUAL_HOOK      ↔ cardTitleSpec's "On-screen hook" title
// Script and Text overlay are the SAME Airtable field (Body) — per the spec
// sheet, a post-first format's on-screen text IS its script.
const FORMATS_WITH_SCRIPT = new Set(RECORD_FIRST_FORMATS);
const FORMATS_WITH_TEXT_OVERLAY = new Set(TEXT_OVERLAY_FORMATS);
const FORMATS_WITH_VISUAL_HOOK = new Set(
  VIDEO_FORMATS.filter((f) => !TEXT_OVERLAY_FORMATS.includes(f)),
);

// The card's headline: which field it comes from and what it's called.
function cardTitleSpec(item: any): { label: string; value: string } {
  const f = String(item?.fields?.format?.label || "").trim();
  const fields = item?.fields || {};
  const custom = stripRichText(fields.customPostName);
  if (TEXT_OVERLAY_FORMATS.includes(f)) {
    return { label: "Text overlay", value: custom || stripRichText(fields.body) };
  }
  if (formatGroupOf(item) === "graphic") {
    return { label: "Cover title", value: custom || stripRichText(fields.visualHook) };
  }
  return { label: "On-screen hook", value: custom || stripRichText(fields.visualHook) };
}

// One row of the expanded card. `lines` is the clamp from the sheet.
type CardField = { label: string; value: string; lines: number };
function expandedCardFields(item: any): CardField[] {
  const f = String(item?.fields?.format?.label || "").trim();
  const x = item?.fields || {};
  const group = formatGroupOf(item);
  const val = (v: any) => stripRichText(v) || "";
  const caption = val(x.captionsInstagram) || val(x.captionsTikTok);
  const topicCat = x.topicCategory?.label || "";
  const script = { label: "Script", value: val(x.body), lines: 5 };
  const shootNotes = { label: "Shooting instructions", value: val(x.shootingInstructions), lines: 3 };

  let rows: CardField[];
  if (group === "graphic") {
    // Still graphic calls Slide 1 its design brief; a carousel calls it what
    // it is, because slide 2 onwards follow it. Delivery Style is empty on
    // every live record, so the slide count decides when it isn't set.
    const slides = parseInt(String(x.slidesCount?.label || "").trim(), 10);
    const carousel = String(x.deliveryStyle?.label || "") === "Carousel"
      || (Number.isFinite(slides) && slides > 1);
    rows = [
      { label: "Topic category", value: topicCat, lines: 2 },
      // "Slide 1 Copy" is the Airtable field name; on screen a carousel's
      // first slide is just the graphic copy.
      { label: carousel ? "Slide 1 copy" : "Design brief", value: val(x.slide1Copy), lines: 5 },
      { label: "Notes", value: val(x.creativeInstructions), lines: 3 },
    ];
  } else if (group === "clipOnly") {
    // Cut from footage that exists: the caption and where to cut, not a script.
    rows = [
      { label: "Caption", value: caption, lines: 5 },
      { label: "Timestamps", value: val(x.timestamps), lines: 3 },
    ];
  } else if (f === "Reaction") {
    rows = [
      { label: "Video to react to", value: val(x.videoToReactLink), lines: 2 },
      script,
      shootNotes,
    ];
  } else if (f === "Loop Broll") {
    rows = [{ label: "Caption", value: caption, lines: 5 }, shootNotes];
  } else if (f === "Lip-sync trend" || f === "Trending template") {
    rows = [{ label: "Inspo", value: val(x.inspoLinkInput), lines: 2 }, shootNotes];
  } else {
    // Talking Head, Mini-vlog, Skit, Tutorial, Silent Tutorial, Silent Mini-vlog.
    rows = [{ label: "Topic category", value: topicCat, lines: 2 }, script, shootNotes];
  }
  return rows.filter((r) => r.value && r.value.trim());
}

// Has this actually been shot? The SHOOTING STATUS is the answer, and it is
// what turns a card's outline from red to green. Two things set it: recording
// or attaching a capture file, and "Complete shoot" on the filming day.
//
// Real footage counts on its own as a SAFETY NET. If a status write ever fails
// to land, a card that plainly has footage against it must never sit there
// looking unshot. Being booked into a day is not enough, and a reference file
// attached while drafting is not footage.
const SHOT_STATUSES = ["Shot Taken", "Sent to Post Production"];
// LEGACY prefixes. Uploads written before the split were named "Kind · file";
// new ones are not, so this is only a fallback for those older rows.
const CAPTURE_FILE_KINDS = ["Raw footage", "Edited videos", "Voiceover", "Designed slides"];
const CAPTURE_FILE_TYPES = ["Video", "Audio"];
const hasTake = (item: any) => {
  const shooting = String(item?.fields?.shootingStatus?.label || "").trim();
  if (SHOT_STATUSES.includes(shooting)) return true;
  if (item?.fields?.shotDate) return true;
  const u = item?.fields?.uploads;
  const list = Array.isArray(u) ? u : (u ? [u] : []);
  return list.some((x: any) =>
    (CAPTURE_FILE_TYPES.includes(fileTypeOf(String(x?.label || "")))
      || CAPTURE_FILE_KINDS.some((k) => String(x?.label || "").startsWith(k))));
};
// The filmed material actually on the card. Unlike hasTake, the shooting
// status and shot date do not count, because this is what decides where a
// card goes once it is shot: with material it moves on to To Edit or To
// Design, without it it waits in Attach Media (Karen 2026-09-27). A static
// post's material is its photos, so images count for those.
function hasFootage(item: any): boolean {
  const u = item?.fields?.uploads;
  const list = Array.isArray(u) ? u : (u ? [u] : []);
  return list.some((x: any) =>
    (isMaterialType(fileTypeOf(String(x?.label || "")), item)
      || CAPTURE_FILE_KINDS.some((k) => String(x?.label || "").startsWith(k))));
}
function isMaterialType(fileType: string, item: any): boolean {
  return CAPTURE_FILE_TYPES.includes(fileType) || (fileType === "Image" && isStaticItem(item));
}
// A filming day sits in one of three stages, read straight off its status.
// "Complete shoot" moves it to Ready for Production; only actually sending
// the scripts on moves it to Completed. Those two used to be one irreversible
// step, which is why there was nowhere to stand in between.
//
// MODULE scope on purpose: renderCalendar is defined above where these used to
// sit inside the component, so it read them before they were declared. That
// only worked because renderCalendar is called later, and this file has been
// bitten by exactly that pattern before.
type SessionStage = "toShoot" | "ready" | "done";
function sessionStageOf(s: any): SessionStage {
  const st = String(s?.fields?.status?.label || "");
  if (st === "Completed") return "done";
  if (st === "Ready for Production") return "ready";
  return "toShoot";
}
const sessionDone = (s: any) => sessionStageOf(s) === "done";
// Shot, whether or not it has been handed on. Nothing left to film.
const sessionShot = (s: any) => sessionStageOf(s) !== "toShoot";

type CardState = "drafts" | "plan" | "done" | "post";
// The three states run in order, so "done" is reached THROUGH the shoot plan.
// A draft with a reference file attached is still a draft.
function cardStateOf(item: any, inSession: boolean): CardState {
  // SHOOTING STATUS decides, because that is what the card-behaviour sheet is
  // written against. Reading the phase status and "is it in a filming day"
  // instead meant a card could be Sent to Post Production and still show the
  // buttons of one that was merely booked.
  const shooting = String(item?.fields?.shootingStatus?.label || "").trim();
  if (shooting === "Sent to Post Production") return "post";
  if (shooting === "Shot Taken") return "done";
  if (shooting === "To Shoot") return "plan";
  // Fallbacks for records written before the shooting status drove this, so
  // an older card never loses its buttons.
  if (String(item?.fields?.status?.label || "") === "Post Production") return "post";
  if (inSession) return hasTake(item) ? "done" : "plan";
  return "drafts";
}

function buildOverflowActions(
  item: any,
  h: {
    onRename: () => void;
    onFilm: () => void;
    onRefine: () => void;
    onAttachFile: () => void;
    onBackToDrafts: () => void;
    // Only offered inside a shoot: there is nothing to move out of otherwise.
    onRescheduleShoot?: () => void;
    // "Back to shoot" — un-shoots a shot/sent card back to the shoot plan.
    onMarkPending?: () => void;
    // "Mark as shot": filmed outside the app. With footage it goes on to To
    // Edit or To Design, without it it waits in Attach Media (Karen 2026-09-28).
    onMarkShot?: () => void;
  undatedShoot?: boolean;
    onAddToShootPlan: () => void;
    onAddToPostProduction: () => void;
    onDownloadPdf: () => void;
    onRestore: () => void;
    onDiscard: () => void;
    onCreativeSuite: () => void;
  },
  // `undatedShoot` — the shoot this card sits in has no day yet, so the menu
  // offers Schedule (picking a day for the first time) rather than Reschedule.
  ctx?: { state?: CardState; undatedShoot?: boolean },
): CreativeEntry[] {
  const group = formatGroupOf(item);
  const graphic = group === "graphic";
  const state = ctx?.state || "drafts";
  // This row opens the CAMERA on a graphic, so it must not say "Attach file".
  // Picking an existing file is a separate row further down.
  const captureLabel = graphic ? "Take photo" : "Record";
  const captureIcon = graphic ? Camera : Video;
  // Attach file is a card BUTTON only where the sheet puts it there; the menu
  // carries it everywhere else, so it is always reachable and never doubled.
  // Working this out per branch is what once left a graphic draft unable to
  // attach anything at all.
  const attachIsAButton = (state === "drafts" && group === "clipOnly") // "Re-select Clips"
    || (state === "done" && !hasFootage(item)); // "Attach Media"
  const attachRow: CreativeEntry = { label: "Attach file", icon: Paperclip, onClick: h.onAttachFile };
  // Renaming is done by tapping the title in the open script, so it is not
  // repeated here.
  const rows: CreativeEntry[] = [];
  const markShotRow: CreativeEntry[] = h.onMarkShot
    ? [{ label: "Mark as shot", icon: Clapperboard, onClick: h.onMarkShot }]
    : [];
  if (state === "plan") {
    // Booked, not yet shot: it can be marked shot, the day can still be moved,
    // and it can go back to drafts.
    rows.push(...markShotRow);
    if (h.onRescheduleShoot) {
      rows.push({
        label: ctx?.undatedShoot ? "Schedule shoot" : "Reschedule shoot",
        icon: Calendar,
        onClick: h.onRescheduleShoot,
      });
    }
    rows.push({ label: "Back to Drafts", icon: ArrowLeft, onClick: h.onBackToDrafts });
  } else if (state === "done") {
    // Shot: no rescheduling — the only way back is to the shoot plan.
    if (h.onMarkPending) {
      rows.push({ label: "Back to shoot", icon: RotateCcw, onClick: h.onMarkPending });
    }
    rows.push({ label: "Back to Drafts", icon: ArrowLeft, onClick: h.onBackToDrafts });
  } else if (state === "post") {
    // In the Studio: no rescheduling; Back to shoot is a card button; Back to
    // Drafts is disabled because it has already left the shoot plan.
    rows.push({ label: "Back to Drafts", icon: ArrowLeft, onClick: h.onBackToDrafts, disabled: true });
  } else if (group === "clipOnly") {
    // Nothing to shoot — both shooting actions show, greyed, so it is clear
    // they do not apply rather than mysteriously missing.
    rows.push(
      { label: "Refine", icon: Sparkles, onClick: h.onRefine },
      { label: "Queue Shoot", icon: Calendar, onClick: h.onAddToShootPlan, disabled: true },
      { label: captureLabel, icon: captureIcon, onClick: h.onFilm, disabled: true },
    );
  } else if (graphic) {
    // Its buttons are Queue Design + Refine, so the menu carries the two
    // moves that are not there.
    rows.push(
      { label: captureLabel, icon: captureIcon, onClick: h.onFilm },
      ...markShotRow,
      { label: "Queue Shoot", icon: Calendar, onClick: h.onAddToShootPlan },
    );
  } else {
    // Video draft: buttons are Queue Shoot + Refine.
    rows.push(
      { label: captureLabel, icon: captureIcon, onClick: h.onFilm },
      ...markShotRow,
      { label: "Queue Edit", icon: Palette, onClick: h.onAddToPostProduction },
    );
  }
  if (!attachIsAButton) rows.push(attachRow);
  rows.push(
    { label: "Download as PDF", icon: FileText, onClick: h.onDownloadPdf },
    // Everything under the line rewrites or removes the script itself.
    { label: "divider", icon: null, onClick: () => { /* noop */ }, divider: true },
    { label: "Restore previous versions", icon: RotateCcw, onClick: h.onRestore, disabled: !hasPriorVersions(item) },
    { label: "Discard", icon: Trash2, onClick: h.onDiscard, danger: true },
  );
  return rows;
}

// The two buttons on a card, in both places a card is drawn (grid + list).
// Per Karen's sheet: a draft that will be shot books the day first; one that
// only needs designing goes straight to post production; a clip cut from old
// footage can do neither. Inside a filming day the capture always leads.
type CardCta = { label: string; busyLabel?: string; icon: any; onClick: () => void; disabled?: boolean };
function buildCardCtas(
  item: any,
  state: CardState,
  h: {
    onAddToShootPlan: () => void;
    onFilm: () => void;
    onAddToPostProduction: () => void;
    onRefine: () => void;
    onMarkPending: () => void;
    onAttachFile: () => void;
  },
): { primary: CardCta; secondary?: CardCta } {
  const group = formatGroupOf(item);
  const graphic = group === "graphic";
  // Queue Edit for a video, Queue Design for a graphic (Karen 2026-09-14).
  const post: CardCta = {
    label: graphic ? "Queue Design" : "Queue Edit", busyLabel: "Sending…", icon: Palette,
    onClick: h.onAddToPostProduction,
  };
  // Booking a day is a calendar action, always — it never changes with format.
  const plan: CardCta = {
    label: "Queue Shoot", busyLabel: "Adding…", icon: Calendar,
    onClick: h.onAddToShootPlan,
  };
  const refine: CardCta = { label: "Refine", icon: Sparkles, onClick: h.onRefine };
  // A graphic's capture opens the CAMERA, so the button says so.
  const shotAlready = state === "done" || state === "post";
  const capture: CardCta = graphic
    ? { label: shotAlready ? "Take another" : "Take Photo", icon: Camera, onClick: h.onFilm }
    : { label: shotAlready ? "Record another" : "Record", icon: Video, onClick: h.onFilm };

  // ── The four branches below are the columns of the card-behaviour sheet. ──

  // Sent to Post Production: the only move left is to pull it back, so this is
  // the one card that carries a single button.
  if (state === "post") {
    return {
      primary: capture,
      secondary: { label: "Back to Shoot", busyLabel: "Updating…", icon: RotateCcw, onClick: h.onMarkPending },
    };
  }
  // Shot with nothing attached: it waits in Attach Media, so attaching the
  // footage leads (Karen 2026-09-27).
  if (state === "done" && !hasFootage(item)) {
    return {
      primary: { label: "Attach Media", icon: Paperclip, onClick: h.onAttachFile },
      secondary: graphic
        ? { label: "Take Photo", icon: Camera, onClick: h.onFilm }
        : { label: "Record", icon: Video, onClick: h.onFilm },
    };
  }
  // To Shoot, then Shot Taken. Capture leads in both; `capture` already reads
  // "Record another" / "Take another" once something has been shot.
  if (state === "plan" || state === "done") return { primary: capture, secondary: post };

  // Drafts. A clip is cut from footage that already exists, so it never books
  // a shoot: its second move is choosing different clips.
  if (group === "clipOnly") {
    return {
      primary: post,
      secondary: { label: "Re-select Clips", icon: Scissors, onClick: h.onAttachFile },
    };
  }
  // A graphic is designed, not filmed, so it goes straight to the studio.
  if (graphic) return { primary: post, secondary: refine };
  // Video: book the day first.
  return { primary: plan, secondary: refine };
}

// Download as PDF — builds a clean print sheet from the saved record and hands
// it to the browser's own print dialog, where "Save as PDF" / "Save to Files"
// is the destination. No backend needed; works on iOS Safari. One script or a
// whole filming day go through the same builder — a day is just the same
// sections one after another with a page break between.
function scriptPdfSection(item: any): string {
  const f = item.fields || {};
  const esc = (s: any) => String(s || "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const linkLabel = (v: any) => {
    const one = Array.isArray(v) ? v[0] : v;
    return stripRichText(one?.label) || "";
  };
  const graphic = isGraphicItem(item);
  const details: [string, string][] = ([
    ["Content type", f.deliveryStyle?.label || f.contentType?.label || ""],
    ["Format", f.format?.label || ""],
    ["Angle", f.angle?.label || ""],
    ["Topic category", linkLabel(f.topicCategory)],
    ["Topic", linkLabel(f.topic)],
    [graphic ? "Slides" : "Duration", graphic ? (f.slidesCount?.label || "") : formatDuration(f.duration)],
  ] as [string, string][]).filter(([, v]) => v && v.trim());

  const slides = [
    f.slide1Copy, f.slide2Copy, f.slide3Copy, f.slide4Copy, f.slide5Copy,
    f.slide6Copy, f.slide7Copy, f.slide8Copy, f.slide9Copy, f.slide10Copy,
  ].map(stripRichText).filter((t) => t && t.trim()).join("\n");

  const blocks: [string, string][] = ([
    ["On-screen hook", stripRichText(f.visualHook)],
    ["Hook", stripRichText(f.hook)],
    ["Script", stripRichText(f.body)],
    [graphic ? "Slides copy" : "", slides],
    ["Timestamps", stripRichText(f.timestamps)],
    ["Shooting instructions", stripRichText(f.shootingInstructions)],
    ["Instagram captions", stripRichText(f.captionsInstagram)],
    ["TikTok captions", stripRichText(f.captionsTikTok)],
    ["LinkedIn captions", stripRichText(f.captionsLinkedIn)],
    ["Facebook captions", stripRichText(f.captionsFacebook)],
  ] as [string, string][]).filter(([k, v]) => k && v && v.trim());

  return `<h1>${esc(getCardHeading(item))}</h1>
<table>${details.map(([k, v]) => `<tr><td class="k">${esc(k)}</td><td>${esc(v)}</td></tr>`).join("")}</table>
${blocks.map(([k, v]) => `<h2>${esc(k)}</h2><p>${esc(v)}</p>`).join("") || "<p>This script is still empty.</p>"}`;
}

// Wrap sections in a print document and hand it to the browser's print dialog.
function openPrintDoc(title: string, body: string) {
  const esc = (s: any) => String(s || "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const html = `<!doctype html><html><head><meta charset="utf-8"/>
<title>${esc(title)}</title>
<style>
  @page { margin: 18mm; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
         color: #171717; line-height: 1.55; margin: 0; }
  h1 { font-size: 22px; margin: 0 0 14px; }
  table { border-collapse: collapse; margin: 0 0 22px; }
  td { padding: 3px 0; font-size: 12px; vertical-align: top; }
  td.k { color: #737373; text-transform: uppercase; letter-spacing: 0.08em;
         padding-right: 18px; white-space: nowrap; }
  h2 { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em;
       color: #737373; margin: 22px 0 6px; font-weight: 600; }
  p { font-size: 14px; margin: 0; white-space: pre-wrap; }
  .brk { page-break-before: always; }
</style></head><body>
${body}
</body></html>`;

  const frame = document.createElement("iframe");
  frame.setAttribute("aria-hidden", "true");
  frame.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0;opacity:0;";
  document.body.appendChild(frame);
  const doc = frame.contentWindow?.document;
  if (!doc) { document.body.removeChild(frame); errorToast("Couldn't build the PDF."); return; }
  doc.open();
  doc.write(html);
  doc.close();
  const run = () => {
    try { frame.contentWindow?.focus(); frame.contentWindow?.print(); }
    catch { errorToast("Couldn't open the print sheet."); }
    setTimeout(() => { try { document.body.removeChild(frame); } catch { /* noop */ } }, 60000);
  };
  if (doc.readyState === "complete") setTimeout(run, 60);
  else frame.onload = () => setTimeout(run, 60);
}
function printScriptPdf(item: any) {
  openPrintDoc(getCardHeading(item), scriptPdfSection(item));
}
// Every script in a filming day, one after another in a single document.
function printScriptsPdf(items: any[], title: string) {
  if (!items.length) { errorToast("There are no scripts in this shoot yet."); return; }
  const body = items
    .map((it, i) => (i === 0 ? scriptPdfSection(it) : `<div class="brk"></div>${scriptPdfSection(it)}`))
    .join("\n");
  openPrintDoc(title, body);
}
// "Restore previous versions" only means anything when older copies exist:
// PRIOR versions hang off Parent Record, not Child Record. Verified against
// the live data: a refined script is Active and points BACK at the originals
// through Parent Record, while those originals are Deprecated and point
// FORWARD at it through Child Record. This read childRecord, so the menu row
// was disabled on exactly the scripts that have history, and enabled on the
// deprecated ones nobody opens.
const priorVersionLinks = (item: any) => {
  const c = item?.fields?.parentRecord;
  return Array.isArray(c) ? c.filter(Boolean) : (c ? [c] : []);
};
const hasPriorVersions = (item: any) => priorVersionLinks(item).length > 0;

// "1m 30s" / "90s" / "90" → seconds. Returns null when unparseable.
function parseDurationInput(text: string): number | null {
  const t = String(text || "").trim().toLowerCase();
  if (!t) return null;
  const mObj = t.match(/^(?:(\d+)\s*m)?\s*(?:(\d+)\s*s?)?$/);
  if (!mObj || (!mObj[1] && !mObj[2])) return null;
  const mins = mObj[1] ? parseInt(mObj[1], 10) : 0;
  const secs = mObj[2] ? parseInt(mObj[2], 10) : 0;
  const total = mins * 60 + secs;
  return total > 0 ? total : null;
}

