// Our kind names are not Airtable's option names. Note the capital F on
// "Raw Footage" and that there is no "slides" option, only Carousel/Graphic.
// The four things a file can BE. What a script USES it for is a separate
// question, answered later on Script Files > Used as — asking at upload time
// meant answering it twice, and the answer could only ever be one value.
const FILE_TYPES = ["Video", "Audio", "Image", "Document"] as const;
const FILE_TYPE_ICON: Record<string, any> = {
  Video: Video, Audio: Mic, Image: Image, Document: FileText,
};
// Tabs read in plural; the Airtable option is singular.
const FILE_TYPE_TABS: { kind: string; label: string; Icon: any }[] = [
  { kind: "Video", label: "Videos", Icon: Video },
  { kind: "Audio", label: "Audio", Icon: Mic },
  { kind: "Image", label: "Images", Icon: Image },
  { kind: "Document", label: "Documents", Icon: FileText },
];
const EXT_VIDEO = /\.(mp4|mov|m4v|webm|avi|mkv)$/i;
const EXT_AUDIO = /\.(m4a|mp3|wav|aac|ogg|flac)$/i;
const EXT_IMAGE = /\.(png|jpe?g|gif|webp|heic|heif|avif|svg|bmp)$/i;
// MIME first, because it is what the browser actually knows; the extension is
// the fallback for a file that arrives without one.
function fileTypeOf(name: string, mime?: string): string {
  const m = String(mime || "").toLowerCase();
  if (m.startsWith("video/")) return "Video";
  if (m.startsWith("audio/")) return "Audio";
  if (m.startsWith("image/")) return "Image";
  const n = String(name || "");
  if (EXT_VIDEO.test(n)) return "Video";
  if (EXT_AUDIO.test(n)) return "Audio";
  if (EXT_IMAGE.test(n)) return "Image";
  return "Document";
}

