// Which filming session a script is booked into (null = not booked yet).
// Module-level so the drafts list can use it too: a booked script leaves
// To Review even before its status write has come back round.
function sessionIdOf(item: any): string | null {
  const link = item?.fields?.filmingSession;
  const first = Array.isArray(link) ? link[0] : link;
  return first?.id || null;
}

// "2h 30m free" / "45m free" / "Full".
function formatFreeLabel(freeMin: number): string {
  if (freeMin <= 0) return "Full";
  const h = Math.floor(freeMin / 60);
  const m = freeMin % 60;
  if (h && m) return `${h}h ${m}m free`;
  if (h) return `${h}h free`;
  return `${m}m free`;
}

