// Inline span used inside bot bubbles to highlight dynamic values (counts,
// hours, etc). Bubbles are 300-weight; emphasis spans go 600 per UI standards.
function DataTag({ children }: { children: React.ReactNode }) {
  return (
    <span style={{ fontWeight: 600, color: "#171717" }}>
      {children}
    </span>
  );
}

// The "…" trio that animates at the end of loading-state bot lines.
function TypingDots() {
  return <span className="strat-typing-dots" />;
}

// Pipeline strip — brand+format aware. Computes runway %, bar color, math
// grid values from the selected brand's per-format pipeline data. "Approved
// scripts" is hardcoded to 0 here because on Screens 2/3 no Script Request
// exists yet; the post-generation state will read from Script Request's
// "Approved scripts so far" field instead.
function PipelineStrip({
  brand,
  format,
  mathOpen,
  onToggleMath,
  embedded = false,
  labelOverride,
}: {
  brand: Brand;
  format: FormatKey;
  mathOpen: boolean;
  onToggleMath: () => void;
  embedded?: boolean;
  // When set (e.g. "Video" or "Graphic"), overrides the default
  // "Pipeline health" caps text on the embedded label. Used by the 2.E
  // strip where each row needs a format-specific label.
  labelOverride?: string;
}) {
  const block = brand[format];
  const safety = brand.safetyTarget || 0;
  const cadence = block.cadenceTargetPerWeek || 0;
  const currentDays = block.currentPipelineDays || 0;
  const rawSuggested = block.suggestedToApprove;
  const suggested = typeof rawSuggested === "number" ? rawSuggested : 0;
  // Typed as a number rather than left to narrow to the literal 0: the
  // singular/plural check below compares it against 1, which a checker reads
  // as provably false and flags. Nothing feeds this yet.
  const approvedSoFar: number = 0;
  const scriptsToGo = Math.max(0, suggested - approvedSoFar);

  const healthPct = safety > 0 ? Math.min(100, (currentDays / safety) * 100) : 0;
  const fillWidth = `${Math.max(0, Math.round(healthPct))}%`;
  const fillColor = pipelineHealthColor(healthPct);

  const formatLabel = format === "graphic" ? "static post" : "video";
  const formatPlural = format === "graphic" ? "static posts" : "video";
  const platformLabel = brand.prioritySocial || "Instagram";

  const scriptsNoun = scriptsToGo === 1 ? "script" : "scripts";
  // Days are whole numbers, rounded up (Karen 2026-09-13).
  const currentDaysDisplay = Math.ceil(currentDays);

  return (
    <div data-rail-keep="block">
      {/* Row A — text + info button */}
      <div
        className="flex items-center gap-1.5 cursor-pointer"
        onClick={onToggleMath}
      >
        {embedded ? (
          <div
            className="flex-1 uppercase"
            style={{
              fontFamily: "'Geist Mono', monospace",
              fontSize: "12px",
              fontWeight: 500,
              letterSpacing: "0.1em",
              color: "#525252",
              lineHeight: 1.4,
            }}
          >
            {labelOverride || "Pipeline health"}
          </div>
        ) : (
          <div
            className="flex-1 font-mono"
            style={{ fontSize: "12px", lineHeight: 1.4, color: "#525252" }}
          >
            <span style={{ fontWeight: 700 }}>
              {scriptsToGo} {scriptsNoun} to go
            </span>
            <span style={{ fontWeight: 300 }}> for pipeline health</span>
          </div>
        )}
        <div
          className="w-[22px] h-[22px] rounded-full bg-white flex items-center justify-center"
          style={{ border: "1px solid rgba(168,85,247,0.32)", color: "#A855F7" }}
        >
          <Info className="w-3 h-3" />
        </div>
      </div>

      {/* Row B — progress bar.
          Red outline when THIS format's pipeline count = 0 (per spec 2.E
          empty rule). Uses `outline` (not border) so the bar height stays
          6px with no layout shift. Right end is SQUARE (not rounded) so it
          meets the target marker line cleanly. */}
      <div
        className="relative h-1.5 bg-[#f5f5f5] mt-2"
        style={{
          borderRadius: "3px 0 0 3px",
          outline: (block.pipelineCount === 0 && !(block.currentPipelineDays > 0)) ? "1.5px solid #dc2626" : "none",
          outlineOffset: 0,
          transition: "outline-color 0.2s ease",
        }}
      >
        <div
          className="absolute h-full"
          style={{
            width: fillWidth,
            background: fillColor,
            borderRadius: "3px 0 0 3px",
            transition: "width 0.4s ease, background-color 0.3s ease",
          }}
        />
        <div
          className="absolute top-[-3px] bottom-[-3px] w-[2px] bg-[#171717]"
          style={{ right: 0, opacity: 0.4 }}
        />
        <div
          className="absolute font-mono"
          style={{
            right: "-2px",
            top: "12px",
            fontSize: "11px",
            fontWeight: 600,
            color: "#525252",
          }}
        >
          {safety}d target
        </div>
      </div>

      {/* Math grid */}
      {mathOpen && (
        <div
          className="grid gap-x-3.5 gap-y-1.5 p-3 bg-white border rounded-lg mt-10 font-mono uppercase"
          style={{
            gridTemplateColumns: "max-content 1fr",
            borderColor: "#ededed",
            fontSize: "11px",
            letterSpacing: "0.06em",
          }}
        >
          {/* Order locked across all math grids:
                Priority platform → Posting cadence target → Pipeline target
                → Current pipeline → Suggested to approve → Approved scripts.
              Cadence rendered in DAY units so it stays consistent with the
              "X days" pipeline target row.
              Label = bold dark; value = lighter (same style the old label had). */}
          <div style={{ color: "#171717", fontWeight: 700 }}>Priority platform</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>{platformLabel}</div>

          <div style={{ color: "#171717", fontWeight: 700 }}>Posting cadence target</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>
            {cadenceToDayLabel(cadence, formatLabel) || "No cadence set"}
          </div>

          <div style={{ color: "#171717", fontWeight: 700 }}>Pipeline target</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>
            {safety} days of {formatPlural}
          </div>

          <div style={{ color: "#171717", fontWeight: 700 }}>Current pipeline</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>
            <span style={{ color: fillColor, fontWeight: 700 }}>{currentDaysDisplay}</span> days of {formatPlural}
          </div>

          <div style={{ color: "#171717", fontWeight: 700 }}>In the pipeline</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>
            {block.pipelineCount} {formatLabel} script{block.pipelineCount === 1 ? "" : "s"}
          </div>

        </div>
      )}
    </div>
  );
}

// Pipeline strip in its "embedded inside the bot zone" wrapper — handles
// the standard inline placement (left-inset to align with bubble text,
// right-extended to the bot zone edge, large bottom margin before the
// decision chips). Used on Screens 1, 1b, 2, 3a, 3b.
function InlinePipeline({
  brand,
  format,
  mathOpen,
  onToggleMath,
}: {
  brand: Brand;
  format: FormatKey;
  mathOpen: boolean;
  onToggleMath: () => void;
}) {
  return (
    <div data-rail-keep="block"
      className="mt-6"
      style={{ maxWidth: "100%", paddingLeft: "14px" }}
    >
      <PipelineStrip
        brand={brand}
        format={format}
        mathOpen={mathOpen}
        onToggleMath={onToggleMath}
        embedded
      />
    </div>
  );
}

// Single brand pipeline row used on Screen 2.D. Mirrors the visual structure
// of PipelineStrip (caps label + info button on Row A; bar with safety marker
// on Row B; optional expandable math grid below) but is brand-level — the bar
// represents the brand's overall Average pipeline health, and the math grid
// breaks that down into Video % / Graphic % / safety target. Each row's math
// grid toggles independently (handled by the openSet in MultiBrandPipelineStrip).
function BrandPipelineRow({
  brand,
  mathOpen,
  onToggleMath,
}: {
  brand: Brand;
  mathOpen: boolean;
  onToggleMath: () => void;
}) {
  const avgFraction = brand.averageHealth || 0;
  const avgPct = Math.max(0, Math.min(100, avgFraction * 100));
  const fillWidth = `${Math.round(avgPct)}%`;
  const fillColor = pipelineHealthColor(avgPct);

  const videoCadenceRaw = brand.video?.cadenceTargetPerWeek || 0;
  const graphicCadenceRaw = brand.graphic?.cadenceTargetPerWeek || 0;
  const videoDays = Math.ceil(brand.video?.currentPipelineDays || 0);
  const graphicDays = Math.ceil(brand.graphic?.currentPipelineDays || 0);
  const safety = brand.safetyTarget || 0;
  const platformLabel = brand.prioritySocial || "Instagram";

  // Per-format current-pipeline health for number tinting in the math grid.
  // Uses the same currentDays/safety calc the format-level bar uses, so the
  // brand-level "X days of video" number reads in the SAME color the
  // format-level bar would paint when the user moves to 2.E for that format.
  const videoHealthPct =
    safety > 0 ? Math.min(100, ((brand.video?.currentPipelineDays || 0) / safety) * 100) : 0;
  const graphicHealthPct =
    safety > 0 ? Math.min(100, ((brand.graphic?.currentPipelineDays || 0) / safety) * 100) : 0;
  const videoCurrentColor = pipelineHealthColor(videoHealthPct);
  const graphicCurrentColor = pipelineHealthColor(graphicHealthPct);

  // Day-based cadence — joins both formats when both are non-zero, drops the
  // zero one cleanly. Keeps units consistent with "Xd target" and the days
  // shown in the current-pipeline row.
  const cadenceParts = [
    cadenceToDayLabel(videoCadenceRaw, "video"),
    cadenceToDayLabel(graphicCadenceRaw, "static post"),
  ].filter((s): s is string => !!s);

  // Outline the BAR (not the whole row) in red ONLY when overall average
  // health is exactly 0. Per-format zeros are not "empty" at this level —
  // those still surface visually via the bar color (red for <51%).
  const isEmpty = avgFraction === 0;

  return (
    <div>
      {/* Row A — brand name caps label + info button */}
      <div
        className="flex items-center gap-1.5 cursor-pointer"
        onClick={onToggleMath}
      >
        <div
          className="flex-1 uppercase"
          style={{
            fontFamily: "'Geist Mono', monospace",
            fontSize: "12px",
            fontWeight: 500,
            letterSpacing: "0.1em",
            color: "#525252",
            lineHeight: 1.4,
          }}
        >
          {brand.name}
        </div>
        <div
          className="w-[22px] h-[22px] rounded-full bg-white flex items-center justify-center"
          style={{ border: "1px solid rgba(168,85,247,0.32)", color: "#A855F7" }}
        >
          <Info className="w-3 h-3" />
        </div>
      </div>

      {/* Row B — progress bar with pipeline target marker.
          Outline = red ONLY when overall average health is 0. Using `outline`
          (not `border`) so the bar height stays 6px with no layout shift.
          Right end is SQUARE (not rounded) so it meets the target marker
          line cleanly. Left end stays rounded. */}
      <div
        className="relative h-1.5 bg-[#f5f5f5] mt-2"
        style={{
          borderRadius: "3px 0 0 3px",
          outline: isEmpty ? "1.5px solid #dc2626" : "none",
          outlineOffset: 0,
          transition: "outline-color 0.2s ease",
        }}
      >
        <div
          className="absolute h-full"
          style={{
            width: fillWidth,
            background: fillColor,
            borderRadius: "3px 0 0 3px",
            transition: "width 0.4s ease, background-color 0.3s ease",
          }}
        />
        <div
          className="absolute top-[-3px] bottom-[-3px] w-[2px] bg-[#171717]"
          style={{ right: 0, opacity: 0.4 }}
        />
        <div
          className="absolute font-mono"
          style={{
            right: "-2px",
            top: "12px",
            fontSize: "11px",
            fontWeight: 600,
            color: "#525252",
          }}
        >
          {safety}d target
        </div>
      </div>

      {/* Math grid — brand-level breakdown.
          Order locked across all grids:
            Priority platform → Posting cadence target → Pipeline target
            → Current pipeline → (Suggested to approve, Approved scripts —
            format-level grid only, skipped here since no format is chosen yet).
          Label = bold dark; value = lighter (same style the old label had). */}
      {mathOpen && (
        <div
          className="grid gap-x-3.5 gap-y-1.5 p-3 bg-white border rounded-lg mt-10 font-mono uppercase"
          style={{
            gridTemplateColumns: "max-content 1fr",
            borderColor: "#ededed",
            fontSize: "11px",
            letterSpacing: "0.06em",
          }}
        >
          <div style={{ color: "#171717", fontWeight: 700 }}>Priority platform</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>{platformLabel}</div>

          <div style={{ color: "#171717", fontWeight: 700 }}>Posting cadence target</div>
          <div
            style={{
              color: "#737373",
              fontWeight: 500,
              display: "flex",
              flexDirection: "column",
              gap: "2px",
            }}
          >
            {cadenceParts.length > 0
              ? cadenceParts.map((line, i) => <span key={i}>{line}</span>)
              : <span>No cadence set</span>}
          </div>

          <div style={{ color: "#171717", fontWeight: 700 }}>Pipeline target</div>
          <div style={{ color: "#737373", fontWeight: 500 }}>{safety} days per format</div>

          <div style={{ color: "#171717", fontWeight: 700 }}>Current pipeline</div>
          <div
            style={{
              color: "#737373",
              fontWeight: 500,
              display: "flex",
              flexDirection: "column",
              gap: "2px",
            }}
          >
            <span>
              <span style={{ color: videoCurrentColor, fontWeight: 700 }}>{videoDays}</span> days of video
            </span>
            <span>
              <span style={{ color: graphicCurrentColor, fontWeight: 700 }}>{graphicDays}</span> days of static posts
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

// Stack of BrandPipelineRows used on Screen 2.D. Wraps in the same outer
// spacing as InlinePipeline (left-inset 14px, mt-6) so it visually sits
// in the same column as the format-specific pipeline strip used on later
// screens. Rows separated by 32px so the "Xd target" label below each bar
// doesn't crowd the next row's info button.
function MultiBrandPipelineStrip({
  brands,
  openSet,
  onToggle,
}: {
  brands: Brand[];
  openSet: Set<string>;
  onToggle: (id: string) => void;
}) {
  return (
    <div data-rail-keep="block" className="mt-6 rail-pipeline-cards" style={{ paddingLeft: "14px" }}>
      {brands.map((b, idx) => (
        <div key={b.id} style={{ marginTop: idx === 0 ? 0 : "32px" }}>
          <BrandPipelineRow
            brand={b}
            mathOpen={openSet.has(b.id)}
            onToggleMath={() => onToggle(b.id)}
          />
        </div>
      ))}
    </div>
  );
}

// Two-row pipeline strip used on Screen 2.E. One row per format (video +
// graphic) for the SELECTED brand. Each row is just a PipelineStrip with a
// format-specific caps label. Math grids toggle independently per format.
// Same 32px row spacing as the multi-brand strip so the "Xd target" label
// under each bar doesn't crowd the next row's info button.
function BrandFormatPipelineStrip({
  brand,
  openSet,
  onToggle,
}: {
  brand: Brand;
  openSet: Set<FormatKey>;
  onToggle: (fmt: FormatKey) => void;
}) {
  return (
    <div data-rail-keep="block" className="mt-6" style={{ maxWidth: "100%", paddingLeft: "14px" }}>
      <div>
        <PipelineStrip
          brand={brand}
          format="video"
          mathOpen={openSet.has("video")}
          onToggleMath={() => onToggle("video")}
          embedded
          labelOverride="Video"
        />
      </div>
      <div style={{ marginTop: "32px" }}>
        <PipelineStrip
          brand={brand}
          format="graphic"
          mathOpen={openSet.has("graphic")}
          onToggleMath={() => onToggle("graphic")}
          embedded
          labelOverride="Static posts"
        />
      </div>
    </div>
  );
}

// Wraps content (chips, input pills, CTAs) that should fade in AFTER the
// staggered bot bubbles above it have finished revealing.
function StaggerAfterBubbles({
  count,
  children,
}: {
  count: number;
  children: React.ReactNode;
}) {
  const base = useContext(RailDelayCtx);
  return (
    <div
      className="strat-bubble-in"
      style={{ animationDelay: `${base + count * 0.7}s` }}
    >
      {children}
    </div>
  );
}

// ─── Rail v2 components (design_handoff_flowy_rail) ─────────────────────────

// One story card: brain-dump textarea (auto-grown) + media drop tile + the
// tooltip hint behind the info button. Filled = green border, like every
// other selected surface.
// ── Voice notes on the rail ────────────────────────────────────────────────
// Tap the mic, talk, tap again: the take goes to the transcription webhook and
// the words are appended to the box. One hook and one button, shared by the
// stance box and the story cards, using the same method as the composers (the
// browser's own speech API was tried first and is far less reliable).
// A take is its own paragraph, never glued to the sentence before it (Karen
// 2026-09-14: it landed mid-paragraph and had to be hunted for).
const joinSpoken = (prev: string, add: string) =>
  (prev.trim() ? `${prev.trim()}\n\n${add.trim()}` : add.trim());

function useVoiceNote(onText: (text: string) => void) {
  const [state, setState] = useState<"idle" | "recording" | "processing">("idle");
  const [secs, setSecs] = useState(0);
  const mediaRef = useRef<any>(null);
  const chunksRef = useRef<any[]>([]);
  const timerRef = useRef<any>(null);
  // Set true by cancel(): the next onstop throws the take away instead of
  // transcribing it, so a recording left running when the question changes
  // never drops its words into the next box.
  const cancelRef = useRef(false);
  // Always the latest callback, so the take lands on the text as it is NOW.
  const onTextRef = useRef(onText);
  onTextRef.current = onText;
  const stop = () => {
    clearInterval(timerRef.current);
    try {
      if (mediaRef.current && mediaRef.current.state !== "inactive") mediaRef.current.stop();
    } catch { /* noop */ }
  };
  // Stop recording and discard the take (no transcription, no text appended).
  const cancel = () => {
    if (state === "idle") return;
    cancelRef.current = true;
    stop();
    setState("idle");
  };
  const start = async () => {
    try {
      const stream = await (navigator as any).mediaDevices.getUserMedia({ audio: true });
      const mr = new (window as any).MediaRecorder(stream);
      mediaRef.current = mr;
      chunksRef.current = [];
      mr.ondataavailable = (e: any) => { if (e.data && e.data.size) chunksRef.current.push(e.data); };
      mr.onstop = async () => {
        stream.getTracks().forEach((t: any) => t.stop());
        // Cancelled take: let go of the audio without transcribing or appending.
        if (cancelRef.current) { cancelRef.current = false; setState("idle"); return; }
        setState("processing");
        try {
          const blob = new Blob(chunksRef.current, { type: "audio/webm" });
          const res = await fetch(TRANSCRIBE_WEBHOOK, {
            method: "POST",
            headers: { "Content-Type": "audio/webm" },
            body: blob,
          });
          const j = await res.json().catch(() => null);
          const text = String(j?.text || "").trim();
          if (text) onTextRef.current(text);
          else errorToast("Couldn't transcribe that. Please try again.");
        } catch {
          errorToast("Couldn't transcribe that. Please try again.");
        }
        setState("idle");
      };
      mr.start();
      cancelRef.current = false;
      setSecs(0);
      setState("recording");
      timerRef.current = setInterval(() => {
        setSecs((s) => { if (s + 1 >= 300) stop(); return s + 1; });
      }, 1000);
    } catch {
      setState("idle");
      errorToast("Couldn't reach the microphone.");
    }
  };
  // Leaving the card mid-take stops the recorder rather than leaking the mic.
  useEffect(() => () => {
    clearInterval(timerRef.current);
    try {
      if (mediaRef.current && mediaRef.current.state !== "inactive") mediaRef.current.stop();
    } catch { /* noop */ }
  }, []);
  const toggle = () => {
    if (state === "recording") stop();
    else if (state === "idle") start();
  };
  return { state, secs, toggle, cancel };
}

// The mic row that sits INSIDE a text box, bottom right, with the recording
// clock beside it while a take is running.
function VoiceMicButton({ state, secs, onToggle, label }: {
  state: "idle" | "recording" | "processing"; secs: number;
  onToggle: () => void; label: string;
}) {
  const recording = state === "recording";
  return (
    <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: "8px", padding: "3px 7px 7px" }}>
      {state !== "idle" && (
        <span style={{
          fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 500,
          letterSpacing: "0.06em", textTransform: "uppercase",
          color: recording ? "#DC2626" : "#A3A3A3",
        }}>
          {recording ? `Recording · ${mmssClock(secs)}` : "Transcribing…"}
        </span>
      )}
      <button
        onClick={(e: any) => { e.stopPropagation(); onToggle(); }}
        disabled={state === "processing"}
        aria-label={recording ? "Stop recording" : label}
        title={recording ? "Stop recording" : label}
        style={{
          width: "28px", height: "28px", borderRadius: "50%", padding: 0, flexShrink: 0,
          // Solid purple, white glyph: the one look for every text-less
          // button on a card (Karen, 2026-09-03). Red while a take runs.
          background: recording ? "#DC2626" : "#A855F7",
          border: "none",
          cursor: state === "processing" ? "wait" : "pointer",
          opacity: state === "processing" ? 0.6 : 1,
          display: "inline-flex", alignItems: "center", justifyContent: "center",
        }}
      >
        {recording
          ? <span style={{ width: "10px", height: "10px", borderRadius: "2px", background: "white" }} />
          : <Mic size={13} strokeWidth={2.2} style={{ color: "white" }} />}
      </button>
    </div>
  );
}

function StoryRailCard({
  card, text, mediaCount, open, onToggleOpen, tipOpen, onToggleTip, onText, onFiles, isDesktop,
}: {
  card: { id: string; title: string; hint: string; icon: any };
  text: string; mediaCount: number;
  open: boolean; onToggleOpen: () => void;
  tipOpen: boolean; onToggleTip: () => void;
  onText: (v: string) => void; onFiles: (files: File[]) => void;
  isDesktop: boolean;
}) {
  const fileRef = useRef<HTMLInputElement | null>(null);
  const voice = useVoiceNote((t) => onText(joinSpoken(text, t)));
  const taRef = useRef<HTMLTextAreaElement | null>(null);
  // Auto-grow on every render so nothing scrolls or clips (§4.5).
  useEffect(() => {
    const el = taRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  });
  const filled = !!text.trim() || mediaCount > 0;
  const Icon = card.icon;
  return (
    <div style={{
      // Same surface as the chat bubbles: white on the mobile sheet, soft
      // grey on the desktop rail. The text and media boxes inside stay white.
      background: isDesktop ? "#F4F5F6" : "#FFFFFF",
      borderRadius: "14px", overflow: "hidden",
      border: `1px solid ${filled ? "#16A34A" : "#ededed"}`,
      boxShadow: "0 1px 2px rgba(22,23,26,0.03)",
      transition: "border-color 0.18s ease",
    }}>
      <div
        onClick={onToggleOpen}
        style={{ position: "relative", display: "flex", alignItems: "center", gap: "9px", padding: "12px 15px 11px", cursor: "pointer", userSelect: "none" }}
      >
        <Icon size={15} strokeWidth={1.9} style={{ color: filled ? "#16A34A" : "#525252", flexShrink: 0 }} />
        <span style={{ flex: 1, fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 500, color: "#171717", letterSpacing: "-0.005em" }}>
          {card.title}
          {!open && filled && (
            <span style={{ marginLeft: "8px", fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 600, letterSpacing: "0.05em", color: "#16A34A" }}>
              ADDED
            </span>
          )}
        </span>
        <button
          onClick={(e: any) => { e.stopPropagation(); onToggleTip(); }}
          aria-label="What counts"
          style={{
            width: "22px", height: "22px", borderRadius: "50%", flexShrink: 0, padding: 0,
            background: "white", border: "1px solid rgba(168,85,247,0.32)", cursor: "pointer",
            display: "inline-flex", alignItems: "center", justifyContent: "center",
          }}
        >
          <Info size={12} strokeWidth={2} style={{ color: "#A855F7" }} />
        </button>
        <ChevronDown
          size={15}
          strokeWidth={2}
          style={{
            color: "#737373", flexShrink: 0,
            transform: open ? "rotate(180deg)" : "rotate(0deg)",
            transition: "transform 0.2s ease",
          }}
        />
        {tipOpen && (
          <div style={{
            position: "absolute", top: "calc(100% - 2px)", right: "13px", zIndex: 30,
            maxWidth: "240px", background: "white", border: "1px solid #ededed",
            borderRadius: "8px", padding: "9px 12px",
            boxShadow: "0 6px 18px rgba(23,23,23,0.12)",
            fontFamily: "'Geist', sans-serif", fontSize: "12px", fontWeight: 350, color: "#525252",
            animation: "fsBubbleIn 0.16s cubic-bezier(0.16,1,0.3,1) both",
          }}>
            {card.hint}
          </div>
        )}
      </div>
      {open && (
      <div style={{
        display: "grid",
        gridTemplateColumns: isDesktop ? "minmax(0, 1fr) 148px" : "minmax(0, 1fr) 96px",
        borderTop: "1px solid #ededed",
      }}>
        <div style={{ minWidth: 0, padding: "8px 0 10px 15px" }}>
          <div style={{ minHeight: "24px", display: "flex", alignItems: "center", fontFamily: "'Geist Mono', monospace", fontSize: "11px", fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: "#171717" }}>
            Brain dump
          </div>
          <div style={{ background: "white", border: "1px solid #ededed", borderRadius: "10px", overflow: "hidden", marginTop: "5px" }}>
            <textarea
              ref={taRef}
              value={text}
              onChange={(e: any) => onText(e.target.value)}
              placeholder="Type it or record it"
              style={{
                display: "block", width: "100%", boxSizing: "border-box",
                background: "transparent", border: "none", outline: "none",
                padding: "10px 12px 0", minHeight: "54px", resize: "none", overflow: "hidden",
                fontFamily: "'Geist', sans-serif", fontSize: "14px", lineHeight: 1.5, color: "#52525B",
              }}
            />
            <VoiceMicButton state={voice.state} secs={voice.secs} onToggle={voice.toggle} label="Record this story" />
          </div>
        </div>
        <div style={{ padding: "8px 15px 10px 10px" }}>
          <div style={{ minHeight: "24px", display: "flex", alignItems: "center", fontFamily: "'Geist Mono', monospace", fontSize: "11px", fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", color: "#171717" }}>
            Related media
          </div>
          <button
            onClick={() => fileRef.current?.click()}
            style={{
              width: "100%", height: isDesktop ? "94px" : "88px", marginTop: "5px",
              borderRadius: "8px", background: "white", cursor: "pointer",
              border: mediaCount > 0 ? "1px solid rgba(22,163,74,0.45)" : "1px dashed #d4d4d4",
              display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: "6px",
            }}
          >
            <Image size={15} strokeWidth={1.8} style={{ color: mediaCount > 0 ? "#16A34A" : "#737373" }} />
            <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12px", fontWeight: 500, color: mediaCount > 0 ? "#16A34A" : "#737373" }}>
              {mediaCount > 0 ? `${mediaCount} file${mediaCount === 1 ? "" : "s"} added` : "Attach"}
            </span>
          </button>
          <input
            ref={fileRef}
            type="file"
            multiple
            accept="image/*,video/*"
            style={{ display: "none" }}
            onChange={(e: any) => {
              const files = Array.from(e.target.files || []) as File[];
              if (files.length) onFiles(files);
              e.target.value = "";
            }}
          />
        </div>
      </div>
      )}
    </div>
  );
}

// One topic card in the accordion: tag eyebrow + green select circle, and when
// open the editable Topic + stance fields, each with its ↺ feedback bar.
// The card a swapped-in or hand-picked topic shows while Flowy writes its
// stance (Karen 2026-09-15): the wave and one line, in the card's place, never
// a card that only says so once it is opened.
function StanceWritingCard({ topic }: { topic: any }) {
  const isTrend = topic.source === "Trending";
  const TagIcon = isTrend ? Flame : Leaf;
  // A batch-picker card keeps its own layout while its stance is written.
  const picker = !!topic.fromPicker && !topic.ownIdea;
  const PickIcon = topic.cardIcon === "fire" ? Flame : topic.cardIcon === "trophy" ? Trophy : topic.cardIcon === "heart" ? Heart : null;
  const pickIconColor = topic.cardIcon === "fire" ? "#E5484D" : topic.cardIcon === "trophy" ? "#B8860B" : "#EC4899";
  if (picker) {
    return (
      <div style={{ background: "white", borderRadius: "14px", border: "1px solid #ededed", overflow: "hidden" }}>
        <div style={{ padding: "12px 14px 14px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "6px", fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 500, letterSpacing: "0.05em", textTransform: "uppercase", color: "#737373" }}>
            {PickIcon ? <PickIcon size={12} strokeWidth={2.2} style={{ color: pickIconColor, flexShrink: 0 }} /> : null}
            <span style={{ minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{topic.categoryName}</span>
          </div>
          <div style={{ marginTop: "9px", fontFamily: "'Geist', sans-serif", fontSize: "15px", fontWeight: 500, color: "#171717", lineHeight: 1.35 }}>
            {topic.question || topic.subtopic || topic.name}
          </div>
          <div style={{ marginTop: "10px", display: "flex", alignItems: "center", gap: "10px", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", fontWeight: 300, color: "#737373" }}>
            <WaveAvatar />
            <span>Flowy is writing the stance<TypingDots /></span>
          </div>
        </div>
      </div>
    );
  }
  return (
    <div style={{ background: "white", borderRadius: "14px", border: "1px solid #ededed", overflow: "hidden" }}>
      <div style={{ padding: "12px 14px 14px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <span style={{
            flexShrink: 0, display: "inline-flex", alignItems: "center", gap: "5px",
            fontFamily: "'Geist Mono', monospace", fontSize: "9.5px", fontWeight: 700,
            letterSpacing: "0.08em", textTransform: "uppercase",
            padding: "2px 7px", borderRadius: "5px", color: "#737373", background: "#F4F5F6",
          }}>
            <TagIcon size={11} strokeWidth={2.2} style={{ color: isTrend ? "#E5484D" : "#16A34A" }} />
            {isTrend ? "Trending" : "Evergreen"} topic
          </span>
          <span style={{ flex: 1 }} />
          {topic.categoryName ? (
            <span style={{ fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 500, letterSpacing: "0.05em", textTransform: "uppercase", color: "#A3A3A3" }}>
              {topic.categoryName}
            </span>
          ) : null}
        </div>
        <div style={{ marginTop: "9px", fontFamily: "'Geist', sans-serif", fontSize: "15px", fontWeight: 500, color: "#171717", lineHeight: 1.35 }}>
          {topic.name}
        </div>
        <div style={{ marginTop: "10px", display: "flex", alignItems: "center", gap: "10px", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", fontWeight: 300, color: "#737373" }}>
          <WaveAvatar />
          <span>Flowy is writing the stance<TypingDots /></span>
        </div>
      </div>
    </div>
  );
}

function TopicRailCard({
  topic, edits, selected, open, scriptsCount = 0, regenOpen, regenNote,
  onRegenNote, onToggleOpen, onToggleSelect, onEdit, onSpoken, onOpenRegen, onCloseRegen, onRegen,
  onRetryStance, onSwap,
}: {
  topic: any; edits: { name?: string; stance?: string; summary?: string };
  selected: boolean; open: boolean; scriptsCount?: number;
  regenOpen: string | null; regenNote: string;
  onRegenNote: (v: string) => void;
  onToggleOpen: () => void; onToggleSelect: () => void;
  onEdit: (patch: any) => void;
  onSpoken?: (text: string) => void;
  onOpenRegen: (which: string) => void; onCloseRegen: () => void; onRegen: () => void;
  onRetryStance?: () => void;
  onSwap?: () => void;
}) {
  const [stanceEditing, setStanceEditing] = useState(false);
  const [stanceMenu, setStanceMenu] = useState(false);
  // The words of the take that just landed (Karen 2026-09-14): shown in
  // purple italics at the end of the stance and scrolled into view, so they
  // can be found. A tap on the text, or Edit it yourself, makes them plain.
  const [freshSpoken, setFreshSpoken] = useState<string | null>(null);
  const freshRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    if (!freshSpoken || !freshRef.current) return;
    try { freshRef.current.scrollTop = freshRef.current.scrollHeight; } catch { /* nothing to scroll */ }
  }, [freshSpoken, stanceEditing]);
  // The label says where it comes from AND what kind of subtopic it is
  // (Karen 2026-09-13): "Evergreen question", "Trending pushback", and so on.
  const kindOf = (type: string) => {
    const tt = (type || "").toLowerCase();
    if (tt === "joke") return "joke";
    if (tt === "push" || tt === "rebuttal") return "pushback";
    if (tt === "how") return "request";
    return "question";
  };
  const isTrend = topic.source === "Trending";
  const tag = topic.isStory ? "PERSONAL STORY OR EVENT"
    : topic.ownIdea ? "Your idea"
    : `${isTrend ? "Trending" : "Evergreen"} ${topic.subtopic ? kindOf(topic.subType) : "topic"}`;
  const tagColor = topic.isStory ? "#A855F7" : topic.ownIdea ? "#6366F1" : isTrend ? "#E5484D" : "#16A34A";
  const TagIcon = topic.isStory ? Camera : topic.ownIdea ? Lightbulb : isTrend ? Flame : Leaf;
  // A card from the batch picker (Karen's layout, 2026-10-07): the icon and the
  // pillar on one line (fire = trending, trophy = top performer, heart =
  // personal, none for the rest), how often the question was used at the top
  // right, the question, then when open the situation and the stance.
  const picker = !!topic.fromPicker && !topic.isStory && !topic.ownIdea;
  const PickIcon = topic.cardIcon === "fire" ? Flame : topic.cardIcon === "trophy" ? Trophy : topic.cardIcon === "heart" ? Heart : null;
  const pickIconColor = topic.cardIcon === "fire" ? "#E5484D" : topic.cardIcon === "trophy" ? "#B8860B" : "#EC4899";
  const uses = Number(topic.questionUses || 0);
  const usesLabel = uses === 0 ? "Not used yet" : uses === 1 ? "Used once" : `Used ${uses} times`;
  const stanceFailedHere = !topic.isStory && topic.stanceState === "failed";
  // Only the founder can answer this one (Karen 2026-10-11): nothing they have
  // given Flowy tells it, so the box stays empty and is flagged the way the
  // onboarding form flags a box that needs their own words.
  const stanceNeedsHere = !topic.isStory && topic.stanceState === "needs";
  // Like a form box: open for typing straight away. It stays open once they
  // start, so the box never swaps under their first keystroke.
  useEffect(() => { if (stanceNeedsHere) setStanceEditing(true); }, [stanceNeedsHere]);
  // A picker card's context is written for the founder and sits right under
  // the question (Karen 2026-10-11). The question's description (the
  // audience's own words and the brief for what a full answer covers) is for
  // the stance and the writer only: on the card it read as a second question
  // and an instruction. The question bank now writes a context for the
  // founder after the audience line, labelled "Context:" (Karen 2026-10-12):
  // why the question is asked, who it is about and what it wants from them.
  // A question written before that has none, so a trend card falls back to
  // the trend as it was found and an evergreen card shows nothing.
  const trendFound = [String(topic.trendHeadline || "").trim(), String(topic.trendSummary || "").trim()];
  const writtenContext = (String(topic.situation || "").match(/(?:^|\n)Context:\s*([\s\S]+)$/) || [])[1] || "";
  const pickerContext = !picker ? "" : (writtenContext.trim() || (isTrend ? trendFound[1] : ""));
  const showSituation = picker ? false
    : (topic.isStory || isTrend || topic.categoryName === REPLY_PILLAR || !topic.subtopic);
  const stanceLabel = topic.isStory ? "Your story" : "Your stance";
  const stancePh = topic.isStory ? "Your words, as you told them"
    : stanceNeedsHere ? ""
    : "Take your stance, type it or record it";
  const name = edits.name ?? topic.name;
  // The subtopic is the headline for evergreen and trending alike; a trending
  // headline moves into the card's context when it opens.
  const title = (!topic.isStory && topic.subtopic) ? topic.subtopic : name;
  const stance = edits.stance ?? topic.stance;
  const brief = edits.summary ?? (topic.summary || "");
  const voice = useVoiceNote((t) => {
    if (t.trim()) setFreshSpoken(t.trim());
    if (onSpoken) onSpoken(t); else onEdit({ stance: joinSpoken(stance, t) });
  });
  const stanceText = String(stance || "");
  const freshAtEnd = !!freshSpoken && stanceText.endsWith(freshSpoken);
  const stanceWithFresh = freshAtEnd && freshSpoken
    ? <>{stanceText.slice(0, stanceText.length - freshSpoken.length)}<span style={{ color: "#A855F7", fontStyle: "italic" }}>{freshSpoken}</span></>
    : stanceText;
  const regenBar = (which: string) => (
    <div style={{
      display: "flex", alignItems: "center", gap: "6px", marginTop: "9px",
      background: "#FAF5FF", border: "1px solid rgba(168,85,247,0.30)",
      borderRadius: "8px", padding: "6px 6px 6px 11px",
      animation: "fsBubbleIn 0.16s cubic-bezier(0.16,1,0.3,1) both",
    }}>
      <WaveAvatar />
      <input
        value={regenNote}
        onChange={(e: any) => onRegenNote(e.target.value)}
        placeholder="Tell Flowy what to change…"
        style={{
          flex: 1, minWidth: 0, border: "none", outline: "none", background: "transparent",
          fontFamily: "'Geist', sans-serif", fontSize: "13px", color: "#171717",
        }}
      />
      <button
        onClick={onRegen}
        style={{
          height: "28px", padding: "0 12px", borderRadius: "6px", flexShrink: 0,
          background: BRAND_GRADIENT, border: "none", color: "white",
          fontFamily: "'Geist', sans-serif", fontSize: "12px", fontWeight: 600, cursor: "pointer",
        }}
      >
        Regenerate
      </button>
      <button
        onClick={onCloseRegen}
        aria-label="Close"
        style={{ width: "24px", height: "24px", background: "transparent", border: "none", cursor: "pointer", color: "#737373", padding: 0 }}
      >
        <X size={13} strokeWidth={2} />
      </button>
    </div>
  );
  // Both boxes are multi-line: they grow with the text and only start
  // scrolling past roughly 500 characters (~220px at this type size).
  const fieldBox: React.CSSProperties = {
    width: "100%", boxSizing: "border-box", background: "white",
    border: "1px solid #ededed", borderRadius: "10px", padding: "10px 13px",
    fontFamily: "'Geist', sans-serif", fontSize: "15px", lineHeight: 1.55, color: "#171717", fontWeight: 300,
    outline: "none", resize: "none" as any,
    maxHeight: "220px", overflowY: "auto" as any,
  };
  return (
    <div style={{
      background: "white", borderRadius: "14px",
      border: `1px solid ${selected ? "#16A34A" : "#ededed"}`,
      overflow: "hidden", transition: "border-color 0.18s ease",
    }}>
      <div
        onClick={onToggleOpen}
        style={{ padding: picker ? "12px 14px 14px" : "12px 14px 16px", cursor: "pointer" }}
      >
        {/* Line 1 — grey tag with its colored icon (+ bonus marker for
            stories), the scripts pill once selected, select circle pinned
            right. Then the category, the brief, and the one-liner. */}
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          {picker ? (
            <span style={{
              flexShrink: 1, minWidth: 0, display: "inline-flex", alignItems: "center", gap: "6px",
              fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 500,
              letterSpacing: "0.05em", textTransform: "uppercase", color: "#737373",
            }}>
              {PickIcon ? <PickIcon size={12} strokeWidth={2.2} style={{ color: pickIconColor, flexShrink: 0 }} /> : null}
              {/* One line, cut when long: with no script count beside it the
                  pillar has the row to itself (Karen 2026-10-11). */}
              <span style={{ minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{topic.categoryName}</span>
            </span>
          ) : (
          <span style={{
            flexShrink: 0, display: "inline-flex", alignItems: "center", gap: "5px",
            fontFamily: "'Geist Mono', monospace", fontSize: "9.5px", fontWeight: 700,
            letterSpacing: "0.08em", textTransform: "uppercase",
            padding: "2px 7px", borderRadius: "5px",
            color: "#737373", background: "#F4F5F6",
          }}>
            <TagIcon size={11} strokeWidth={2.2} style={{ color: tagColor }} />
            {tag}{topic.isStory ? " · BONUS" : ""}
          </span>
          )}
          <span style={{ flex: 1 }} />
          {/* No script count here (Karen 2026-10-11): every topic is one
              script, and the pill crowded the pillar. */}
          <button
            onClick={(e: any) => { e.stopPropagation(); onToggleSelect(); }}
            aria-label={selected ? "Unselect" : "Select"}
            style={{
              width: "20px", height: "20px", borderRadius: "50%", flexShrink: 0, padding: 0,
              border: selected ? "none" : "1px solid #d4d4d4",
              background: selected ? "#16a34a" : "white",
              display: "inline-flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
            }}
          >
            {selected && <Check size={11} strokeWidth={3} color="white" />}
          </button>
        </div>
        {topic.categoryName && !picker ? (
          <div style={{
            marginTop: "10px", fontFamily: "'Geist Mono', monospace", fontSize: "10px",
            fontWeight: 500, letterSpacing: "0.05em", textTransform: "uppercase", color: "#A3A3A3",
          }}>
            {topic.categoryName}
          </div>
        ) : null}
        {/* Closed, the title shows up to two lines (Karen 2026-10-11, was one);
            open, all of it. */}
        <div style={{
          marginTop: "10px",
          fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 500,
          color: "#171717", lineHeight: 1.45,
          ...(open ? {} : { display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" as any, overflow: "hidden" }),
        }}>
          {title}
        </div>
        {/* The context flows straight from the question (Karen 2026-10-11): in
            italics, as dark as the question but lighter, no label. A trend
            card's is the trend as it was found, with a link to read it all. */}
        {open && pickerContext ? (
          <div style={{ marginTop: "6px", fontFamily: "'Geist', sans-serif", fontSize: "14px", fontStyle: "italic", fontWeight: 300, color: "#171717", lineHeight: 1.5, whiteSpace: "pre-wrap" }}>
            {pickerContext}
          </div>
        ) : null}
        {open && pickerContext && isTrend && topic.sourceUrl ? (
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: "10px", marginTop: "10px", fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", letterSpacing: "0.04em" }}>
            <span style={{ color: "#A3A3A3", minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>Source · {sourceHost(topic.sourceUrl)}</span>
            <a
              href={topic.sourceUrl}
              target="_blank"
              rel="noreferrer"
              onClick={(e: any) => e.stopPropagation()}
              style={{ flexShrink: 0, color: "#A855F7", fontWeight: 600, textDecoration: "none" }}
            >
              {/^(.*\.)?(linkedin|x|twitter|reddit|tiktok|instagram|facebook|threads|youtube)\.(com|net)$/i.test(sourceHost(topic.sourceUrl)) ? "Read post" : "Read full news"} ↗
            </a>
          </div>
        ) : null}
      </div>
      {open && (
        <div style={picker ? { padding: "10px 14px 12px" } : { padding: "2px 14px 14px", borderTop: "1px solid #f5f5f5" }}>
          {/* The situation only where it explains something the title does
              not (Karen 2026-09-13): a story, a news moment, a comment to
              reply to, or a topic that has no subtopic yet. An evergreen
              subtopic stands on its own. */}
          {showSituation && (
          <div style={{ marginTop: "12px" }}>
            <div style={{ marginBottom: "6px", fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 600, letterSpacing: "0.09em", textTransform: "uppercase", color: "#16171A" }}>{topic.isStory ? "Your story" : topic.source === "Trending" ? "Online discussion" : topic.subtopic ? "The situation" : "Topic"}</div>
            {/* One box (Karen 2026-09-13): for a trending card the headline
                is the first paragraph and what is going on follows it, no
                separate line above. Same text size as the stance. */}
            {!topic.isStory && isTrend ? (
              /* Read only (Karen 2026-09-14): the discussion is there to be
                 read, never edited. Plain text in the title's type, no box:
                 the headline first, then what is going on. */
              <div style={{ fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 500, color: "#171717", lineHeight: 1.5, whiteSpace: "pre-wrap" }}>
                {topic.subtopic && name ? <div style={{ marginBottom: brief ? "8px" : 0 }}>{name}</div> : null}
                {brief ? <div>{brief}</div> : null}
              </div>
            ) : (
              <div style={{ background: "white", border: "1px solid #ededed", borderRadius: "10px", overflow: "hidden" }}>
                <AutoGrowTextarea
                  value={brief}
                  placeholder={topic.isStory ? "What happened, in a few lines" : "What this topic is about"}
                  onChange={(e: any) => onEdit({ summary: e.target.value })}
                  maxHeight={220}
                  style={{ ...fieldBox, border: "none", borderRadius: 0, background: "transparent" }}
                />
              </div>
            )}
            {topic.sourceUrl ? (
              /* Under the discussion, on the right, in purple, with room
                 below it (Karen 2026-09-14). */
              <div style={{ display: "flex", justifyContent: "flex-end", margin: "10px 0 12px" }}>
                <a
                  href={topic.sourceUrl}
                  target="_blank"
                  rel="noreferrer"
                  onClick={(e: any) => e.stopPropagation()}
                  style={{
                    display: "inline-flex", alignItems: "center", gap: "4px",
                    fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", letterSpacing: "0.04em",
                    color: "#A855F7", textDecoration: "none",
                  }}
                >
                  Source · {sourceHost(topic.sourceUrl)} ↗
                </a>
              </div>
            ) : null}
          </div>
          )}
          <div style={{ marginTop: showSituation ? "14px" : "12px" }}>
            <div style={{ marginBottom: "6px", fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 600, letterSpacing: "0.09em", textTransform: "uppercase", color: "#16171A" }}>{stanceLabel} *</div>
            {(stanceEditing || topic.isStory) ? (
              <div style={{ position: "relative" }}>
              {/* The onboarding form's flag (Karen 2026-10-11): purple outline
                  and a pill on the top-right corner while the box is empty. The
                  pill sits outside the clipped box so the corner never cuts it. */}
              {stanceNeedsHere && (
                <span style={{
                  position: "absolute", top: "-9px", right: "12px", zIndex: 4,
                  background: "white", border: "1px solid #e9d5ff", color: "#A855F7",
                  fontFamily: "'Geist Mono', monospace", fontSize: "9.5px", fontWeight: 600, letterSpacing: "0.04em",
                  textTransform: "uppercase", padding: "2px 9px", borderRadius: "999px",
                  boxShadow: "0 2px 8px rgba(168,85,247,0.18)", whiteSpace: "nowrap",
                }}>Needs your input</span>
              )}
              <div style={{ background: "white", border: stanceNeedsHere ? "1.5px solid #A855F7" : "1px solid #ededed", borderRadius: "10px", overflow: "hidden" }}>
                {freshAtEnd ? (
                  <div
                    ref={freshRef}
                    role="button"
                    tabIndex={0}
                    onClick={() => setFreshSpoken(null)}
                    onKeyDown={(e: any) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setFreshSpoken(null); } }}
                    style={{ ...fieldBox, border: "none", borderRadius: 0, background: "transparent", paddingBottom: "4px", whiteSpace: "pre-wrap", cursor: "text" }}
                  >
                    {stanceWithFresh}
                  </div>
                ) : (
                  <AutoGrowTextarea
                    value={stance}
                    onChange={(e: any) => onEdit({ stance: e.target.value })}
                    placeholder={stancePh}
                    maxHeight={220}
                    style={{ ...fieldBox, border: "none", borderRadius: 0, background: "transparent", paddingBottom: "4px" }}
                  />
                )}
                <VoiceMicButton
                  state={voice.state} secs={voice.secs} onToggle={voice.toggle}
                  label={topic.isStory ? "Record your story" : "Record your stance"}
                />
                {/* The way back out of editing (Karen 2026-09-13). Not while
                    the box is empty and waiting for their words. */}
                {!topic.isStory && !stanceNeedsHere && (
                  <div style={{ display: "flex", justifyContent: "flex-end", padding: "0 10px 8px" }}>
                    <button
                      onClick={() => setStanceEditing(false)}
                      style={{
                        background: "transparent", border: "none", padding: "4px 2px", cursor: "pointer",
                        fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 600, color: "#A855F7",
                      }}
                    >
                      Done
                    </button>
                  </div>
                )}
              </div>
              </div>
            ) : (
              <div style={{ position: "relative" }}>
                {/* A div, not a button: a button brings its own font on iOS,
                    so the stance never quite matched the discussion box. */}
                <div
                  ref={freshRef}
                  role="button"
                  tabIndex={0}
                  onClick={() => setStanceMenu((v: boolean) => !v)}
                  onKeyDown={(e: any) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setStanceMenu((v: boolean) => !v); } }}
                  style={{ ...fieldBox, cursor: "pointer", whiteSpace: "pre-wrap", minHeight: "46px", paddingRight: "34px" }}
                >
                  {stance
                    ? stanceWithFresh
                    : stanceFailedHere
                      ? <span style={{ color: "#B45309" }}>Flowy couldn&apos;t write this one. Tap to try again, or write your own.</span>
                      : <span style={{ color: "#A3A3A3" }}>Flowy is writing the stance…</span>}
                  <MoreHorizontal size={15} strokeWidth={2} style={{ position: "absolute", top: "11px", right: "11px", color: "#B4B4B4" }} />
                </div>
                {/* The menu opens upward: the card clips anything past its bottom
                    edge (overflow hidden for the rounded corners), and the stance
                    box is the last thing in it, so a menu dropping below was cut
                    off to a sliver. */}
                {stanceMenu ? (
                  <div style={{ position: "absolute", bottom: "calc(100% + 5px)", right: 0, zIndex: 30, background: "white", borderRadius: "9px", boxShadow: "0 6px 20px rgba(23,23,23,0.14)", overflow: "hidden", minWidth: "196px" }}>
                    {!stance && stanceFailedHere ? (
                      <button onClick={() => { setStanceMenu(false); onRetryStance?.(); }} className="fs-menu-row" style={{ display: "flex", alignItems: "center", gap: "9px", width: "100%", padding: "11px 13px", background: "white", border: "none", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#171717", textAlign: "left" }}>
                        <RotateCcw size={15} strokeWidth={1.9} style={{ color: "#A855F7" }} /> Try again
                      </button>
                    ) : (
                      <button onClick={() => { setStanceMenu(false); onOpenRegen("stance"); }} className="fs-menu-row" style={{ display: "flex", alignItems: "center", gap: "9px", width: "100%", padding: "11px 13px", background: "white", border: "none", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#171717", textAlign: "left" }}>
                        <Sparkles size={15} strokeWidth={1.9} style={{ color: "#A855F7" }} /> Rewrite with Flowy
                      </button>
                    )}
                    <button onClick={() => { setStanceMenu(false); setFreshSpoken(null); setStanceEditing(true); }} className="fs-menu-row" style={{ display: "flex", alignItems: "center", gap: "9px", width: "100%", padding: "11px 13px", background: "white", border: "none", borderTop: "1px solid #f4f4f4", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#171717", textAlign: "left" }}>
                      <Pencil size={15} strokeWidth={1.9} style={{ color: "#6C707A" }} /> Edit it yourself
                    </button>
                    {onSwap ? (
                      <button onClick={() => { setStanceMenu(false); onSwap(); }} className="fs-menu-row" style={{ display: "flex", alignItems: "center", gap: "9px", width: "100%", padding: "11px 13px", background: "white", border: "none", borderTop: "1px solid #f4f4f4", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#171717", textAlign: "left" }}>
                        <RotateCcw size={15} strokeWidth={1.9} style={{ color: "#A855F7" }} /> Swap this topic
                      </button>
                    ) : null}
                  </div>
                ) : null}
              </div>
            )}
            {regenOpen === `${topic.id}:stance` && regenBar("stance")}
          </div>
        </div>
      )}
      {/* How often the question was used: a quiet tag on the card's
          bottom-right corner, never between the pillar and the question
          (Karen 2026-10-11). */}
      {picker ? (
        <div style={{ display: "flex", justifyContent: "flex-end", padding: "0 12px 10px" }}>
          <span style={{
            fontFamily: "'Geist Mono', monospace", fontSize: "9.5px", fontWeight: 500, letterSpacing: "0.04em",
            color: "#8a8a8a", background: "#F4F5F6", padding: "2px 8px", borderRadius: "999px",
          }}>
            {usesLabel}
          </span>
        </div>
      ) : null}
    </div>
  );
}

// Blanks (Karen 2026-10-21): on the idea route the writer leaves {what the client said} where only the
// founder knows the detail. Each one shows as a chip under its box; tapping it selects that blank in the
// box, ready to type over.
const BLANK_RE = /\{[^{}\n]{2,160}\}/g;
function blanksIn(text: string): string[] {
  return String(text || "").match(BLANK_RE) || [];
}
function BlanksStrip({ text, fieldId }: { text: string; fieldId: string }) {
  const blanks = blanksIn(text);
  if (!blanks.length) return null;
  const pick = (b: string) => {
    const el = document.querySelector(`textarea[data-blank-field="${fieldId}"]`) as HTMLTextAreaElement | null;
    if (!el) return;
    const at = el.value.indexOf(b);
    if (at < 0) return;
    el.focus();
    el.setSelectionRange(at, at + b.length);
    // The box scrolls after nine lines, and a selection alone does not always bring the blank into view.
    if (el.scrollHeight > el.clientHeight) {
      el.scrollTop = Math.max(0, (at / Math.max(1, el.value.length)) * el.scrollHeight - el.clientHeight / 3);
    }
  };
  return (
    <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: "6px", marginTop: "8px" }}>
      <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 500, color: "#B45309" }}>Fill in:</span>
      {blanks.map((b, i) => (
        <button
          key={i}
          onClick={() => pick(b)}
          style={{
            display: "inline-flex", alignItems: "center", maxWidth: "100%", minHeight: "26px", padding: "3px 10px",
            borderRadius: "999px", background: "#FEF3C7", border: "1px solid #FCD34D", color: "#92400E",
            fontFamily: "'Geist', sans-serif", fontSize: "12.5px", lineHeight: 1.35, textAlign: "left", cursor: "pointer",
          }}
        >
          {b.slice(1, -1)}
        </button>
      ))}
    </div>
  );
}

// The in-rail review card (§5): a compact header of tags, the topic, the script's parts, the chat under it and
// the bottom dock with the way back, the add button and the chat box.
function RailReviewCard({
  item, n, total, format, formats, sections, name, fields, note,
  secOpen, secRework, mode, fbText, fmtMenuOpen, isTalking,
  onName, onField, onToggleSec, onOpenRework, onRework, reworkText, onReworkText,
  onToggleFmtMenu, onPickFormat, onRefineOpen, onRefineClose, onFbText, onRefineSend,
  onAdd, onClose, onBack, isDesktop, busy, delayS = 0, backLabel = "Go back", remaining = 0,
  addLabel = "Add", addWhere = "your board",
  chat = [], chatText = "", onChatText, chatSel = null, onChatSel, chatRec = "idle", onChatMic, onChatUndo,
  changed = [], canChat = false, onChatSend, appName = "",
}: any) {
  // The review reads as one page you can talk to (Karen 2026-10-22): no folding boxes, Change format and
  // Discard in the menu at the top, a chat under the script once it is written, and one button to approve.
  const [topMenuOpen, setTopMenuOpen] = useState(false);
  // Words selected in a part, waiting for a tap on Ask Flowy.
  const [pendingSel, setPendingSel] = useState<{ key: string; text: string } | null>(null);
  // The script opened on its own, full screen, to read and edit (Karen 2026-10-22).
  const [docFull, setDocFull] = useState(false);
  // The Add button opens a short list above it: add, add and write the next one, or add and write everything
  // left straight onto the board (Karen 2026-09-14, back as a split button 2026-10-22).
  const [addMenuOpen, setAddMenuOpen] = useState(false);
  const addWrapRef = useRef<any>(null);
  const chatInputRef = useRef<any>(null);
  const threadEndRef = useRef<any>(null);
  // Only a new line in the chat moves the view to it. On arrival the script opens at its first line, which the
  // rail itself takes care of (Karen 2026-10-22).
  const seenChatRef = useRef<number>(chat.length);
  useEffect(() => {
    if (chat.length === seenChatRef.current) return;
    seenChatRef.current = chat.length;
    try { threadEndRef.current?.scrollIntoView({ block: "nearest", behavior: "smooth" }); } catch { /* noop */ }
  }, [chat.length]);
  // The recording clock beside the mic, the same as the stance box shows (Karen 2026-10-22).
  const [recSecs, setRecSecs] = useState(0);
  useEffect(() => {
    if (chatRec !== "recording") { setRecSecs(0); return; }
    const t0 = Date.now();
    const id = setInterval(() => setRecSecs(Math.floor((Date.now() - t0) / 1000)), 500);
    return () => clearInterval(id);
  }, [chatRec]);
  // The add list closes on a tap anywhere else. The tap's own path is read too, so a tap on a row is never taken
  // for one outside and the list never closes before the row's choice lands (Karen 2026-10-22).
  useEffect(() => {
    if (!addMenuOpen) return;
    const off = (e: any) => {
      const w = addWrapRef.current;
      if (!w) return;
      const path = typeof e.composedPath === "function" ? e.composedPath() : [];
      if (path.includes(w) || w.contains(e.target)) return;
      setAddMenuOpen(false);
    };
    // Escape closes it too (only when full screen isn't open, so one press closes one thing).
    const onKey = (e: any) => { if (e.key === "Escape" && !document.querySelector(".rail-doc-full")) setAddMenuOpen(false); };
    document.addEventListener("mousedown", off);
    document.addEventListener("touchstart", off);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", off); document.removeEventListener("touchstart", off); document.removeEventListener("keydown", onKey); };
  }, [addMenuOpen]);
  // Full screen closes on Escape, and the page behind it stays still. Keyboard focus moves onto Close
  // when it opens and back to the button that opened it when it closes.
  useEffect(() => {
    if (!docFull) return;
    const onKey = (e: any) => { if (e.key === "Escape") setDocFull(false); };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const opener = document.activeElement as HTMLElement | null;
    const raf = requestAnimationFrame(() => (document.querySelector('.rail-doc-full button[aria-label="Close full screen"]') as HTMLElement | null)?.focus());
    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener("keydown", onKey); document.body.style.overflow = prev;
      if (opener && document.contains(opener)) opener.focus();
    };
  }, [docFull]);
  const askable = (key: string) => !!RAIL_SECTION_WRITER[key] || isPieceSec(key);
  const noteSelection = (key: string, e: any) => {
    const el = e.target;
    const a = el?.selectionStart ?? 0, b = el?.selectionEnd ?? 0;
    const picked = b > a ? String(el.value || "").slice(a, b).trim() : "";
    setPendingSel(picked && askable(key) ? { key, text: picked } : null);
  };
  const seedFor = (key: string): string => {
    if (fields[key] !== undefined) return fields[key];
    // Generation is pending: seed the card from the topic so review is real.
    if (key === "hook" || key === "visualHook") return item.topic;
    if (key === "body") return [item.summary, item.stance].filter(Boolean).join("\\n\\n");
    return "";
  };
  // Blanks the idea-route writer left for what only the founder knows (Karen 2026-10-21).
  const blankTotal = (sections || []).reduce((n: number, s: any) => n + (s.pieces
    ? s.pieces.reduce((m: number, p: any) => m + blanksIn(seedFor(p.key)).length, 0)
    : blanksIn(seedFor(s.key)).length), 0);
  // A static post has no filming to talk about: its pill is the slide count
  // (Karen 2026-09-14), and the minutes are left off.
  const byPieces = (sections || []).some((s: any) => isPieceSec(s.key));
  const isStatic = byPieces || (sections || []).some((s: any) => s.key === "slides");
  const slideCount = byPieces ? pieceSlideCount(fields) : isStatic ? slideRowsOf(fields.slides || "").length : 0;
  // Tags, not rows (Karen 2026-10-22): small mono pills, so the header takes one line when reading in the chat.
  // Light grey, near-ink words at a regular weight, each with a small icon, nothing purple (Karen 2026-10-22).
  const greyPill: React.CSSProperties = {
    display: "inline-flex", alignItems: "center", gap: "5px", whiteSpace: "nowrap",
    fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 400, letterSpacing: "0.06em",
    textTransform: "uppercase", padding: "3px 8px", borderRadius: "999px", lineHeight: 1.4,
    background: "#F4F4F5", color: "#3F3F46",
  };
  const tagIcon = { size: 11, strokeWidth: 1.8, style: { color: "#71717A", flexShrink: 0 } as React.CSSProperties };
  const menuRow: React.CSSProperties = {
    display: "flex", alignItems: "center", gap: "9px", width: "100%", padding: "11px 13px",
    background: "white", border: "none", cursor: "pointer",
    fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#171717", textAlign: "left",
  };
  const roundBtn: React.CSSProperties = {
    width: "28px", height: "28px", borderRadius: "50%", padding: 0, flexShrink: 0,
    background: "white", border: "none", boxShadow: "0 1px 2px rgba(22,23,26,0.06)",
    cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center",
  };
  const partLabel: React.CSSProperties = { fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 600, letterSpacing: "0.09em", textTransform: "uppercase", color: "#9aa0ab" };
  const changedTag: React.CSSProperties = { fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: "#15803D" };
  // Undo sits on the part Flowy changed, beside its Changed tag (Karen 2026-10-22), never under the chat line.
  const undoAt = (keys: string[]) => {
    for (let i = chat.length - 1; i >= 0; i--) {
      const u = chat[i] && chat[i].undo;
      if (u && keys.some((k) => Object.prototype.hasOwnProperty.call(u, k))) return i;
    }
    return -1;
  };
  const undoBtn = (keys: string[]) => {
    const at = undoAt(keys);
    if (at < 0 || busy) return null;
    return (
      <button
        type="button"
        onClick={() => onChatUndo(at, keys.filter((k) => Object.prototype.hasOwnProperty.call(chat[at].undo, k)))}
        // A bigger tap area on the phone, same look: the padding is taken back by the margin (QA 2026-10-22).
        style={{ background: "transparent", border: "none", padding: "8px 6px", margin: "-8px -4px", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 600, color: "#A855F7" }}
      >
        Undo
      </button>
    );
  };
  // The script's parts, one block each. A graphic's pieces sit one block per image (Karen 2026-10-11).
  const items: any[] = (() => {
    const out: any[] = [];
    for (const sec of (sections || [])) {
      if (!isPieceSec(sec.key)) { out.push(sec); continue; }
      const g = pieceGroupOf(sec.key.slice(PIECE_SEC.length));
      const last = out[out.length - 1];
      if (last && last.pieceGroup === g) { last.pieces.push(sec); continue; }
      out.push({ key: "pcg_" + g, pieceGroup: g, pieces: [sec] });
    }
    return out;
  })();
  // Text a size under the chat (Karen 2026-10-22): 14px on desktop. On the phone the boxes stay 16px, the size
  // that keeps iOS from zooming in.
  const bodySize = "14px";
  const askBtn = (style: React.CSSProperties) => (
    <button
      onMouseDown={(e: any) => e.preventDefault()}
      onClick={() => { onChatSel(pendingSel); setPendingSel(null); setTimeout(() => chatInputRef.current?.focus(), 0); }}
      style={{
        display: "inline-flex", alignItems: "center", gap: "5px",
        height: "28px", padding: "0 11px", borderRadius: "999px",
        background: "white", border: "1px solid rgba(168,85,247,0.30)", color: "#A855F7",
        fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 600, cursor: "pointer",
        boxShadow: "0 4px 12px -6px rgba(30,32,40,0.25)", ...style,
      }}
    >
      <Sparkles size={13} strokeWidth={2} /> Ask Flowy
    </button>
  );
  // The same tags and parts, in the chat and full screen. Full screen leaves Ask Flowy out: the chat box is
  // behind it.
  const docBody = (full: boolean) => {
    const idp = full ? "full-" : "";
    return (
      <div style={{ padding: full ? "0" : "0 18px 8px" }}>
        <div style={{ padding: "2px 0 4px", fontFamily: "'Geist', sans-serif", fontSize: "16px", fontWeight: 600, lineHeight: 1.35, letterSpacing: "-0.01em", color: "#171717", textWrap: "balance" as any }}>
          {item.topic || name}
        </div>
        {items.map((sec: any, si: number) => {
          if (sec.pieceGroup) {
            // A slide reads as a block of the page: its number, then its words in their own weights, no box
            // (Karen 2026-10-22). The cover is Slide 1 when there is one.
            const [slideName, slideTag] = pieceGroupTitle(sec.pieceGroup, fields).split(" · ");
            const look = (part: string): React.CSSProperties => part === "Title"
              ? { fontSize: bodySize, fontWeight: 600, color: "#171717", lineHeight: 1.5 }
              : part === "Label"
                ? { fontSize: "11px", fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: "#7E22CE", lineHeight: 1.5 }
                : part === "Subtitle"
                  ? { fontSize: bodySize, fontWeight: 500, color: "#3F3F46", lineHeight: 1.55 }
                  : part === "Call to action"
                    ? { fontSize: bodySize, fontWeight: 600, color: "#7E22CE", lineHeight: 1.55 }
                    : { fontSize: bodySize, fontWeight: 350, color: "#27272A", lineHeight: 1.65 };
            const keys = sec.pieces.map((p: any) => p.key);
            const groupChanged = keys.some((k: string) => changed.includes(k));
            return (
              <div key={sec.key} style={{ padding: "12px 0", borderTop: si ? "1px solid #F1F1F3" : "none" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "6px", marginBottom: "4px", flexWrap: "wrap" }}>
                  <span style={partLabel}>{slideName}{slideTag ? ` · ${slideTag}` : ""}</span>
                  {groupChanged && <span style={changedTag}>· Changed</span>}
                  {groupChanged && undoBtn(keys.filter((k: string) => changed.includes(k)))}
                </div>
                {sec.pieces.map((p: any) => {
                  const part = piecePart(p.key.slice(PIECE_SEC.length));
                  const pc = changed.includes(p.key);
                  return (
                    <div key={p.key} style={{ marginTop: "2px" }}>
                      <AutoGrowTextarea
                        value={seedFor(p.key)}
                        onChange={(e: any) => onField(p.key, e.target.value)}
                        onSelect={full ? undefined : (e: any) => noteSelection(p.key, e)}
                        data-blank-field={`${idp}${n}:${p.key}`}
                        aria-label={`${slideName} ${part}`}
                        style={{
                          width: "calc(100% + 13px)", boxSizing: "border-box", display: "block", marginLeft: "-13px",
                          background: pc ? "#F0FDF4" : "transparent",
                          border: "none", borderLeft: pc ? "3px solid #22C55E" : "3px solid transparent",
                          borderRadius: "4px", padding: "3px 8px 3px 10px",
                          fontFamily: "'Geist', sans-serif", outline: "none", resize: "none" as any,
                          transition: "background 0.3s ease",
                          ...look(part),
                        }}
                      />
                      <BlanksStrip text={seedFor(p.key)} fieldId={`${idp}${n}:${p.key}`} />
                      {!full && pendingSel && pendingSel.key === p.key && canChat && !busy && askBtn({ margin: "6px 0 4px" })}
                    </div>
                  );
                })}
              </div>
            );
          }
          // One page: each part under a small label, no folding and no box (Karen 2026-10-22).
          const isChanged = changed.includes(sec.key);
          const showAsk = !full && pendingSel && pendingSel.key === sec.key && canChat && !busy;
          return (
            <div key={sec.key} style={{ padding: "8px 0" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "6px", flexWrap: "wrap" }}>
                <span style={partLabel}>{sec.label}</span>
                {isChanged && <span style={changedTag}>· Changed</span>}
                {isChanged && undoBtn([sec.key])}
              </div>
              <AutoGrowTextarea
                value={seedFor(sec.key)}
                onChange={(e: any) => onField(sec.key, e.target.value)}
                onSelect={full ? undefined : (e: any) => noteSelection(sec.key, e)}
                data-blank-field={`${idp}${n}:${sec.key}`}
                aria-label={sec.label}
                placeholder={`Flowy writes the ${sec.label.toLowerCase()} here.`}
                style={{
                  width: "calc(100% + 13px)", boxSizing: "border-box", marginTop: "4px", display: "block",
                  background: isChanged ? "#F0FDF4" : "transparent",
                  border: "none", borderLeft: isChanged ? "3px solid #22C55E" : "3px solid transparent",
                  borderRadius: "4px", padding: "4px 8px 4px 10px", marginLeft: "-13px",
                  fontFamily: "'Geist', sans-serif", fontSize: bodySize,
                  fontWeight: 350, lineHeight: 1.65, color: "#27272A",
                  outline: "none", resize: "none" as any,
                  transition: "background 0.3s ease",
                }}
              />
              <BlanksStrip text={seedFor(sec.key)} fieldId={`${idp}${n}:${sec.key}`} />
              {showAsk && askBtn({ marginTop: "6px" })}
            </div>
          );
        })}
      </div>
    );
  };
  // The header's tags: which script, the style's app name, the slides or the filming, and the format.
  const tags = (
    <>
      <span style={{ fontFamily: "'Geist Mono', monospace", fontSize: "11px", fontWeight: 700, letterSpacing: "0.09em", textTransform: "uppercase", color: "#171717", whiteSpace: "nowrap", marginRight: "2px" }}>
        Script {n} of {total}
      </span>
      {appName ? <span style={greyPill}><Sparkles {...tagIcon} />{appName}</span> : null}
      {/* A carousel or graphic needs no format tag: the slide count says it. A single graphic is one image. */}
      {isStatic ? (
        isCarouselFormat(format) || slideCount > 1 ? (
          <span style={greyPill}><Layers {...tagIcon} />{slideCount > 0 ? `${slideCount} slide${slideCount === 1 ? "" : "s"}` : "Slides"}</span>
        ) : (
          <span style={greyPill}><Image {...tagIcon} />1 image</span>
        )
      ) : (
        <>
          <span style={greyPill}>
            {isTalking ? <Video {...tagIcon} /> : <VideoOff {...tagIcon} />}
            {isTalking ? "Filming" : "No filming"}
          </span>
          <span style={greyPill}>
            <Clock {...tagIcon} />
            {FORMAT_FILMING_MINUTES[format] !== undefined
              ? `${Math.max(FORMAT_FILMING_MINUTES[format], SHOOT_FLOOR_MINUTES)} min`
              : `~${SHOOT_FLOOR_MINUTES} min`}
          </span>
          {format ? <span style={greyPill}><Clapperboard {...tagIcon} />{format}</span> : null}
        </>
      )}
    </>
  );
  // What Flowy last did to this script, one quiet line under the tags (Karen 2026-10-21).
  const noteLine = note ? (
    <div title={note} style={{ marginTop: "6px", fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", color: "#71717A", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
      {note}
    </div>
  ) : null;
  const hasAddMenu = remaining > 0;
  // A choice in the add list: the list closes and the add happens once.
  const pickAdd = (how: "one" | "next" | "all") => {
    setAddMenuOpen(false);
    if (busy) return;
    onAdd(how);
  };
  return (
    // One centred reading column, like a chat (Karen 2026-10-22): 720px at most, never the rail's full width.
    <div style={{ maxWidth: "720px", margin: "0 auto" }}>
    <div className="rail-review-card" style={{
      marginTop: "14px", background: "white", border: "1px solid #ededed",
      borderRadius: "16px", overflow: "visible",
      boxShadow: "0 1px 2px rgba(22,23,26,0.04), 0 12px 28px -20px rgba(30,32,40,0.18)",
      animation: "fsBubbleIn 0.2s cubic-bezier(0.16,1,0.3,1) both",
      animationDelay: `${delayS}s`,
    }}>
      <div style={{ padding: "14px 14px 8px 18px" }}>
        <div style={{ display: "flex", alignItems: "flex-start", gap: "8px" }}>
          <div style={{ flex: 1, minWidth: 0, display: "flex", alignItems: "center", gap: "6px", flexWrap: "wrap", paddingTop: "4px" }}>
            {tags}
          </div>
          <span style={{ position: "relative", display: "inline-flex", gap: "4px", flexShrink: 0 }}>
            <button onClick={() => { setTopMenuOpen(false); setDocFull(true); }} aria-label="Open full screen" title="Open full screen" style={roundBtn}>
              <Maximize2 size={13} strokeWidth={2.2} style={{ color: "#737373" }} />
            </button>
            <button
              onClick={() => { setTopMenuOpen(!topMenuOpen); if (fmtMenuOpen) onToggleFmtMenu(); }}
              aria-label="More: change format or discard"
              style={roundBtn}
            >
              <MoreHorizontal size={16} strokeWidth={2.2} style={{ color: "#737373" }} />
            </button>
            {topMenuOpen && (
              <div style={{ position: "absolute", right: 0, top: "34px", zIndex: 30, minWidth: "220px", background: "white", border: "1px solid #ededed", borderRadius: "12px", overflow: "hidden", boxShadow: "0 1px 2px rgba(22,23,26,.04),0 12px 28px -16px rgba(30,32,40,.28)", animation: "fsBubbleIn 0.16s cubic-bezier(0.16,1,0.3,1) both" }}>
                <button className="fs-menu-row" onClick={onToggleFmtMenu} style={menuRow}>
                  <Clapperboard size={15} strokeWidth={1.8} style={{ color: "#6C707A" }} />
                  <span style={{ flex: 1 }}>Change format</span>
                  <ChevronDown size={14} strokeWidth={2} style={{ color: "#737373", transform: fmtMenuOpen ? "rotate(180deg)" : "none", transition: "transform 0.18s ease" }} />
                </button>
                {fmtMenuOpen && (
                  <div style={{ maxHeight: "240px", overflowY: "auto", borderTop: "1px solid #f4f4f4" }}>
                    {formats.map((f: string) => (
                      <div
                        key={f}
                        onClick={() => { setTopMenuOpen(false); onPickFormat(f); }}
                        className="fs-menu-row"
                        style={{ display: "flex", alignItems: "center", gap: "8px", padding: "9px 13px 9px 37px", fontFamily: "'Geist', sans-serif", fontSize: "13px", color: "#171717", cursor: "pointer" }}
                      >
                        <span style={{ flex: 1 }}>{f}</span>
                        {f === format && <Check size={14} strokeWidth={2.2} style={{ color: "#A855F7" }} />}
                      </div>
                    ))}
                  </div>
                )}
                <button className="fs-menu-row" onClick={() => { setTopMenuOpen(false); if (!busy) onClose(); }} style={{ ...menuRow, borderTop: "1px solid #f4f4f4", color: busy ? "#A3A3A3" : "#B91C1C" }}>
                  <Trash2 size={15} strokeWidth={1.8} /> Discard
                </button>
              </div>
            )}
          </span>
        </div>
        {noteLine}
      </div>
      {docBody(false)}
    </div>
    {/* The chat under the script (Karen 2026-10-22). Flowy's lines are plain text at the chat's size, the
        person's are a compact grey bubble that fits its words, on the right. */}
    <div style={{ animation: "fsBubbleIn 0.2s cubic-bezier(0.16,1,0.3,1) both", animationDelay: `${delayS + 0.15}s` }}>
        <div style={{ padding: "18px 0 0" }}>
          {chat.map((m: any, i: number) => m.from === "user" ? (
            <div key={i} style={{ display: "flex", justifyContent: "flex-end", marginBottom: "18px" }}>
              {/* The same grey bubble Flowy's lines used to wear (Karen 2026-10-22). */}
              <div className="strat-bubble" style={{ maxWidth: "75%", color: "#171717", borderRadius: "18px 18px 4px 18px", padding: "10px 14px", fontFamily: "'Geist', sans-serif", fontSize: "15px", lineHeight: 1.55, whiteSpace: "pre-wrap", overflowWrap: "anywhere" }}>{m.text}</div>
            </div>
          ) : (
            <div key={i} style={{ marginBottom: "18px", maxWidth: "640px", fontFamily: "'Geist', sans-serif", fontSize: "15px", fontWeight: 400, lineHeight: 1.6, color: "#171717" }}>
              {m.text}
            </div>
          ))}
          {busy && chat.length > 0 ? (
            <div style={{ fontFamily: "'Geist Mono', monospace", fontSize: "12px", fontWeight: 500, color: "#A855F7", margin: "-8px 0 18px" }}>
              {chat[chat.length - 1].from === "user" ? "Reading…" : "Rewriting…"}
            </div>
          ) : null}
          {/* The scroll stops above the chat box, so the newest line is never under it. */}
          <div ref={threadEndRef} style={{ scrollMarginBottom: "170px" }} />
        </div>
    </div>
        {/* Anchored to the bottom of the screen: the way back and the approve button on one row, then the chat
            box, always there. The box waits, greyed, until the script is written (Karen 2026-10-22). */}
        <div style={railDockStyle(isDesktop)}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "10px" }}>
            <button
              onClick={onBack}
              className="uppercase"
              style={{ flexShrink: 0, background: "transparent", border: "none", cursor: "pointer", fontFamily: "'Geist Mono', monospace", fontSize: "11px", fontWeight: 500, letterSpacing: "0.1em", color: "#A855F7", padding: "6px 0", whiteSpace: "nowrap" }}
            >
              ‹ {backLabel}
            </button>
            <div style={{ flex: 1, minWidth: 0, textAlign: "right", fontFamily: "'Geist', sans-serif", fontSize: "12.5px", lineHeight: 1.4, color: "#B45309" }}>
              {blankTotal > 0 ? `${blankTotal === 1 ? "1 blank" : `${blankTotal} blanks`} to fill in before you ${isStatic ? "post" : "film"} it.` : null}
            </div>
            {/* One button that always opens the list (Karen 2026-10-22): a choice in it is the add itself, made once,
                with nothing asked again. With nothing left to write there is no choice to make, so it adds. */}
            <div ref={addWrapRef} style={{ position: "relative", display: "inline-flex", flexShrink: 0, borderRadius: "8px", boxShadow: "0 6px 16px -8px rgba(168,85,247,0.7)", opacity: busy ? 0.45 : 1 }}>
              <button
                onClick={() => {
                  if (busy) return;
                  if (hasAddMenu) { setAddMenuOpen(!addMenuOpen); return; }
                  onAdd("one");
                }}
                disabled={busy}
                aria-haspopup={hasAddMenu ? "menu" : undefined}
                aria-expanded={hasAddMenu ? (addMenuOpen ? "true" : "false") : undefined}
                style={{
                  height: "40px", padding: hasAddMenu ? "0 12px 0 16px" : "0 18px", borderRadius: "8px",
                  background: BRAND_GRADIENT, border: "none", color: "white",
                  fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 600, whiteSpace: "nowrap",
                  cursor: busy ? "default" : "pointer",
                  opacity: busy ? 0.55 : 1, transition: "opacity 0.18s ease",
                  display: "inline-flex", alignItems: "center", gap: "6px",
                }}
              >
                <Check size={14} strokeWidth={2.4} />
                {addLabel}
                {hasAddMenu && !busy && (
                  <ChevronUp size={15} strokeWidth={2.4} style={{ marginLeft: "2px", transform: addMenuOpen ? "rotate(180deg)" : "none", transition: "transform 0.18s ease" }} />
                )}
              </button>
              {addMenuOpen && hasAddMenu && (
                // Opens above, like the ⋯ menu, so it never drops under the chat box.
                <div role="menu" style={{ position: "absolute", right: 0, bottom: "46px", zIndex: 40, minWidth: "230px", background: "white", border: "1px solid #ededed", borderRadius: "12px", overflow: "hidden", boxShadow: "0 1px 2px rgba(22,23,26,.04),0 12px 28px -16px rgba(30,32,40,.28)", animation: "fsBubbleIn 0.16s cubic-bezier(0.16,1,0.3,1) both" }}>
                  <button role="menuitem" className="fs-menu-row" onClick={() => pickAdd("one")} style={menuRow}>
                    <Check size={15} strokeWidth={2} style={{ color: "#A855F7" }} /> Add this
                  </button>
                  <button role="menuitem" className="fs-menu-row" onClick={() => pickAdd("next")} style={{ ...menuRow, borderTop: "1px solid #f4f4f4" }}>
                    <ArrowRight size={15} strokeWidth={2} style={{ color: "#A855F7" }} /> Add and write next
                  </button>
                  {remaining > 1 && (
                    <button role="menuitem" className="fs-menu-row" onClick={() => pickAdd("all")} style={{ ...menuRow, borderTop: "1px solid #f4f4f4" }}>
                      <ChevronsRight size={15} strokeWidth={2} style={{ color: "#A855F7" }} /> Add and write all
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
          {chatSel ? (
            <div style={{ display: "flex", alignItems: "center", gap: "6px", marginBottom: "6px", fontFamily: "'Geist', sans-serif", fontSize: "12.5px", color: "#7E22CE" }}>
              <Sparkles size={12} strokeWidth={2} />
              <span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>About: &ldquo;{chatSel.text}&rdquo;</span>
              <button onClick={() => onChatSel(null)} aria-label="Clear the selected words" style={{ background: "transparent", border: "none", padding: 0, cursor: "pointer", display: "inline-flex" }}>
                <X size={13} strokeWidth={2} style={{ color: "#A3A3A3" }} />
              </button>
            </div>
          ) : null}
          {(() => {
            const off = !canChat || busy;
            return (
              <RailComposer
                inputRef={chatInputRef}
                value={chatText}
                onChange={(v: string) => onChatText(v)}
                onSend={() => { if (!off && chatText.trim()) onChatSend(); }}
                placeholder={!canChat ? "Writing the script…" : chatRec === "processing" ? "Transcribing…" : "What should change?"}
                off={off}
                rec={chatRec}
                recSecs={recSecs}
                onMic={onChatMic}
                isDesktop={isDesktop}
              />
            );
          })()}
        </div>
        {/* The script on its own, full screen: the same parts, edited the same way. Close goes back to the chat. */}
        {docFull && createPortal(
          <div
            className="rail-screens rail-doc-full"
            role="dialog"
            aria-modal="true"
            aria-label={`Script ${n} of ${total}`}
            style={{ position: "fixed", inset: 0, zIndex: 10000, background: "#FFFFFF", overflowY: "auto", WebkitOverflowScrolling: "touch" as any }}
          >
            {/* Block styles don't always reach portals: the phone's 16px boxes and the menu keyframes travel along. */}
            <style>{`
              @keyframes fsBubbleIn { from { opacity: 0; transform: translateY(5px) } to { opacity: 1; transform: translateY(0) } }
              @media (max-width: 999px) { .rail-doc-full textarea { font-size: 16px !important; } }
            `}</style>
            <div style={{ position: "sticky", top: 0, zIndex: 2, background: "rgba(255,255,255,0.96)", borderBottom: "1px solid #F1F1F3" }}>
              <div style={{ maxWidth: "720px", margin: "0 auto", padding: "12px 16px", display: "flex", alignItems: "flex-start", gap: "10px", boxSizing: "border-box" }}>
                <div style={{ flex: 1, minWidth: 0, display: "flex", alignItems: "center", gap: "6px", flexWrap: "wrap", paddingTop: "5px" }}>
                  {tags}
                </div>
                <button
                  onClick={() => setDocFull(false)}
                  aria-label="Close full screen"
                  style={{ flexShrink: 0, height: "32px", padding: "0 12px", borderRadius: "999px", background: "#F4F4F5", border: "none", cursor: "pointer", display: "inline-flex", alignItems: "center", gap: "6px", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, color: "#171717" }}
                >
                  <Minimize2 size={13} strokeWidth={2.2} /> Close
                </button>
              </div>
            </div>
            <div style={{ maxWidth: "720px", margin: "0 auto", padding: "20px 16px 64px", boxSizing: "border-box" }}>
              {docBody(true)}
            </div>
          </div>,
          document.body
        )}
    </div>
  );
}

// The rail's sticky bottom: approve and the chat box, over a fade of the rail's own colour. The screen around it
// fills the rail's height, so on a short page it still sits on the rail's bottom edge.
const railDockStyle = (isDesktop?: boolean): React.CSSProperties => ({
  position: "sticky", bottom: 0, zIndex: 25, margin: "0 -4px",
  padding: "10px 4px calc(12px + env(safe-area-inset-bottom, 0px))",
  // Solid behind the approve button and the box, so no message shows through beside them; the soft fade sits above.
  // On the phone it is the sheet's own grey, so no lighter band shows around the box.
  // Flowy block: the rail is white on every width.
  background: "#FFFFFF",
  boxShadow: "0 -14px 14px -2px #FFFFFF",
});

// The rail's chat box (Karen 2026-10-22): it grows with the words up to about seven lines, then scrolls. The mic
// and send sit inside it, bottom right. The mic is the stance box's own: a solid purple circle with a white mic,
// red with a white square while recording.
function RailComposer({ inputRef, value, onChange, onSend, placeholder, off, rec = "idle", recSecs = 0, onMic, isDesktop, ariaLabel = "What should change?" }: any) {
  const recording = rec === "recording";
  // 16px on the phone keeps iOS from zooming in on the box.
  const size = isDesktop ? 15 : 16;
  return (
    <div style={{
      background: "white", border: "1px solid #E5E5E5", borderRadius: "22px",
      padding: "12px 12px 10px 16px", opacity: off ? 0.6 : 1,
      boxShadow: "0 8px 24px -16px rgba(30,32,40,0.3)",
    }}>
      <AutoGrowTextarea
        innerRef={inputRef}
        value={value}
        onChange={(e: any) => onChange(e.target.value)}
        onKeyDown={(e: any) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); onSend(); } }}
        placeholder={placeholder}
        disabled={off}
        aria-label={ariaLabel}
        maxHeight={Math.round(size * 1.5 * 7)}
        style={{
          width: "100%", boxSizing: "border-box", display: "block", minHeight: `${size * 1.5}px`,
          border: "none", outline: "none", background: "transparent", padding: 0, margin: 0,
          fontFamily: "'Geist', sans-serif", fontSize: `${size}px`, lineHeight: 1.5, color: "#171717",
        }}
      />
      <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: "8px", marginTop: "8px" }}>
        {rec !== "idle" && (
          <span style={{
            fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 500,
            letterSpacing: "0.06em", textTransform: "uppercase",
            color: recording ? "#DC2626" : "#A3A3A3",
          }}>
            {recording ? `Recording · ${mmssClock(recSecs)}` : "Transcribing…"}
          </span>
        )}
        <button
          type="button"
          onClick={(e: any) => { e.stopPropagation(); if (off && !recording) return; onMic && onMic(); }}
          disabled={(off && !recording) || rec === "processing"}
          aria-label={recording ? "Stop recording" : "Record"}
          title={recording ? "Stop recording" : "Record"}
          // The same square as Send, as a secondary button: light purple with a purple mic, red while it
          // records (Karen, 2026-10-23).
          style={{
            width: "32px", height: "32px", borderRadius: "8px", padding: 0, flexShrink: 0, boxSizing: "border-box",
            background: recording ? "#DC2626" : "#F5EEFE",
            border: recording ? "1px solid #DC2626" : "1px solid rgba(168,85,247,0.30)",
            cursor: rec === "processing" ? "wait" : off && !recording ? "default" : "pointer",
            opacity: rec === "processing" ? 0.6 : 1,
            display: "inline-flex", alignItems: "center", justifyContent: "center",
          }}
        >
          {recording
            ? <span style={{ width: "10px", height: "10px", borderRadius: "2px", background: "white" }} />
            : <Mic size={15} strokeWidth={2.2} style={{ color: "#A855F7" }} />}
        </button>
        <button
          type="button"
          onClick={() => { if (!off && String(value || "").trim()) onSend(); }}
          disabled={off || !String(value || "").trim()}
          aria-label="Send"
          style={{ width: "32px", height: "32px", borderRadius: "8px", padding: 0, flexShrink: 0, background: BRAND_GRADIENT, border: "none", boxShadow: "0 4px 12px -4px rgba(168,85,247,.55)", opacity: off || !String(value || "").trim() ? 0.45 : 1, cursor: off || !String(value || "").trim() ? "default" : "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center" }}
        >
          <ArrowUp size={16} strokeWidth={2.4} style={{ color: "white" }} />
        </button>
      </div>
    </div>
  );
}

// The rail's chat box on every screen but the review: the same box, greyed, at the bottom from the very first
// screen (Karen 2026-10-22). It opens once a script is written.
function RailChatWaiting({ isDesktop, placeholder = "Writing the script…" }: { isDesktop?: boolean; placeholder?: string }) {
  return (
    <>
      {/* Room for the box's fade, so the last box above it shows its bottom edge in full (Karen 2026-10-22). */}
      <div aria-hidden="true" style={{ height: "20px", flexShrink: 0 }} />
      <div style={railDockStyle(isDesktop)}>
        <RailComposer value="" onChange={() => {}} onSend={() => {}} placeholder={placeholder} off isDesktop={isDesktop} />
      </div>
    </>
  );
}

// Flowy's own line on the review page: plain text, no bubble, the size of the chat (Karen 2026-10-22).
function RailFlowyLine({ children, delayIndex = 0 }: { children: React.ReactNode; delayIndex?: number }) {
  return (
    <div
      data-rail-keep="true"
      className="strat-bubble-in"
      style={{
        maxWidth: "640px", margin: "0 0 4px", fontFamily: "'Geist', sans-serif", fontSize: "15px",
        fontWeight: 400, lineHeight: 1.6, color: "#171717",
        animationDelay: `${RAIL_TYPING_S + delayIndex * 0.35}s`,
      }}
    >
      {children}
    </div>
  );
}

// ── Create Media (Karen 2026-10-22, the approved mockup create_media_mock.html) ─────────────────────────────
// The rail's second route: the workspace, the brand, video or static, how many, then one card per item. The
// button under the cards wakes up once every card has what it needs. Editing and designing are not connected
// yet, so that button only says so and sends nothing, and nothing is written to Airtable. Footage stays on the
// device: it shows as a preview and is never uploaded. Write with Flowy on the slides is live: the FD5 slides
// writer answers with words only and saves nothing. The results (Ready to Schedule, Re-do) are built and show
// only with ?mediaResults=1 until the edit and design calls are wired in, then MEDIA_RESULTS_LIVE turns them on.
const MEDIA_RESULTS_LIVE = false;
const mediaResultsOn = (): boolean => {
  if (MEDIA_RESULTS_LIVE) return true;
  try { return new URLSearchParams(window.location.search).has("mediaResults"); } catch { return false; }
};
const MEDIA_MAX = 10;
// The Studio's own names and words (creative-hub-v1.tsx EDIT_STYLES and FLOWY_LOOKS), the first sentence of each.
const MEDIA_EDIT_TYPES: { key: string; name: string; says: string }[] = [
  { key: "loop", name: "Loop Silent Clip", says: "One clip on a loop, with a line of text over it." },
  { key: "talking", name: "Talking Clips", says: "Your clips cut together, with a hook and captions." },
  { key: "voiceover", name: "Clips and Voiceover", says: "Your clips under your voiceover, with a hook and captions." },
];
const MEDIA_LOOKS: { key: string; name: string; says: string }[] = [
  { key: "listicle", name: "List", says: "Numbered points, one per slide." },
  { key: "quotes", name: "Text-lead", says: "Short, bold lines that carry each slide on their own." },
  { key: "explainer", name: "Visual Explainer", says: "An idea broken down with simple drawn visuals." },
  { key: "comparisons", name: "Comparison", says: "Two sides: before and after, myth and truth." },
  { key: "story", name: "Story", says: "A story told with your photos. Needs at least one photo." },
  { key: "tutorial", name: "Tutorial", says: "Step by step, one step per slide." },
];
// A carousel's images in the order they read: the cover, up to eight slides, then the closing. Each is a group
// of the piece fields (PIECE_FIELD), the same places the review card and the slides writer use. A single graphic
// is the one group "s1", the way the Studio keeps it.
const MEDIA_MIDDLE = ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8"];
const mediaPartsOf = (g: string) => (g === "closing" ? ["Title", "CTA"] : ["Title", "Subtitle"]);
const mediaPieceKey = (g: string, part: string) => (g === "cover" ? `cover${part}`
  : g === "closing" ? (part === "CTA" ? "closingCta" : `closing${part}`) : `${g}${part}`);
// Numbered the way pieceGroupTitle numbers a full carousel: the cover is Slide 1, the closing comes last.
const mediaSlideTitle = (single: boolean, groups: string[], g: string) => {
  if (single) return "Graphic";
  const at = groups.indexOf(g) + 1;
  return g === "cover" ? "Slide 1 · Cover" : g === "closing" ? `Slide ${at} · Closing` : `Slide ${at}`;
};
// A file on a media card. `uploadId` is its Uploads row when it came from the picker's library or was uploaded
// through it, `thumb` the picture Airtable made of it. A file kept on the device only has neither.
// `mediaRowId` is a Flowshift Media row picked in the picker: it is copied into an Uploads row on the card's
// record, the Studio's way. `pairId` is the Script Files row that attaches it to the record.
type MediaFile = { id: string; name: string; kind: "video" | "image"; url: string; uploadId?: string; thumb?: string;
  mediaRowId?: string; mediaUsedFor?: string[]; filename?: string; pairId?: string };
type MediaCard = {
  id: string; open: boolean;
  // The card's own Content record, made before the cards show (Karen, 2026-10-23). Empty only if the create
  // was refused: the card still works, nothing of it is saved. `handed` once Edit now or Design now put it
  // on the board, so Start Over leaves it there.
  recordId: string; handed: boolean;
  clips: MediaFile[]; editType: string;
  format: "carousel" | "graphic"; look: string; groups: string[]; pieces: Record<string, string>;
  photos: MediaFile[]; copyReady: boolean;
  // The results, built for when editing and designing are wired in.
  result: { version: number; queued: "" | "queue" | "captions" } | null;
  redo: boolean; redoNote: string;
};
type MediaLine = { from: "flowy" | "user"; text: string; at: number; step?: string };
type MediaRouteState = {
  step: "ws" | "brand" | "kind" | "count" | "cards";
  ask: string;
  log: MediaLine[];
  after: MediaLine[];
  brandId: string; brandName: string;
  kind: "video" | "static" | null;
  count: number;
  cards: MediaCard[];
  working: { ids: string[]; idx: number; startedAt: number } | null;
  redoAll: boolean;
  // The cards' records are being made: the cards wait for them.
  creating: boolean;
};
function newMediaRoute(hello: string): MediaRouteState {
  return {
    step: "ws", ask: "", log: hello ? [{ from: "flowy", text: hello, at: 0 }] : [], after: [],
    brandId: "", brandName: "", kind: null, count: 1, cards: [], working: null, redoAll: false, creating: false,
  };
}
const newMediaCard = (i: number, recordId = ""): MediaCard => ({
  // Every card starts closed, and Flowy's line above them says what to do (Karen, 2026-10-23).
  id: "m" + i + "-" + Math.random().toString(36).slice(2, 7), open: false, recordId, handed: false,
  // The Studio's carousel: the cover, one slide and the closing (creative-hub-v1.tsx copyEditor).
  clips: [], editType: "", format: "carousel", look: "", groups: ["cover", "s1", "closing"], pieces: {},
  photos: [], copyReady: false, result: null, redo: false, redoNote: "",
});
const mediaGroupsOf = (c: MediaCard) => (c.format === "graphic" ? ["s1"] : c.groups);
// What a card still needs before the button wakes up (the mockup's own rules).
function mediaMissing(kind: "video" | "static" | null, c: MediaCard): string[] {
  const m: string[] = [];
  if (kind === "video") {
    if (!c.clips.length) m.push("footage");
    if (!c.editType) m.push("edit type");
    return m;
  }
  if (!c.look) m.push("design style");
  const groups = mediaGroupsOf(c);
  const words = groups.filter((g) => g !== "closing").every((g) => String(c.pieces[mediaPieceKey(g, "Title")] || "").trim());
  if (!words) m.push("copy");
  if (c.look === "story" && !c.photos.length) m.push("a photo");
  if (!c.copyReady) m.push("the ready tick");
  return m;
}
const mediaListWords = (m: string[]) => (m.length < 2 ? m.join("") : `${m.slice(0, -1).join(", ")} and ${m[m.length - 1]}`);
const mediaFilesFrom = (list: FileList | null, only: "video" | "any"): MediaFile[] => Array.from(list || [])
  .filter((f) => only === "any" || /^video\//.test(f.type) || EXT_VIDEO.test(f.name))
  .map((f) => {
    let url = "";
    try { url = URL.createObjectURL(f); } catch { url = ""; }
    const kind: "video" | "image" = /^video\//.test(f.type) || EXT_VIDEO.test(f.name) ? "video" : "image";
    return { id: Math.random().toString(36).slice(2, 10), name: f.name, kind, url };
  });
// Only a file kept on the device has a blob address to give back. A library file's address is its own.
const mediaFreeFile = (f: MediaFile) => { try { if (f.url && f.url.startsWith("blob:")) URL.revokeObjectURL(f.url); } catch { /* noop */ } };

// The drawn tiles on the Edit Type and Design Style pickers: shapes only, never pictures (Karen's rule).
function MediaTileArt({ k }: { k: string }) {
  const box = (s: React.CSSProperties, key?: any) => <div key={key} style={{ position: "absolute", ...s }} />;
  const ink = "#2b2540", soft = "#b9b2a6", slate = "#3c4a55";
  const parts: Record<string, React.ReactNode> = {
    loop: <>{box({ inset: 0, background: slate })}{box({ left: 8, right: 8, top: 30, height: 6, borderRadius: 2, background: "#fff" })}{box({ left: 14, right: 14, top: 40, height: 4, borderRadius: 2, background: "rgba(255,255,255,.6)" })}{box({ right: 6, bottom: 6, width: 12, height: 12, border: "2px solid #fff", borderRightColor: "transparent", borderRadius: "50%", boxSizing: "border-box" })}</>,
    talking: <>{box({ inset: 0, background: slate })}{box({ left: 21, top: 20, width: 16, height: 16, borderRadius: "50%", background: "#9fb0bd" })}{box({ left: 15, top: 36, width: 28, height: 30, borderRadius: "14px 14px 0 0", background: "#9fb0bd" })}{box({ left: 7, right: 7, top: 7, height: 8, borderRadius: 2, background: "#fff" })}{box({ left: 10, right: 10, bottom: 12, height: 4, borderRadius: 2, background: "#FACC15" })}</>,
    voiceover: <>{box({ inset: 0, background: slate })}{box({ left: 7, right: 7, top: 7, height: 8, borderRadius: 2, background: "#fff" })}{box({ left: 9, top: 30, width: 14, height: 14, borderRadius: "50%", background: "#fff" })}{[6, 10, 5, 12, 7, 9].map((h, i) => box({ left: 27 + i * 4, top: 37 - h / 2, width: 2, height: h, borderRadius: 1, background: "#fff" }, i))}{box({ left: 10, right: 10, bottom: 12, height: 4, borderRadius: 2, background: "#FACC15" })}</>,
    listicle: <><div style={{ position: "absolute", left: 8, top: 9, fontFamily: "'Geist', sans-serif", fontWeight: 700, fontSize: 22, lineHeight: 1, color: ink }}>1</div>{box({ left: 8, right: 8, top: 40, height: 5, borderRadius: 2, background: ink })}{box({ left: 8, right: 16, top: 50, height: 3, borderRadius: 2, background: soft })}{box({ left: 8, right: 22, top: 57, height: 3, borderRadius: 2, background: soft })}</>,
    quotes: <>{box({ left: 8, right: 8, top: 18, height: 7, borderRadius: 2, background: ink })}{box({ left: 8, right: 14, top: 29, height: 7, borderRadius: 2, background: ink })}{box({ left: 8, width: 22, top: 40, height: 7, borderRadius: 2, background: "#A855F7" })}</>,
    explainer: <>{box({ left: 8, right: 8, top: 9, height: 5, borderRadius: 2, background: ink })}{box({ left: 10, top: 24, width: 16, height: 16, borderRadius: 4, border: `2px solid ${ink}`, boxSizing: "border-box" })}{box({ left: 28, top: 31, width: 8, height: 2, background: ink })}{box({ left: 37, top: 24, width: 14, height: 14, borderRadius: "50%", background: "#C4B5FD" })}{box({ left: 8, right: 14, top: 52, height: 3, borderRadius: 2, background: soft })}</>,
    comparisons: <>{box({ left: 0, top: 0, bottom: 0, width: 29, background: "#E7E2DA" })}{box({ left: 5, width: 19, top: 28, height: 4, borderRadius: 2, background: "#8b8478" })}{box({ right: 5, width: 19, top: 28, height: 4, borderRadius: 2, background: ink })}{box({ left: 5, width: 14, top: 36, height: 3, borderRadius: 2, background: soft })}{box({ right: 5, width: 14, top: 36, height: 3, borderRadius: 2, background: "#7E22CE" })}</>,
    story: <>{box({ inset: 0, background: "linear-gradient(170deg,#e9d5c3 0 45%,#c9a98d 45%)" })}{box({ left: 19, top: 12, width: 20, height: 20, borderRadius: "50%", background: "#8a6a55" })}{box({ left: 11, top: 34, width: 36, height: 40, borderRadius: "18px 18px 0 0", background: "#8a6a55" })}{box({ left: 6, right: 6, bottom: 8, height: 9, borderRadius: 3, background: "#fff" })}</>,
    tutorial: <>{[10, 30, 50].map((t, i) => box({ left: 8, top: t, width: 14, height: 14, borderRadius: "50%", background: i ? "#E7E2DA" : ink }, "d" + i))}{[[15, 8, ink], [35, 12, soft], [55, 16, soft]].map(([t, r, c]: any, i) => box({ left: 26, right: r, top: t, height: 4, borderRadius: 2, background: c }, "l" + i))}</>,
  };
  return <>{parts[k] || null}</>;
}

// "Flowy decides": Flowy's own wordmark, the colour-cycling wave and the mono caps, as the rail's header wears it.
function MediaFlowyDecides() {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: "7px", fontFamily: "'Geist Mono', monospace", fontSize: "11.5px", fontWeight: 400, letterSpacing: "0.1em", textTransform: "uppercase", color: "#171717", whiteSpace: "nowrap" }}>
      <svg viewBox="0 0 31 8" fill="none" aria-hidden="true" style={{ width: "30px", height: "9px", flexShrink: 0, filter: "drop-shadow(0 0 4px rgba(168,85,247,.25))" }}>
        <defs>
          <linearGradient id="mediaWaveGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#EC4899"><animate attributeName="stop-color" values="#EC4899;#A855F7;#6366F1;#A855F7;#EC4899" dur="4s" repeatCount="indefinite" /></stop>
            <stop offset="50%" stopColor="#A855F7"><animate attributeName="stop-color" values="#A855F7;#6366F1;#EC4899;#A855F7" dur="4s" repeatCount="indefinite" /></stop>
            <stop offset="100%" stopColor="#6366F1"><animate attributeName="stop-color" values="#6366F1;#EC4899;#A855F7;#6366F1" dur="4s" repeatCount="indefinite" /></stop>
          </linearGradient>
        </defs>
        <path d="M2.45808 1.72226C1.74654 1.72226 0.769662 2.9375 0.750379 4.1529C0.728363 5.54055 1.66854 6.65884 2.885 6.74558C4.17988 6.83792 4.73596 5.46653 5.30425 4.1529C5.87254 2.83927 6.36311 0.75 7.15425 0.75C7.9454 0.75 9.48709 6.45133 12.2774 6.4215C14.017 6.4029 15.3507 5.03796 16.262 4.1529C17.1733 3.26784 18.2669 2.19642 19.9074 2.19642C21.5478 2.19642 22.9505 3.50473 24.0889 4.31494C25.2274 5.12515 26.2869 6.18013 27.6467 5.93537C28.2918 5.81924 29.0209 5.62496 29.75 4.1529" stroke="url(#mediaWaveGradient)" strokeWidth="1.8" strokeLinecap="round" fill="none" />
      </svg>
      Flowy decides
    </span>
  );
}

// ── Create Media's media picker (Karen, 2026-10-23) ─────────────────────────────
// The Creative Studio's attach sheet (creative-hub-v1.tsx attachSheetView), on a media card's footage: three
// equal tabs, My Uploads (the workspace's Uploads rows, newest first), Flowshift Media (the shared Flowshift Media
// Library) and Upload File (files from this device, staged so they can be looked at and named before anything
// leaves). Picking hands the files back to the card. Uploading goes the Studio's way: Softr's own upload, then a
// row in Uploads with its name, the file and its kind. Every media card has its own Content record now (Karen,
// 2026-10-23), so the row is made with Linked Content Record set to it and the File type the route asks for
// ("Raw Footage" for footage), as the Studio's attach does (creative-hub-v1.tsx attachFiles, uploadCreateFields).
// If the upload or the row is refused, the file stays on the card from this device, the way the card worked before.
const mediaLibrarySelect = q.select({
  mediaName: "Media Name",
  status: "Status",
  attachments: "Attachments",
  type: "Type",
  usedFor: "Used for content",
});
// The board's own upload map (uploadCreateFields): the name, the file, the record it belongs to and its kind.
const mediaUploadCreateFields = q.select({
  fileName: "File Name",
  file: "File",
  linkedContent: "Linked Content Record",
  fileType: "File type",
});
// The Studio's fallback: a refusal of the kind leaves the name and the file.
const mediaUploadBareFields = q.select({
  fileName: "File Name",
  file: "File",
});
const mediaAttOf = (v: any): any => (Array.isArray(v) ? v[0] : v) || null;
const mediaSelLabel = (v: any): string => String((v && typeof v === "object" ? (v.label ?? v.name) : v) ?? "");
const mediaKindOf = (mime: string, name: string): "Video" | "Image" | "Audio" | "Document" => fileTypeOf(name, mime) as any;
const mediaDateShort = (v: any): string => {
  const t = v ? new Date(v) : null;
  return t && !isNaN(t.getTime()) ? t.toLocaleDateString(undefined, { day: "numeric", month: "short" }) : "";
};
// Flowshift's wave, small, for the Flowshift Media tab (the Studio puts FlowyMark there).
function MediaWaveMark() {
  return (
    <svg viewBox="0 0 31 8" fill="none" aria-hidden="true" style={{ width: "22px", height: "7px", flexShrink: 0 }}>
      <defs>
        <linearGradient id="mediaPickWave" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="#EC4899" /><stop offset="50%" stopColor="#A855F7" /><stop offset="100%" stopColor="#6366F1" />
        </linearGradient>
      </defs>
      <path d="M2.45808 1.72226C1.74654 1.72226 0.769662 2.9375 0.750379 4.1529C0.728363 5.54055 1.66854 6.65884 2.885 6.74558C4.17988 6.83792 4.73596 5.46653 5.30425 4.1529C5.87254 2.83927 6.36311 0.75 7.15425 0.75C7.9454 0.75 9.48709 6.45133 12.2774 6.4215C14.017 6.4029 15.3507 5.03796 16.262 4.1529C17.1733 3.26784 18.2669 2.19642 19.9074 2.19642C21.5478 2.19642 22.9505 3.50473 24.0889 4.31494C25.2274 5.12515 26.2869 6.18013 27.6467 5.93537C28.2918 5.81924 29.0209 5.62496 29.75 4.1529" stroke="url(#mediaPickWave)" strokeWidth="1.8" strokeLinecap="round" fill="none" />
    </svg>
  );
}
// The Creative Studio's FlowyMark (creative-hub-v1.tsx ~4404) at the sizes its Write with Flowy pills use: the
// colour-cycling wave, each with its own gradient id.
let mediaMarkSeq = 0;
function MediaFlowyMark({ size = 14 }: { size?: number }) {
  const idRef = useRef("");
  if (!idRef.current) { mediaMarkSeq += 1; idRef.current = `mediaMark${mediaMarkSeq}`; }
  const h = Math.round((size * 14) / 34);
  return (
    <span aria-hidden="true" style={{ position: "relative", width: `${size}px`, height: `${h}px`, display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
      <svg viewBox="0 0 31 8" fill="none" style={{ width: `${Math.round(size * 0.88)}px`, height: `${Math.max(4, Math.round(h * 0.64))}px`, overflow: "visible" }}>
        <defs>
          <linearGradient id={idRef.current} x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#EC4899"><animate attributeName="stop-color" values="#EC4899;#A855F7;#6366F1;#A855F7;#EC4899" dur="5s" repeatCount="indefinite" /></stop>
            <stop offset="50%" stopColor="#A855F7"><animate attributeName="stop-color" values="#A855F7;#6366F1;#EC4899;#A855F7" dur="5s" repeatCount="indefinite" /></stop>
            <stop offset="100%" stopColor="#6366F1"><animate attributeName="stop-color" values="#6366F1;#EC4899;#A855F7;#6366F1" dur="5s" repeatCount="indefinite" /></stop>
          </linearGradient>
        </defs>
        <path d="M2.45808 1.72226C1.74654 1.72226 0.769662 2.9375 0.750379 4.1529C0.728363 5.54055 1.66854 6.65884 2.885 6.74558C4.17988 6.83792 4.73596 5.46653 5.30425 4.1529C5.87254 2.83927 6.36311 0.75 7.15425 0.75C7.9454 0.75 9.48709 6.45133 12.2774 6.4215C14.017 6.4029 15.3507 5.03796 16.262 4.1529C17.1733 3.26784 18.2669 2.19642 19.9074 2.19642C21.5478 2.19642 22.9505 3.50473 24.0889 4.31494C25.2274 5.12515 26.2869 6.18013 27.6467 5.93537C28.2918 5.81924 29.0209 5.62496 29.75 4.1529" stroke={`url(#${idRef.current})`} strokeWidth="1.8" strokeLinecap="round" fill="none" />
      </svg>
    </span>
  );
}
function MediaPickerSheet({ title, subtitle, only, onCard, dropped, isDesktop, onClose, onPick, recordId = "", fileTypeFor }: {
  title: string; subtitle: string; only: "video" | "any"; onCard: string[]; dropped?: File[];
  // The card's Content record and the File type an upload from here gets (null: by the file's own kind).
  recordId?: string; fileTypeFor?: (kind: "video" | "image") => string | null;
  isDesktop: boolean; onClose: () => void; onPick: (files: MediaFile[]) => void;
}) {
  // State first: every read below waits on it.
  const [tab, setTab] = useState<"library" | "media" | "device">(dropped && dropped.length ? "device" : "library");
  const [sel, setSel] = useState<string[]>([]);
  const [search, setSearch] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [filterOpen, setFilterOpen] = useState(false);
  const [libType, setLibType] = useState<string | null>(null);
  const [libUsed, setLibUsed] = useState<string | null>(null);
  const [libAge, setLibAge] = useState<string | null>(null);
  const [libBrand, setLibBrand] = useState<string | null>(null);
  const [staged, setStaged] = useState<{ id: string; file: File; url: string }[]>([]);
  const [stagedNames, setStagedNames] = useState<Record<string, string>>({});
  const [dropActive, setDropActive] = useState(false);
  const [busy, setBusy] = useState(0);
  const stagedRef = useRef<{ id: string; file: File; url: string }[]>([]);
  stagedRef.current = staged;
  const okKind = (k: string) => (only === "video" ? k === "Video" : k === "Video" || k === "Image");
  const stage = (list: File[]) => {
    const add = list.filter((f) => okKind(mediaKindOf(String(f.type || ""), f.name))).map((f) => {
      let url = "";
      try { url = URL.createObjectURL(f); } catch { url = ""; }
      return { id: Math.random().toString(36).slice(2, 10), file: f, url };
    });
    if (list.length && !add.length) toast(only === "video" ? "Only videos go here." : "Only photos and videos go here.");
    if (add.length) setStaged((s) => [...s, ...add]);
  };
  useEffect(() => { if (dropped && dropped.length) stage(dropped); }, []);
  // A staged file that never went out gives its preview back.
  useEffect(() => () => { stagedRef.current.forEach((s) => { try { if (s.url) URL.revokeObjectURL(s.url); } catch { /* noop */ } }); }, []);
  const unstage = (id: string) => setStaged((s) => s.filter((x) => { if (x.id === id) { try { URL.revokeObjectURL(x.url); } catch { /* noop */ } } return x.id !== id; }));

  // ── The reads, as the Studio does them: newest first, re-read on every open, a plain read behind the sorted one ──
  const libraryRead = useRecords({ from: ds.uploads, select: filesSelect, count: 200, sort: [{ fieldId: "Created date", direction: "desc" }] as any });
  const libraryFailed = !!(libraryRead as any)?.error;
  const libraryPlainRead = useRecords({ from: ds.uploads, select: filesSelect, count: 200, enabled: libraryFailed });
  const plainFailed = libraryFailed && !!(libraryPlainRead as any)?.error;
  const libraryRows: any[] = useMemo(() => {
    const src = libraryFailed ? (libraryPlainRead as any) : (libraryRead as any);
    return src?.data?.pages?.flatMap((pg: any) => pg.items) ?? [];
  }, [(libraryRead as any)?.data, (libraryPlainRead as any)?.data, libraryFailed]);
  const libraryLoading = !plainFailed && !(libraryFailed ? (libraryPlainRead as any)?.data : (libraryRead as any)?.data);
  const mediaReady = ds.flowshiftMedia !== MEDIA_LIBRARY_DS_UNSET;
  const mediaRead = useRecords({ from: ds.flowshiftMedia, select: mediaLibrarySelect, count: 200, enabled: tab === "media" && mediaReady });
  const mediaRows: any[] = useMemo(() => ((mediaRead as any)?.data?.pages?.flatMap((pg: any) => pg.items) ?? []), [(mediaRead as any)?.data]);
  const mediaFailed = !!(mediaRead as any)?.error;
  const mediaLoading = tab === "media" && mediaReady && !mediaFailed && !(mediaRead as any)?.data;
  const createUpload = useRecordCreate({ from: ds.uploads, fields: mediaUploadCreateFields });
  const createUploadBare = useRecordCreate({ from: ds.uploads, fields: mediaUploadBareFields });
  const { uploadAsync } = useUpload();
  useEffect(() => { try { (libraryRead as any)?.refetch?.(); } catch { /* noop */ } }, []);
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape" && !busy) onClose(); };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [busy]);

  const onLibrary = tab === "library";
  const onMedia = tab === "media";
  const picking = onLibrary || onMedia;
  const term = search.trim().toLowerCase();
  const rowName = (r: any) => String(r?.fields?.fileName || mediaAttOf(r?.fields?.file)?.filename || "File");
  const rowKind = (r: any) => {
    const att = mediaAttOf(r?.fields?.file);
    const ft = mediaSelLabel(r?.fields?.fileType);
    const k = mediaKindOf(String(att?.type || ""), rowName(r) + (att?.filename ? " " + att.filename : ""));
    return k !== "Document" ? k : /video|footage/i.test(ft) ? "Video" : /graphic|carousel|thumbnail|image/i.test(ft) ? "Image" : k;
  };
  const hasUses = !libraryFailed;
  const usesOf = (r: any) => Math.max(0, Number(r?.fields?.usedCount) || 0);
  const brandsOf = (r: any) => {
    const raw = r?.fields?.brand;
    const arr = Array.isArray(raw) ? raw : (raw ? [raw] : []);
    return arr.map((b: any) => String(b?.label ?? b?.name ?? b ?? "")).filter(Boolean);
  };
  const ageDays = (r: any) => {
    const t = r?.fields?.createdDate ? new Date(r.fields.createdDate).getTime() : 0;
    return t ? (Date.now() - t) / 86400000 : Infinity;
  };
  const onThis = new Set(onCard);
  // What this card can take at all, which is what the tab counts.
  const fits = libraryRows
    .filter((r: any) => !!mediaAttOf(r.fields?.file)?.url)
    .filter((r: any) => mediaSelLabel(r.fields?.status) !== "Deleted")
    .filter((r: any) => okKind(rowKind(r)));
  const pool = fits
    .filter((r: any) => !term || rowName(r).toLowerCase().includes(term))
    .filter((r: any) => !libType || rowKind(r) === libType)
    .filter((r: any) => {
      if (!libUsed || !hasUses) return true;
      const n = usesOf(r);
      return libUsed === "unused" ? n === 0 : libUsed === "once" ? n === 1 : n > 1;
    })
    .filter((r: any) => {
      if (!libAge) return true;
      const d = ageDays(r);
      return libAge === "7" ? d <= 7 : libAge === "30" ? d <= 30 : d > 30;
    })
    .filter((r: any) => !libBrand || brandsOf(r).includes(libBrand));
  const brandOptions = Array.from(new Set(libraryRows.flatMap((r: any) => brandsOf(r)))).sort();
  const activeFilters = [libType, libUsed, libAge, libBrand].filter(Boolean).length;
  const mediaAtt = (r: any) => (Array.isArray(r.fields?.attachments) ? r.fields.attachments[0] : null);
  const mediaKind = (r: any) => mediaKindOf(String(mediaAtt(r)?.type || ""), String(mediaAtt(r)?.filename || r.fields?.mediaName || ""));
  const mediaPool = mediaRows
    .filter((r: any) => mediaSelLabel(r.fields?.status) === "Done")
    .filter((r: any) => !!mediaAtt(r)?.url)
    .filter((r: any) => okKind(mediaKind(r)))
    .filter((r: any) => !term || String(r.fields?.mediaName || "").toLowerCase().includes(term))
    .filter((r: any) => !libType || mediaKind(r) === libType);

  const canAdd = !busy && (picking ? sel.length > 0 : staged.length > 0);
  const addLabel = picking ? (sel.length > 1 ? `Add ${sel.length} files` : "Add file") : (staged.length > 1 ? `Upload ${staged.length} files` : "Upload");
  const countText = busy ? `${busy === 1 ? "One file" : `${busy} files`} on the way…` : picking ? (sel.length ? `${sel.length} selected` : "") : (staged.length ? `${staged.length} ready` : "");
  const toggleSel = (id: string) => setSel((s) => (s.includes(id) ? s.filter((x) => x !== id) : s.concat([id])));
  const mono = (size: number, color: string, weight = 500): React.CSSProperties => ({ fontFamily: "'Geist Mono', monospace", fontSize: `${size}px`, fontWeight: weight, letterSpacing: "0.08em", textTransform: "uppercase", color });
  const INK = "#171717", INK_2 = "#525252", INK_3 = "#737373", INK_MUTED = "#A3A3A3", HAIR = "#E5E5E5", HAIR_SOFT = "#F0F0F0", WASH = "#F5EEFE", ACCENT = "#A855F7", ACCENT_DEEP = "#7E22CE";

  const tile = (o: { key: string; name: string; kind: string; url?: string; thumb?: string; selected: boolean; disabled?: boolean;
    facts: [string, string][]; onPick: () => void; onRemove?: () => void; rename?: { value: string; onChange: (v: string) => void } }) => (
    <div key={o.key} onClick={() => { if (!o.disabled) o.onPick(); }}
      style={{ minWidth: 0, padding: "6px", borderRadius: "11px", position: "relative", cursor: o.disabled ? "default" : "pointer",
        background: o.selected ? WASH : "#FAFAFA", border: `1px solid ${o.selected ? "rgba(168,85,247,0.30)" : HAIR_SOFT}`, transition: "background 0.15s ease, border-color 0.15s ease" }}>
      <div style={{ position: "relative", width: "100%", aspectRatio: "16 / 10", borderRadius: "9px", overflow: "hidden", background: "linear-gradient(135deg,#3F3F46,#71717A)",
        display: "flex", alignItems: "center", justifyContent: "center", opacity: o.disabled ? 0.45 : 1,
        boxShadow: o.selected ? `0 0 0 2px ${ACCENT}, 0 0 0 4px rgba(168,85,247,0.16)` : "0 0 0 1px rgba(23,23,23,0.06)", transition: "box-shadow 0.15s ease" }}>
        {o.thumb ? <img loading="lazy" decoding="async" src={o.thumb} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          : o.url && o.kind === "Image" ? <img loading="lazy" decoding="async" src={o.url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          : o.url && o.kind === "Video" ? <video src={`${o.url}#t=0.1`} preload="metadata" muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover", pointerEvents: "none" }} />
          : <FileText size={18} strokeWidth={1.6} color="rgba(255,255,255,0.9)" />}
        {!o.disabled && !o.onRemove && (
          <button type="button" title={o.selected ? "Deselect" : "Select"} aria-label={`${o.selected ? "Deselect" : "Select"} ${o.name}`}
            onClick={(e) => { e.stopPropagation(); o.onPick(); }}
            style={{ position: "absolute", left: "6px", top: "6px", zIndex: 2, width: "20px", height: "20px", borderRadius: "50%", padding: 0, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
              background: o.selected ? ACCENT : "rgba(10,10,14,0.45)", border: o.selected ? "none" : "1px solid rgba(255,255,255,0.6)" }}>
            <Check size={11} strokeWidth={3} color="white" style={{ opacity: o.selected ? 1 : 0.6 }} />
          </button>
        )}
        {o.onRemove && (
          <button type="button" title="Take it out" aria-label={`Take ${o.name} out`} onClick={(e) => { e.stopPropagation(); o.onRemove?.(); }}
            style={{ position: "absolute", right: "6px", top: "6px", zIndex: 2, width: "20px", height: "20px", borderRadius: "50%", padding: 0, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", background: "rgba(10,10,14,0.62)", border: "none" }}>
            <X size={11} strokeWidth={2.4} color="white" />
          </button>
        )}
      </div>
      <div style={{ fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 500, color: INK, marginTop: "6px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", opacity: o.disabled ? 0.55 : 1 }}>{o.name}</div>
      {o.rename && (
        <input value={o.rename.value} placeholder="Give it a name (optional)" aria-label={`Name for ${o.name}`} onClick={(e) => e.stopPropagation()} onChange={(e) => o.rename?.onChange(e.target.value)}
          style={{ width: "100%", boxSizing: "border-box", marginTop: "6px", height: "26px", padding: "0 7px", borderRadius: "7px", background: "white", border: `1px solid ${HAIR}`, outline: "none", fontFamily: "'Geist', sans-serif", fontSize: "11.5px", fontWeight: 450, color: INK }} />
      )}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1px 6px", marginTop: "5px", opacity: o.disabled ? 0.55 : 1 }}>
        {o.facts.map(([k, v]) => (
          <div key={k} style={{ minWidth: 0 }}>
            <span style={{ ...mono(9, "#B4B4B4"), display: "block" }}>{k}</span>
            <span style={{ display: "block", fontFamily: "'Geist', sans-serif", fontSize: "11px", fontWeight: 450, color: INK_2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{v}</span>
          </div>
        ))}
      </div>
    </div>
  );
  const libraryTiles = pool.map((r: any) => {
    const att = mediaAttOf(r.fields?.file);
    const id = String(r.id);
    const on = onThis.has(id);
    const uses = usesOf(r);
    return tile({
      key: id, name: rowName(r), kind: rowKind(r), url: att?.url || "", thumb: att?.thumbnails?.large?.url || att?.thumbnails?.small?.url || "",
      selected: sel.includes(id), disabled: on,
      facts: [["Kind", rowKind(r)], ["Size", formatFileSize(att?.size)], ["Added", mediaDateShort(r.fields?.createdDate) || "—"],
        ["Used", on ? "On this card" : !hasUses ? "—" : uses === 0 ? "Not yet" : uses === 1 ? "Once" : `${uses}×`]],
      onPick: () => toggleSel(id),
    });
  });
  const mediaTiles = mediaPool.map((r: any) => {
    const att = mediaAtt(r);
    const id = String(r.id);
    const uses = Array.isArray(r.fields?.usedFor) ? r.fields.usedFor.length : 0;
    return tile({
      key: id, name: String(r.fields?.mediaName || att?.filename || "Media"), kind: mediaKind(r), url: att?.url || "", thumb: att?.thumbnails?.large?.url || att?.thumbnails?.small?.url || "",
      selected: sel.includes(id), disabled: onThis.has(id),
      facts: [["Kind", mediaSelLabel(r.fields?.type) || mediaKind(r)], ["Size", formatFileSize(att?.size)], ["Added", "Flowshift"], ["Used", uses === 0 ? "Not yet" : uses === 1 ? "Once" : `${uses}×`]],
      onPick: () => toggleSel(id),
    });
  });
  const stagedTiles = staged.map((s) => {
    const kind = mediaKindOf(String(s.file.type || ""), s.file.name);
    return tile({
      key: s.id, name: s.file.name, kind, url: s.url, selected: true, facts: [["Kind", kind], ["Size", formatFileSize(s.file.size)]],
      onPick: () => {}, onRemove: () => unstage(s.id),
      rename: { value: stagedNames[s.id] || "", onChange: (v) => setStagedNames((m) => ({ ...m, [s.id]: v })) },
    });
  });
  const accept = only === "video" ? "video/*" : "image/*,video/*";
  const fileInput = (id: string) => (
    <input type="file" multiple id={id} style={{ display: "none" }} accept={accept}
      onChange={(e) => { const picked = Array.from((e.target?.files || []) as any) as File[]; (e.target as any).value = ""; stage(picked); }} />
  );
  const dropzone = (
    <label htmlFor="fs-media-drop"
      onDragOver={(e) => { e.preventDefault(); setDropActive(true); }} onDragLeave={() => setDropActive(false)}
      onDrop={(e) => { e.preventDefault(); setDropActive(false); stage(Array.from(e.dataTransfer?.files || []) as File[]); }}
      style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: "8px", minHeight: "230px", padding: "0 16px", textAlign: "center",
        borderRadius: "14px", border: `1.5px dashed ${dropActive ? ACCENT : "#DEDEE2"}`, background: dropActive ? WASH : "#FCFCFD", cursor: "pointer" }}>
      <Upload size={20} strokeWidth={1.8} color={dropActive ? ACCENT : INK_MUTED} />
      <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "13.5px", fontWeight: 500, color: INK }}>{isDesktop ? "Drop files here, or click to pick them" : "Tap to pick files"}</span>
      <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12px", color: INK_3 }}>Nothing uploads until you press {addLabel}.</span>
      {fileInput("fs-media-drop")}
    </label>
  );
  const addMoreRow = (
    <label htmlFor="fs-media-more" style={{ display: "inline-flex", alignSelf: "flex-start", alignItems: "center", gap: "6px", height: "30px", padding: "0 11px", marginTop: "12px", borderRadius: "8px",
      border: `1px solid ${HAIR}`, background: "white", color: INK, fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, cursor: "pointer" }}>
      <Plus size={13} strokeWidth={2} color={ACCENT} /> Add more
      {fileInput("fs-media-more")}
    </label>
  );
  const emptyNote = (text: string) => <div style={{ padding: "40px 0", textAlign: "center", fontFamily: "'Geist', sans-serif", fontSize: "13px", color: INK_3 }}>{text}</div>;
  const grid: React.CSSProperties = { display: "grid", gap: isDesktop ? "12px" : "10px", flexShrink: 0, gridTemplateColumns: `repeat(auto-fill, minmax(${isDesktop ? 150 : 140}px, 1fr))` };
  const noMatch = term ? "Nothing matches that search." : activeFilters || libType ? "Nothing matches those filters." : only === "video" ? "No videos here yet." : "No photos or videos here yet.";
  const body = onMedia
    ? (!mediaReady ? emptyNote("Connect the Flowshift Media Library table in Softr and this fills up.")
      : mediaFailed ? emptyNote("Couldn't reach the Flowshift media just now.")
      : mediaLoading ? emptyNote("Loading Flowshift media…")
      : mediaPool.length === 0 ? emptyNote(term || libType ? noMatch : "No Access to Flowshift Media")
      : <div style={grid}>{mediaTiles}</div>)
    : onLibrary
      ? (plainFailed ? emptyNote("Couldn't reach your uploads just now. Upload File still works.")
        : libraryLoading ? emptyNote("Loading your files…")
        : pool.length === 0 ? emptyNote(term || activeFilters ? noMatch : "Nothing here yet. Anything you upload will be waiting here next time.")
        : <div style={grid}>{libraryTiles}</div>)
      : (staged.length === 0 ? dropzone : <><div style={grid}>{stagedTiles}</div>{addMoreRow}</>);
  const fchip = (selected: boolean, onClick: () => void, text: string) => (
    <button key={text} type="button" aria-pressed={selected ? "true" : "false"} onClick={onClick}
      style={{ height: "26px", padding: "0 10px", borderRadius: "999px", cursor: "pointer", whiteSpace: "nowrap", background: selected ? WASH : "white", border: `1px solid ${selected ? "rgba(168,85,247,0.45)" : HAIR}`,
        color: selected ? ACCENT_DEEP : INK_2, fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 500 }}>{text}</button>
  );
  const fgroup = (label: string, chips: React.ReactNode) => (
    <div style={{ marginBottom: "10px" }}>
      <span style={{ ...mono(9.5, INK_MUTED, 600), display: "block", marginBottom: "6px" }}>{label}</span>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "6px" }}>{chips}</div>
    </div>
  );

  // ── Hand the files back ──
  const fromRow = (id: string): MediaFile | null => {
    const r = libraryRows.find((x: any) => String(x.id) === id);
    if (r) {
      const att = mediaAttOf(r.fields?.file);
      return { id: "u-" + id + "-" + Math.random().toString(36).slice(2, 6), uploadId: id, name: rowName(r), kind: rowKind(r) === "Video" ? "video" : "image", url: att?.url || "", thumb: att?.thumbnails?.large?.url || "" };
    }
    const m = mediaRows.find((x: any) => String(x.id) === id);
    if (m) {
      const att = mediaAtt(m);
      // Not an Uploads row: the card copies it into one on its record (creative-hub-v1.tsx attachFromMedia).
      const used = (Array.isArray(m.fields?.usedFor) ? m.fields.usedFor : []).map((l: any) => String(l?.id ?? l ?? "")).filter(Boolean);
      return { id: "f-" + id + "-" + Math.random().toString(36).slice(2, 6), mediaRowId: id, mediaUsedFor: used, filename: String(att?.filename || ""), name: String(m.fields?.mediaName || att?.filename || "Media"), kind: mediaKind(m) === "Video" ? "video" : "image", url: att?.url || "", thumb: att?.thumbnails?.large?.url || "" };
    }
    return null;
  };
  const uploadStaged = async () => {
    const list = staged.slice();
    setBusy(list.length);
    const out: MediaFile[] = [];
    let kept = 0;
    for (const s of list) {
      const want = (stagedNames[s.id] || "").trim();
      const ext = (s.file.name.match(/\.[^.]+$/) || [""])[0];
      const name = want ? (/\.[^.]+$/.test(want) ? want : want + ext) : s.file.name;
      const kind: "video" | "image" = mediaKindOf(String(s.file.type || ""), s.file.name) === "Video" ? "video" : "image";
      let r: any = null;
      try { const res = await uploadAsync([s.file]); r = (Array.isArray(res) ? res : [res]).find((x: any) => x?.status === "completed" && x?.url) || null; } catch { r = null; }
      let rowId: string | null = null;
      if (r) {
        const fields: any = { fileName: name, file: [{ url: r.url, filename: s.file.name }], fileType: (fileTypeFor && fileTypeFor(kind)) || fileTypeOf(s.file.name, s.file.type) };
        if (recordId) fields.linkedContent = [recordId];
        rowId = await createRecordAsync(createUpload, fields);
        if (!rowId) rowId = await createRecordAsync(createUploadBare, { fileName: name, file: fields.file });
      }
      if (r && rowId) {
        out.push({ id: "u-" + rowId, uploadId: rowId, name, kind, url: r.url });
        try { URL.revokeObjectURL(s.url); } catch { /* noop */ }
      } else {
        // Refused or offline: the card still gets the file, from this device, as it did before the picker.
        out.push({ id: Math.random().toString(36).slice(2, 10), name, kind, url: s.url });
        kept += 1;
      }
      setBusy((n) => Math.max(0, n - 1));
    }
    stagedRef.current = [];
    if (kept) toast(kept === list.length ? "Couldn't save to your uploads, so it's on this card from your device." : `${kept} of ${list.length} couldn't save to your uploads. They're on this card from your device.`);
    onPick(out);
  };
  const submit = () => {
    if (!canAdd) return;
    if (picking) { onPick(sel.map(fromRow).filter(Boolean) as MediaFile[]); return; }
    uploadStaged();
  };

  const tabs: { key: "library" | "media" | "device"; label: React.ReactNode }[] = [
    { key: "library", label: (
      <span style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}>
        My Uploads
        <span style={{ fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 600, padding: "1px 5px", borderRadius: "5px", background: tab === "library" ? WASH : "rgba(168,85,247,0.10)", color: ACCENT_DEEP }}>
          {libraryLoading ? "…" : plainFailed ? "—" : fits.length}
        </span>
      </span>
    ) },
    { key: "media", label: <span style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}>{isDesktop && <MediaWaveMark />}Flowshift Media</span> },
    { key: "device", label: "Upload File" },
  ];
  const segmented = (
    <div role="tablist" aria-label="Where the files come from" style={{ display: "flex", gap: "4px", padding: "4px", borderRadius: "12px", background: SEGMENT_TRACK, width: isDesktop ? "448px" : "100%", boxSizing: "border-box", flexShrink: 0 }}>
      {tabs.map((t) => (
        <button key={t.key} type="button" role="tab" aria-selected={tab === t.key ? "true" : "false"}
          onClick={() => { setTab(t.key); setSel([]); if (t.key === "device") { setSearchOpen(false); setSearch(""); setFilterOpen(false); } }}
          style={{ flex: "1 1 0", minWidth: 0, height: "28px", padding: isDesktop ? "0 12px" : "0 4px", borderRadius: "8px", border: "none", cursor: "pointer", whiteSpace: "nowrap", overflow: "hidden",
            display: "inline-flex", alignItems: "center", justifyContent: "center",
            background: tab === t.key ? "white" : "transparent", boxShadow: tab === t.key ? "0 1px 2px rgba(23,23,23,0.08)" : "none",
            color: tab === t.key ? INK : INK_2, fontFamily: "'Geist', sans-serif", fontSize: isDesktop ? "13px" : "12.5px", fontWeight: 500 }}>
          {t.label}
        </button>
      ))}
    </div>
  );
  const searchBox = picking && (searchOpen ? (
    <div style={{ flex: isDesktop ? "0 1 260px" : "1 1 auto", minWidth: 0, display: "flex", alignItems: "center", gap: "7px", height: "30px", boxSizing: "border-box", padding: "0 9px", borderRadius: "8px", background: "#F7F7F8", border: `1px solid ${HAIR}` }}>
      <Search size={13} strokeWidth={1.9} color={INK_MUTED} style={{ flexShrink: 0 }} />
      <input autoFocus value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search your library" aria-label="Search your library"
        style={{ flex: 1, minWidth: 0, border: "none", outline: "none", background: "transparent", fontFamily: "'Geist', sans-serif", fontSize: isDesktop ? "13px" : "16px", color: INK }} />
      <button type="button" title="Close the search" aria-label="Close the search" onClick={() => { setSearch(""); setSearchOpen(false); }}
        style={{ background: "none", border: "none", cursor: "pointer", display: "flex", padding: 0, color: INK_MUTED }}><X size={13} /></button>
    </div>
  ) : (
    <button type="button" title="Search your library" aria-label="Search your library" onClick={() => setSearchOpen(true)}
      style={{ width: "30px", height: "30px", flexShrink: 0, boxSizing: "border-box", borderRadius: "8px", border: `1px solid ${HAIR}`, background: "white", color: "#525252", cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0 }}>
      <Search size={14} strokeWidth={1.9} />
    </button>
  ));
  const filterBox = picking && (
    <div style={{ position: "relative", flexShrink: 0 }}>
      <button type="button" title="Narrow the list" aria-label="Narrow the list" aria-expanded={filterOpen ? "true" : "false"} onClick={() => setFilterOpen((v) => !v)}
        style={{ display: "inline-flex", alignItems: "center", gap: "6px", height: "30px", padding: activeFilters ? "0 9px" : 0, width: activeFilters ? undefined : "30px", justifyContent: "center", boxSizing: "border-box", borderRadius: "8px",
          border: `1px solid ${activeFilters ? "rgba(168,85,247,0.45)" : HAIR}`, background: activeFilters ? WASH : "white", color: activeFilters ? ACCENT_DEEP : "#525252", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500 }}>
        <Filter size={14} strokeWidth={1.9} />{activeFilters > 0 && activeFilters}
      </button>
      {filterOpen && (
        <div style={{ position: "absolute", right: 0, top: "36px", zIndex: 4, width: "268px", maxWidth: "calc(100vw - 32px)", maxHeight: "320px", overflowY: "auto", padding: "12px", boxSizing: "border-box", borderRadius: "12px", background: "white", border: `1px solid ${HAIR}`, boxShadow: "0 12px 28px -16px rgba(30,32,40,.28)" }}>
          {only !== "video" && fgroup("Kind", ["Video", "Image"].map((t) => fchip(libType === t, () => setLibType(libType === t ? null : t), t)))}
          {onLibrary && hasUses && fgroup("Times Used", [["unused", "Not yet"], ["once", "Once"], ["many", "More than once"]].map(([v, t]) => fchip(libUsed === v, () => setLibUsed(libUsed === v ? null : v), t)))}
          {onLibrary && fgroup("Added", [["7", "Last 7 days"], ["30", "Last 30 days"], ["old", "Older"]].map(([v, t]) => fchip(libAge === v, () => setLibAge(libAge === v ? null : v), t)))}
          {onLibrary && brandOptions.length > 1 && fgroup("Brand", brandOptions.map((b) => fchip(libBrand === b, () => setLibBrand(libBrand === b ? null : b), b)))}
          <button type="button" onClick={() => { setLibType(null); setLibUsed(null); setLibAge(null); setLibBrand(null); }} disabled={!activeFilters}
            style={{ marginTop: "2px", padding: 0, background: "none", border: "none", cursor: activeFilters ? "pointer" : "default", fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 500, color: activeFilters ? ACCENT : INK_MUTED }}>Clear All</button>
        </div>
      )}
    </div>
  );
  const btn: React.CSSProperties = { flexShrink: 0, height: "32px", minWidth: isDesktop ? "124px" : "96px", padding: "0 14px", borderRadius: "8px", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "6px" };
  return createPortal(
    <div role="dialog" aria-modal="true" aria-label={title}
      style={{ position: "fixed", inset: 0, zIndex: 10050, display: "flex", alignItems: isDesktop ? "center" : "stretch", justifyContent: "center", padding: isDesktop ? "32px" : 0, background: "rgba(23,23,23,0.32)" }}
      onMouseDown={(e) => { if (e.target === e.currentTarget && !busy) onClose(); }}>
      <div style={{ width: isDesktop ? "920px" : "100%", maxWidth: "100%", height: isDesktop ? "640px" : "100%", maxHeight: "100%", display: "flex", flexDirection: "column", boxSizing: "border-box",
        background: "white", borderRadius: isDesktop ? "16px" : 0, boxShadow: "0 24px 64px -24px rgba(30,32,40,0.4)", overflow: "hidden" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "10px", padding: isDesktop ? "12px 16px 12px 20px" : "calc(10px + env(safe-area-inset-top)) 10px 10px 16px", borderBottom: `1px solid ${HAIR_SOFT}`, flexShrink: 0 }}>
          <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "15px", fontWeight: 600, letterSpacing: "-0.01em", color: INK, whiteSpace: "nowrap" }}>{title}</span>
          <span style={{ ...mono(10.5, INK_MUTED), flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{subtitle}</span>
          <button type="button" title="Close" aria-label="Close" onClick={() => { if (!busy) onClose(); }}
            style={{ width: "28px", height: "28px", flexShrink: 0, borderRadius: "8px", border: "none", background: "transparent", color: "#525252", cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0 }}>
            <X size={15} />
          </button>
        </div>
        {isDesktop ? (
          <div style={{ display: "flex", alignItems: "center", gap: "8px", padding: "12px 20px 10px", flexShrink: 0 }}>
            {segmented}<span style={{ flex: 1 }} />{searchBox}{filterBox}
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "8px", padding: "10px 16px 8px", flexShrink: 0 }}>
            {segmented}
            {picking && <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "8px" }}>{searchBox}{filterBox}</div>}
          </div>
        )}
        <div style={{ flex: 1, minHeight: 0, overflowY: "auto", overflowX: "hidden", padding: isDesktop ? "2px 20px 18px" : "2px 16px 16px", display: "flex", flexDirection: "column" }}>{body}</div>
        <div style={{ display: "flex", alignItems: "center", gap: "8px", padding: isDesktop ? "8px 20px" : "8px 16px calc(8px + env(safe-area-inset-bottom))", borderTop: `1px solid ${HAIR_SOFT}`, background: "#FAFAFA", flexShrink: 0 }}>
          <span style={{ ...mono(11, canAdd || busy ? ACCENT_DEEP : INK_MUTED, 600), flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{countText}</span>
          <button type="button" onClick={() => { if (!busy) onClose(); }} style={{ ...btn, border: `1px solid ${HAIR}`, background: "white", color: INK_2, cursor: busy ? "default" : "pointer" }}>Cancel</button>
          <button type="button" disabled={!canAdd} onClick={submit}
            style={{ ...btn, border: "none", background: CTA_FILL, boxShadow: SHADOW_CTA, color: "white", cursor: canAdd ? "pointer" : "not-allowed", opacity: canAdd || busy ? 1 : 0.4 }}>
            {busy ? "Uploading…" : addLabel}
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

// Create Media's writes, each on its own map so a refusal costs only that write (the rail's rule). Every name
// here is already written by a working map in this block (railCreateFields, modalUpdateFields, pieceWriteFields,
// contentUploadFields, scriptFileCreateFields), except "Flowy edit order", which only the Creative Studio
// writes so far (creative-hub-v1.tsx contentFlowyFields).
const mediaRecordCreateFields = q.select({
  stage: "Real Consolidated Status",
  status: "Status",
  postProductionStatus: "Post-production status",
  contentType: "Content Type",
  deliveryStyle: "Delivery Style",
  visibility: "Visibility",
  source: "Source",
  recordType: "Record type",
  version: "Version",
  brand: "Brand",
  customPostName: "Custom post name",
});
// The same create without the stage fields, for a connection that refuses one of them.
const mediaRecordBareFields = q.select({
  contentType: "Content Type",
  visibility: "Visibility",
  brand: "Brand",
  customPostName: "Custom post name",
});
const mediaRecordUpdateFields = q.select({
  stage: "Real Consolidated Status",
  status: "Status",
  postProductionStatus: "Post-production status",
  deliveryStyle: "Delivery Style",
  visibility: "Visibility",
  discardedDate: "Discarded date",
});
const mediaOrderFields = q.select({ flowyOrder: "Flowy edit order" });
const mediaUploadsLinkFields = q.select({ uploads: "Uploads" });
const mediaPairBareFields = q.select({ content: "Content", upload: "Upload", usedAs: "Used as" });
const mediaPairDetachFields = q.select({ content: "Content" });
const mediaUsedFields = q.select({ usedFor: "Used for content" });

function CreateMediaRoute({
  state, setState, isDesktop, membersReady, needsWsPick, workspaces, onPickWs, onUnpickWs,
  brands, brandsStatus, onStartOver, startOverRef,
}: {
  state: MediaRouteState;
  setState: (fn: (s: MediaRouteState) => MediaRouteState) => void;
  isDesktop: boolean;
  membersReady: boolean; needsWsPick: boolean; workspaces: { id: string; name: string }[];
  onPickWs: (id: string) => void; onUnpickWs: () => void;
  brands: Brand[]; brandsStatus: "loading" | "ready" | "error";
  onStartOver: () => void;
  // Flowy block: the + runs this route's own Start Over through here.
  startOverRef?: { current: (() => void) | null };
}) {
  // ── One Content record per card (Karen, 2026-10-23): what is written, when, and where it was copied from ──
  // Every record is made when the count is confirmed, before the cards show, so footage, words and choices
  // always have a home. Status options are only ones Airtable already has: nothing new is ever written.
  //
  //  1. Count confirmed: one create per card on ds.content (mediaRecordCreateFields).
  //       visibility "Hidden"      kept off the board while the card is filled (the rail's drafts, draftFields
  //                                in this file; the Studio's snapshots, creative-hub-v1.tsx line ~8438).
  //       Video:   stage "Attach Raw", status "Post Production", postProductionStatus "New Shots"
  //       Static:  stage "To Design",  status "Post Production", postProductionStatus "To Design"
  //                                (the Studio's new card placed in a column, canvasStage, creative-hub-v1.tsx
  //                                line ~18030, with ppValueFor line ~4224).
  //       contentType "Video" or "Graphic", deliveryStyle "Carousel" for a static card (the rail's draftFields).
  //       source "Manual-Original", recordType "Original script", version "Active" (the Studio's blank card,
  //                                onCanvasCreated, creative-hub-v1.tsx line ~20647).
  //       brand [the brand], customPostName "Create Media · Video 1" (what tells these apart: Source has no
  //                                Create Media option, and none is made from code).
  //  2. Footage and photos (the Studio's attach, creative-hub-v1.tsx attachFiles ~7151, library attach ~7418,
  //     attachFromMedia ~7480):
  //       Upload File: Uploads row with Linked Content Record [record] and File type "Raw Footage" for footage
  //                    (Karen, 2026-10-23), the file's own kind ("Image") for a static card's photos.
  //       My Uploads:  the existing Uploads row as it is.
  //       Flowshift Media: copied into a new Uploads row as above, and the record added to the media row's
  //                    "Used for content".
  //       Then each gets a Script Files row (label, content, upload, usedAs "Raw footage" for a video and
  //       "Reference files" for a static card, status "Unused"), and the record's "Uploads" list is rewritten
  //       in full. Taking a file off unlinks its Script Files row (content []), never deletes the upload.
  //  3. Edit Type: "Flowy edit order" = {"style": "loop" | "talking" | "voiceover"} (the Studio's startEdit,
  //     creative-hub-v1.tsx ~12850, the key its EDIT_STYLES use).
  //     Design Style: "Flowy edit order" = {"designLook": "<look key>"} (startDesign, ~12775, FLOWY_LOOKS keys).
  //     Format: deliveryStyle "Carousel" or "Still Graphic" (the rail's draftFields).
  //     Slide words: the piece fields (Cover Title, Slide 1 Title, Closing CTA...) through pieceWriteFields, the
  //     same map as the rail's railPieceUpdate, saved a moment after typing stops.
  //  4. Edit N now / Design N now: no edit or design call (MEDIA_RESULTS_LIVE is false), and ON HOLD the records stay
//     Hidden where they are (Karen 2026-10-23). Once live, each record is put
  //     where the Studio's Edit and Design buttons start from: visibility "Active" (the rail's Add, this file),
  //     video stage "To Edit" with postProductionStatus "Creatives Queue" (ppValueFor), static stays "To Design".
  //     The order is rewritten whole: video {"style"}, static {"design": true, "designLook"}. The future call
  //     adds "sentAt" to the order and moves the stage to "In Progress" (postProductionStatus "In Progress"),
  //     as the Studio's onStatus("In Progress") does once the job is taken.
  //  5. Start Over: every record not yet handed over gets visibility "Deleted" and discardedDate now (the
  //     board's discard in this file, never a hard delete). A record that lands after Start Over goes the same way.
  const mediaCreate = useRecordCreate({ from: ds.content, fields: mediaRecordCreateFields });
  const mediaCreateBare = useRecordCreate({ from: ds.content, fields: mediaRecordBareFields });
  const mediaUpdate = useRecordUpdate({ from: ds.content, fields: mediaRecordUpdateFields });
  const mediaOrder = useRecordUpdate({ from: ds.content, fields: mediaOrderFields });
  const mediaPieces = useRecordUpdate({ from: ds.content, fields: pieceWriteFields });
  const mediaUploadsLink = useRecordUpdate({ from: ds.content, fields: mediaUploadsLinkFields });
  const mediaPairCreate = useRecordCreate({ from: ds.scriptFiles, fields: scriptFileCreateFields });
  const mediaPairBare = useRecordCreate({ from: ds.scriptFiles, fields: mediaPairBareFields });
  const mediaPairDetach = useRecordUpdate({ from: ds.scriptFiles, fields: mediaPairDetachFields });
  const mediaUploadCopy = useRecordCreate({ from: ds.uploads, fields: mediaUploadCreateFields });
  const mediaUploadCopyBare = useRecordCreate({ from: ds.uploads, fields: mediaUploadBareFields });
  const mediaUsed = useRecordUpdate({ from: ds.flowshiftMedia, fields: mediaUsedFields });
  // Start Over while the records are still being made: what lands after it is discarded.
  const createRunRef = useRef(0);
  // Slide words wait a moment after typing stops, then go in one write per card.
  const pieceQueueRef = useRef<Record<string, { recordId: string; fields: Record<string, string>; timer: any }>>({});
  // The cards as they are now, for the writes that finish after a render.
  const cardsRef = useRef<MediaCard[]>([]);
  cardsRef.current = state.cards;
  // Write with Flowy on a card's slides: which slide's box is open ("all" for every slide), what was typed in it,
  // and which slides Flowy is writing now.
  const [ask, setAsk] = useState<{ card: string; target: string } | null>(null);
  const [askText, setAskText] = useState("");
  const [writing, setWriting] = useState<{ card: string; groups: string[] } | null>(null);
  // The slide being worked on, the only one that shows its tools (the Studio's copyActive).
  const [activeSlide, setActiveSlide] = useState<{ card: string; g: string } | null>(null);
  // The Ready to Schedule list open on one card's result.
  const [menuFor, setMenuFor] = useState<string | null>(null);
  const menuWrapRef = useRef<any>(null);
  // The Creative Studio's media picker, open on one card's footage (Karen, 2026-10-23). `files` are dropped files,
  // which land on its Upload File tab ready to go.
  const [picker, setPicker] = useState<{ cardId: string; which: "clips" | "photos"; files?: File[] } | null>(null);
  const S = state;
  const noun = (n: number) => (S.kind === "video" ? (n === 1 ? "video" : "videos") : (n === 1 ? "design" : "designs"));
  const itemName = (i: number) => `${S.kind === "video" ? "Video" : "Design"} ${i + 1}`;
  const showResults = mediaResultsOn();
  const say = (lines: MediaLine[]) => setState((s) => ({ ...s, after: [...s.after, ...lines] }));
  const patchCard = (id: string, patch: Partial<MediaCard> | ((c: MediaCard) => Partial<MediaCard>)) =>
    setState((s) => ({ ...s, cards: s.cards.map((c) => (c.id === id ? { ...c, ...(typeof patch === "function" ? patch(c) : patch) } : c)) }));
  // An answered question moves into the log with the answer under it, and the next question takes its place.
  const answer = (text: string, next: Partial<MediaRouteState>) => setState((s) => ({
    ...s, ...next,
    log: [...s.log, { from: "flowy", text: s.ask, at: 0, step: s.step }, { from: "user", text, at: Date.now() }],
  }));
  const brandsReady = membersReady && !needsWsPick && brandsStatus === "ready";
  // The first question once Create Media is tapped: the workspace for people in two or more, else the brand.
  useEffect(() => {
    if (S.ask || !membersReady) return;
    setState((s) => (s.ask ? s : needsWsPick
      ? { ...s, step: "ws", ask: "Let's make some media. Which workspace are we in today?" }
      : { ...s, step: "brand", ask: "Let's make some media. Which brand is it for?" }));
  }, [S.ask, needsWsPick, membersReady]);
  // One brand: no question, it is that brand (as the scripts route does).
  useEffect(() => {
    if (S.step !== "brand" || !brandsReady || brands.length !== 1) return;
    const b = brands[0];
    setState((s) => (s.step !== "brand" ? s : {
      ...s, step: "kind", brandId: b.id, brandName: b.name,
      ask: `${s.ask.startsWith("Let's") ? "Let's make some media for " : "This is for "}${b.name}. Videos to edit, or static designs?`,
    }));
  }, [S.step, brandsReady, brands.length]);
  // The working list in the results preview: one line per item, each done in turn.
  useEffect(() => {
    const w = S.working;
    if (!w) return;
    const t = setTimeout(() => setState((s) => {
      const ww = s.working;
      if (!ww) return s;
      const id = ww.ids[ww.idx];
      const cards = s.cards.map((c) => (c.id === id ? { ...c, open: false, redo: false, redoNote: "", result: { version: (c.result?.version || 0) + 1, queued: "" as const } } : c));
      if (ww.idx + 1 < ww.ids.length) return { ...s, cards, working: { ...ww, idx: ww.idx + 1, startedAt: Date.now() } };
      const firstRound = ww.ids.length === s.cards.length && cards.every((c) => c.result?.version === 1);
      const n = ww.ids.length;
      const line = firstRound
        ? `${n === 1 ? "It's ready, on its card." : `${n === 2 ? "Both are" : `All ${n} are`} ready, each on its own card.`} Re-do anything you want changed, or send it to schedule.`
        : n === 1 ? "The new version is on its card." : "The new versions are on their cards.";
      return { ...s, cards, working: null, after: [...s.after, { from: "flowy", text: line, at: Date.now() }] };
    }), 1400);
    return () => clearTimeout(t);
  }, [S.working?.idx, S.working?.ids.join(",")]);
  // The Ready to Schedule list closes on a tap anywhere else, the way the Add list does.
  useEffect(() => {
    if (!menuFor) return;
    const off = (e: any) => {
      const w = menuWrapRef.current;
      const path = typeof e.composedPath === "function" ? e.composedPath() : [];
      if (w && (path.includes(w) || w.contains(e.target))) return;
      setMenuFor(null);
    };
    const onKey = (e: any) => { if (e.key === "Escape") setMenuFor(null); };
    document.addEventListener("mousedown", off);
    document.addEventListener("touchstart", off);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", off); document.removeEventListener("touchstart", off); document.removeEventListener("keydown", onKey); };
  }, [menuFor]);

  // Go back undoes the last answer. From the first question it leaves the route.
  const goBack = () => {
    // Records still being made for this count are discarded when they land.
    if (S.creating) { createRunRef.current += 1; setState((s) => ({ ...s, creating: false })); }
    const at = (() => { for (let i = S.log.length - 1; i >= 0; i--) if (S.log[i].from === "flowy" && S.log[i].step) return i; return -1; })();
    if (at < 0) { onStartOver(); return; }
    const prev = S.log[at];
    if (prev.step === "ws") onUnpickWs();
    setState((s) => ({ ...s, step: prev.step as MediaRouteState["step"], ask: prev.text, log: s.log.slice(0, at) }));
  };
  // ── The record writes (see the map at the top) ──
  const warn = (what: string) => (e: any) => console.warn(`[Rail] Create Media: ${what} did not save.`, e);
  const recUpdate = (recordId: string, fields: Record<string, any>, what: string) => {
    if (recordId) mediaUpdate.mutate({ recordId, fields }, { onError: warn(what) });
  };
  const discardRecord = (recordId: string) => recUpdate(recordId, { visibility: "Deleted", discardedDate: new Date().toISOString() }, "the discard");
  const orderOf = (c: MediaCard, handing = false): Record<string, any> => (S.kind === "video"
    ? (c.editType ? { style: c.editType } : {})
    : { ...(handing ? { design: true } : {}), ...(c.look ? { designLook: c.look } : {}) });
  const writeOrder = (c: MediaCard, handing = false) => {
    if (c.recordId) mediaOrder.mutate({ recordId: c.recordId, fields: { flowyOrder: JSON.stringify(orderOf(c, handing)) } }, { onError: warn("the Flowy edit order") });
  };
  const flushPieces = (cardId: string) => {
    const q0 = pieceQueueRef.current[cardId];
    if (!q0) return;
    clearTimeout(q0.timer);
    delete pieceQueueRef.current[cardId];
    if (q0.recordId && Object.keys(q0.fields).length) mediaPieces.mutate({ recordId: q0.recordId, fields: q0.fields }, { onError: warn("the slide words") });
  };
  const queuePieces = (c: MediaCard, fields: Record<string, string>) => {
    if (!c.recordId) return;
    const prev = pieceQueueRef.current[c.id];
    if (prev) clearTimeout(prev.timer);
    const next = { recordId: c.recordId, fields: { ...(prev ? prev.fields : {}), ...fields }, timer: null as any };
    next.timer = setTimeout(() => flushPieces(c.id), 700);
    pieceQueueRef.current[c.id] = next;
  };
  // Words still waiting go out if the route closes.
  useEffect(() => () => { Object.keys(pieceQueueRef.current).forEach(flushPieces); }, []);
  // The record's whole file list, written afresh (it replaces the list).
  const linkUploadsOf = (recordId: string, files: MediaFile[]) => {
    if (!recordId) return;
    const ids = Array.from(new Set(files.map((f) => f.uploadId || "").filter(Boolean)));
    mediaUploadsLink.mutate({ recordId, fields: { uploads: ids } }, { onError: warn("the record's file list") });
  };
  // Files the picker handed back, put on the card's record the Studio's way.
  const attachToRecord = async (cardId: string, which: "clips" | "photos", got: MediaFile[]) => {
    const c0 = cardsRef.current.find((c) => c.id === cardId);
    const recordId = c0 ? c0.recordId : "";
    if (!recordId) return;
    const usedAs = which === "clips" ? "Raw footage" : "Reference files";
    const out: Record<string, Partial<MediaFile>> = {};
    for (const f of got) {
      let uploadId = f.uploadId || "";
      if (!uploadId && f.mediaRowId && f.url) {
        const fields = { fileName: f.name, file: [{ url: f.url, filename: f.filename || f.name }], fileType: which === "clips" ? "Raw Footage" : (f.kind === "video" ? "Video" : "Image"), linkedContent: [recordId] };
        uploadId = (await createRecordAsync(mediaUploadCopy, fields)) || (await createRecordAsync(mediaUploadCopyBare, { fileName: f.name, file: fields.file })) || "";
        if (!uploadId) { console.warn("[Rail] Create Media: the Flowshift Media file could not be copied into Uploads."); continue; }
        const already = f.mediaUsedFor || [];
        if (!already.includes(recordId)) mediaUsed.mutate({ recordId: f.mediaRowId, fields: { usedFor: Array.from(new Set([...already, recordId])) } }, { onError: warn("the media row's used-for list") });
      }
      if (!uploadId) continue;
      const pairId = (await createRecordAsync(mediaPairCreate, { label: `${usedAs} · ${f.name}`, content: [recordId], upload: [uploadId], usedAs, status: "Unused" }))
        || (await createRecordAsync(mediaPairBare, { content: [recordId], upload: [uploadId], usedAs })) || "";
      if (!pairId) console.warn("[Rail] Create Media: the file is saved but could not be attached to the card's record.");
      out[f.id] = { uploadId, pairId };
    }
    setState((s) => ({ ...s, cards: s.cards.map((c) => (c.id !== cardId ? c
      : { ...c, [which]: c[which].map((f) => (out[f.id] ? { ...f, ...out[f.id] } : f)) } as MediaCard)) }));
    // Once the card has re-rendered, so the list has every file on it.
    setTimeout(() => {
      const c = cardsRef.current.find((x) => x.id === cardId);
      if (c) linkUploadsOf(recordId, [...c.clips, ...c.photos]);
    }, 60);
  };
  const detachFromRecord = (c: MediaCard, f: MediaFile) => {
    if (!c.recordId) return;
    if (f.pairId) mediaPairDetach.mutate({ recordId: f.pairId, fields: { content: [] } }, { onError: warn("taking the file off") });
    linkUploadsOf(c.recordId, [...c.clips, ...c.photos].filter((x) => x.id !== f.id));
  };
  // Start Over: every record not handed over goes to the trash, then the route closes.
  const startOver = () => {
    createRunRef.current += 1;
    Object.keys(pieceQueueRef.current).forEach((k) => { clearTimeout(pieceQueueRef.current[k].timer); delete pieceQueueRef.current[k]; });
    for (const c of S.cards) if (c.recordId && !c.handed) discardRecord(c.recordId);
    onStartOver();
  };
  if (startOverRef) startOverRef.current = startOver;
  // One record per card, before the cards show. A create that never answers lets the card go on without one,
  // and if it lands later it is discarded (the rail's createDraft).
  const makeRecord = (fields: any): Promise<string | null> => {
    const p = createRecordAsync(mediaCreate, fields).then((id) => id || createRecordAsync(mediaCreateBare, {
      contentType: fields.contentType, visibility: fields.visibility, brand: fields.brand, customPostName: fields.customPostName,
    }));
    return withTimeout(p, 30000, null).then((id) => {
      if (!id) p.then((late) => { if (late) discardRecord(late); });
      return id;
    });
  };
  const startCards = async () => {
    if (S.creating) return;
    const n = S.count;
    const vid = S.kind === "video";
    const run = ++createRunRef.current;
    setState((s) => ({ ...s, creating: true }));
    const ids = await Promise.all(Array.from({ length: n }, (_, i) => makeRecord({
      ...(vid
        ? { stage: "Attach Raw", status: "Post Production", postProductionStatus: "New Shots", contentType: "Video" }
        : { stage: "To Design", status: "Post Production", postProductionStatus: "To Design", contentType: "Graphic", deliveryStyle: "Carousel" }),
      visibility: "Hidden", source: "Manual-Original", recordType: "Original script", version: "Active",
      ...(S.brandId ? { brand: [S.brandId] } : {}),
      customPostName: `Create Media · ${vid ? "Video" : "Design"} ${i + 1}`,
    })));
    // Started over while they were being made.
    if (run !== createRunRef.current) { ids.forEach((id) => { if (id) discardRecord(id); }); return; }
    const missed = ids.filter((id) => !id).length;
    if (missed) {
      console.warn(`[Rail] Create Media: ${missed} of ${n} card records could not be made. Those cards are not saved.`);
      toast(missed === n ? "Your cards couldn't be saved yet. You can still fill them in." : `${missed} of ${n} cards couldn't be saved yet. You can still fill them in.`);
    }
    setState((s) => ({ ...s, creating: false }));
    answer(`${n} ${noun(n)}`, {
      step: "cards",
      cards: Array.from({ length: n }, (_, i) => newMediaCard(i, ids[i] || "")),
      after: [{ from: "flowy", at: Date.now(), text: (n === 1 ? "Here's your card. Open it, " : `Here's a card for each ${S.kind === "video" ? "video" : "design"}. Open each one, `) + (S.kind === "video"
        ? "add your footage and pick an edit type. I'll decide the rest."
        : `pick a format and a style, add the slide words and tick that ${n === 1 ? "it's" : "they're"} ready. I'll decide the rest.`) }],
    });
  };
  const allReady = S.cards.length > 0 && S.cards.every((c) => !mediaMissing(S.kind, c).length);
  const readyCount = S.cards.filter((c) => !mediaMissing(S.kind, c).length).length;
  const goLabel = `${S.kind === "video" ? "Edit" : "Design"} ${S.cards.length} now`;
  const go = () => {
    if (!allReady || S.working) return;
    const user: MediaLine = { from: "user", text: goLabel, at: Date.now() };
    // Each record goes where the Studio's Edit and Design start from (the map at the top): on the board, in
    // To Edit or To Design, with the whole order. Nothing is sent to Flowy yet.
    for (const c of S.cards) {
      flushPieces(c.id);
      if (!c.recordId || c.handed) continue;
      // On hold (Karen 2026-10-23): until editing and designing are connected the records stay Hidden where they
      // are, so nothing lands on the board or in the editors' queue. Only the order and the words are saved.
      if (!MEDIA_RESULTS_LIVE) { writeOrder(c, true); continue; }
      recUpdate(c.recordId, S.kind === "video"
        ? { visibility: "Active", stage: "To Edit", status: "Post Production", postProductionStatus: "Creatives Queue" }
        : { visibility: "Active", stage: "To Design", status: "Post Production", postProductionStatus: "To Design", deliveryStyle: c.format === "graphic" ? "Still Graphic" : "Carousel" }, "the hand-over");
      writeOrder(c, true);
    }
    if (MEDIA_RESULTS_LIVE) setState((s) => ({ ...s, cards: s.cards.map((c) => (c.recordId ? { ...c, handed: true } : c)) }));
    if (showResults) {
      setState((s) => ({ ...s, after: [...s.after, user, { from: "flowy", at: Date.now(), text: `On it. I'm ${s.kind === "video" ? "cutting" : "designing"} ${s.cards.length === 1 ? "it" : "them"} now.` }],
        cards: s.cards.map((c) => ({ ...c, open: false })), working: { ids: s.cards.map((c) => c.id), idx: 0, startedAt: Date.now() } }));
      return;
    }
    // Not connected yet (Karen 2026-10-22): nothing is sent and the cards stay as they are.
    const text = S.kind === "video"
      ? "Got it. Editing is being connected, so nothing was sent yet. Your cards stay here."
      : "Got it. Designing is being connected, so nothing was sent yet. Your cards stay here.";
    const last = S.after[S.after.length - 1];
    if (last && last.text === text) return;
    say([user, { from: "flowy", text, at: Date.now() }]);
  };

  // Write with Flowy (FD5, the Studio's slides writer): one slide or all of them, copy only, nothing saved.
  const writeSlides = async (c: MediaCard, target: string) => {
    if (writing) return;
    const single = c.format === "graphic";
    const groups = mediaGroupsOf(c);
    const slides = groups.map((g) => {
      const words: Record<string, string> = {};
      for (const p of mediaPartsOf(g)) {
        const k = mediaPieceKey(g, p);
        const t = String(c.pieces[k] || "").trim();
        if (t) words[slidesPartOf(k)] = t;
      }
      return { slide: g, tag: mediaSlideTitle(single, groups, g), sections: mediaPartsOf(g).map((p) => slidesPartOf(mediaPieceKey(g, p))), words };
    });
    const instruction = askText.trim();
    setWriting({ card: c.id, groups: target === "all" ? groups : [target] });
    setAsk(null);
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 120000);
    let p: any = null;
    try {
      const res = await fetch(RAIL_SLIDES_WEBHOOK, {
        method: "POST",
        signal: ctrl.signal,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          auth: RAIL_SLIDES_AUTH,
          brandId: S.brandId,
          format: single ? "Single Graphic" : "Carousel",
          topic: "",
          hook: "",
          script: "",
          single,
          target,
          slides,
          instruction,
        }),
      });
      const j = await res.json().catch(() => null);
      p = Array.isArray(j) ? j[0] : j;
    } catch { p = null; }
    clearTimeout(timer);
    const patch: Record<string, string> = {};
    for (const x of (p && p.ok && Array.isArray(p.slides) ? p.slides : [])) {
      const g = String((x && x.slide) || "");
      if (!groups.includes(g) || (target !== "all" && g !== target)) continue;
      for (const [name, t] of Object.entries((x && x.sections) || {})) {
        const part = mediaPartsOf(g).find((pp) => slidesPartOf(mediaPieceKey(g, pp)) === name);
        if (!part || typeof t !== "string" || !t.trim()) continue;
        patch[mediaPieceKey(g, part)] = t.trim();
      }
    }
    setWriting(null);
    if (!Object.keys(patch).length) {
      console.warn("[Rail] Write with Flowy on the media slides got no words.", p && p.reason);
      errorToast(ctrl.signal.aborted ? "Flowy took too long. Please try again." : "Flowy couldn't write that. Please try again.");
      return;
    }
    setAskText("");
    patchCard(c.id, (cc) => ({ pieces: { ...cc.pieces, ...patch } }));
    queuePieces(c, patch);
    toast("Flowy wrote it. Have a look before you design.");
  };

  // ── Shared looks, the rail's own ──
  const mono: React.CSSProperties = { fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 600, letterSpacing: "0.09em", textTransform: "uppercase", color: "#737373" };
  const partLabel: React.CSSProperties = { ...mono, color: "#9aa0ab" };
  const req = (state: "miss" | "ok" | "", text: string) => (
    <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12px", color: state === "miss" ? "#B45309" : state === "ok" ? "#15803D" : "#a3a3a3" }}>{text}</span>
  );
  const greyPill: React.CSSProperties = {
    display: "inline-block", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", minWidth: 0, flexShrink: 1,
    fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 400, letterSpacing: "0.06em",
    textTransform: "uppercase", padding: "3px 8px", borderRadius: "999px", lineHeight: 1.4, background: "#F4F4F5", color: "#3F3F46",
  };
  const okPill: React.CSSProperties = { ...greyPill, background: "#F0FDF4", color: "#15803D" };
  const runPill: React.CSSProperties = { ...greyPill, background: "#F3E8FF", color: "#7E22CE" };
  const linkBtn: React.CSSProperties = { display: "inline-flex", alignItems: "center", gap: "6px", background: "transparent", border: "none", cursor: "pointer", padding: 0, color: "#A855F7", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", fontWeight: 500 };
  const muteLink: React.CSSProperties = { ...linkBtn, color: "#a3a3a3", fontWeight: 400, fontSize: "12.5px" };
  const outlineSm: React.CSSProperties = { height: "32px", padding: "0 12px", borderRadius: "8px", background: "white", border: "1px solid rgba(168,85,247,0.30)", color: "#A855F7", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: "6px", whiteSpace: "nowrap" };
  const offSm: React.CSSProperties = { ...outlineSm, background: "#F4F4F5", border: "1px solid #E4E4E7", color: "#A1A1AA", cursor: "default" };
  const gradSm = (off?: boolean): React.CSSProperties => ({ height: "32px", padding: "0 12px", borderRadius: "8px", border: "none", color: "white", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 600, background: off ? "#e5e5e5" : BRAND_GRADIENT, opacity: off ? 0.6 : 1, cursor: off ? "not-allowed" : "pointer", display: "inline-flex", alignItems: "center", gap: "6px", whiteSpace: "nowrap" });
  const menuRow: React.CSSProperties = { display: "flex", alignItems: "center", gap: "9px", width: "100%", padding: "11px 13px", background: "white", border: "none", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#171717", textAlign: "left", whiteSpace: "nowrap" };
  const sec = (label: string, right: React.ReactNode, body: React.ReactNode, extra?: React.ReactNode) => (
    <div style={{ marginTop: "16px" }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: "8px", marginBottom: "8px", flexWrap: "wrap" }}>
        <span style={mono}>{label}</span>{right}
        {extra ? <span style={{ marginLeft: "auto" }}>{extra}</span> : null}
      </div>
      {body}
    </div>
  );
  const flowyText = (t: MediaLine, i: number) => {
    const fresh = t.at > 0 && Date.now() - t.at < 2500;
    return t.from === "user" ? (
      <div key={i} className={fresh ? "strat-bubble-in" : undefined} style={{ display: "flex", justifyContent: "flex-end", margin: "0 0 16px" }}>
        <div className="strat-bubble" style={{ maxWidth: "75%", color: "#171717", borderRadius: "18px 18px 4px 18px", padding: "10px 14px", fontFamily: "'Geist', sans-serif", fontSize: "15px", lineHeight: 1.55, whiteSpace: "pre-wrap", overflowWrap: "anywhere" }}>{t.text}</div>
      </div>
    ) : (
      <div key={i} className={fresh ? "strat-bubble-in" : undefined} style={{ maxWidth: "640px", margin: "0 0 12px", fontFamily: "'Geist', sans-serif", fontSize: "15px", fontWeight: 400, lineHeight: 1.6, color: "#171717", animationDelay: fresh ? "0.3s" : undefined }}>
        {t.text}
      </div>
    );
  };
  const chips = (children: React.ReactNode) => (
    <StaggerAfterBubbles count={1}>
      <div className="flex flex-wrap justify-end gap-2 mt-12" style={{ marginBottom: "10px" }}>{children}</div>
    </StaggerAfterBubbles>
  );
  const backRow = (
    <StaggerAfterBubbles count={1}>
      <div style={{ display: "flex", justifyContent: "flex-end", paddingBottom: "14px" }}>
        <button onClick={goBack} className="inline-flex items-center gap-1.5 uppercase cursor-pointer bg-transparent border-none"
          style={{ color: "#A855F7", fontFamily: "'Geist Mono', monospace", fontSize: isDesktop ? "10.5px" : "12px", fontWeight: 500, letterSpacing: "0.1em", padding: "4px 0" }}>
          <ArrowLeft className="w-3 h-3" style={{ color: "#A855F7" }} strokeWidth={2.2} /> Go back
        </button>
      </div>
    </StaggerAfterBubbles>
  );

  // ── The current question ──
  const question = (() => {
    if (S.step === "cards") return null;
    if (!S.ask) return <div style={{ margin: "0 0 12px", fontSize: "15px", lineHeight: 1.6, color: "#171717" }}><TypingDots /></div>;
    let body: React.ReactNode = null;
    if (S.step === "ws") {
      body = chips(workspaces.map((w) => (
        <ReplyChip key={w.id} onClick={() => { onPickWs(w.id); answer(w.name, { step: "brand", ask: "Which brand is it for?" }); }}>{w.name}</ReplyChip>
      )));
    } else if (S.step === "brand") {
      if (!brandsReady) body = <div style={{ margin: "0 0 12px", fontSize: "15px", lineHeight: 1.6, color: "#171717" }}><TypingDots /></div>;
      else if (!brands.length) body = <BotLine delayIndex={1}>No brands set up yet. Head to the Strategy tab to onboard one.</BotLine>;
      else body = chips(brands.map((b) => (
        <ReplyChip key={b.id} onClick={() => answer(b.name, { step: "kind", brandId: b.id, brandName: b.name, ask: "Videos to edit, or static designs?" })}>{b.name}</ReplyChip>
      )));
    } else if (S.step === "kind") {
      body = chips(<>
        <ReplyChip onClick={() => answer("Video", { step: "count", kind: "video", count: 1, ask: "How many videos?" })}>Video</ReplyChip>
        <ReplyChip onClick={() => answer("Static", { step: "count", kind: "static", count: 1, ask: "How many designs?" })}>Static</ReplyChip>
      </>);
    } else if (S.step === "count") {
      const stp: React.CSSProperties = { width: "32px", height: "32px", borderRadius: "8px", border: "1px solid #E5E5E5", background: "white", cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "16px", lineHeight: 1, color: "#404040", padding: 0 };
      body = (
        <StaggerAfterBubbles count={1}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "10px", flexWrap: "wrap", margin: "12px 0 10px" }}>
            <span style={mono}>{S.kind === "video" ? "Videos" : "Designs"}</span>
            <button style={{ ...stp, opacity: S.count <= 1 ? 0.4 : 1 }} disabled={S.count <= 1} aria-label={`Fewer ${noun(2)}`} onClick={() => setState((s) => ({ ...s, count: Math.max(1, s.count - 1) }))}>−</button>
            <span style={{ minWidth: "22px", textAlign: "center", fontFamily: "'Geist', sans-serif", fontSize: "16px", fontWeight: 600, color: "#171717" }}>{S.count}</span>
            <button style={{ ...stp, opacity: S.count >= MEDIA_MAX ? 0.4 : 1 }} disabled={S.count >= MEDIA_MAX} aria-label={`More ${noun(2)}`} onClick={() => setState((s) => ({ ...s, count: Math.min(MEDIA_MAX, s.count + 1) }))}>+</button>
            <GradientButton onClick={startCards} disabled={S.creating}>{S.creating ? "Setting up…" : "Continue"}</GradientButton>
          </div>
        </StaggerAfterBubbles>
      );
    }
    return (
      <RailDelayCtx.Provider value={0.3}>
        <div key={"mq-" + S.step + S.log.length}>
          <BotLine delayIndex={0}>{S.ask}</BotLine>
          {body}
          {backRow}
        </div>
      </RailDelayCtx.Provider>
    );
  })();

  // ── A card's footage: a drop area, then the clips or photos as small previews with their names ──
  const footage = (c: MediaCard, which: "clips" | "photos") => {
    const files = c[which];
    // Every way in opens the picker: My Uploads, Flowshift Media or Upload File. A drop goes straight to its
    // Upload File tab with the dropped files waiting.
    const open = (dropped?: File[]) => setPicker({ cardId: c.id, which, files: dropped && dropped.length ? dropped : undefined });
    // Off this card only. The file stays in the library.
    const remove = (f: MediaFile) => { mediaFreeFile(f); detachFromRecord(c, f); patchCard(c.id, (cc) => ({ [which]: cc[which].filter((x) => x.id !== f.id) } as any)); };
    const onDrop = (e: any) => { e.preventDefault(); open(Array.from(e.dataTransfer?.files || []) as File[]); };
    if (!files.length && which === "clips") return (
      <button type="button" onDragOver={(e: any) => e.preventDefault()} onDrop={onDrop} onClick={() => open()} aria-label="Add footage"
        style={{ display: "block", boxSizing: "border-box", width: "100%", border: "1.5px dashed #D4D4D8", borderRadius: "12px", padding: "18px 14px", textAlign: "center", cursor: "pointer", background: "#FAFAFA" }}>
        <span style={{ display: "flex", justifyContent: "center", marginBottom: "6px" }}><Upload size={16} strokeWidth={2} style={{ color: "#A855F7" }} /></span>
        <span style={{ display: "block", fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 500, color: "#171717" }}>Add footage</span>
        <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12.5px", color: "#737373" }}>Pick from your uploads or upload from your {isDesktop ? "computer" : "phone"}</span>
      </button>
    );
    const tileH = which === "clips" ? 96 : 72;
    return (
      <div onDragOver={(e: any) => e.preventDefault()} onDrop={onDrop}>
        {files.length > 0 && (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", alignItems: "flex-start", marginBottom: which === "photos" ? "8px" : 0 }}>
            {files.map((f) => (
              <div key={f.id} style={{ width: "58px", display: "flex", flexDirection: "column", gap: "4px" }}>
                <div style={{ position: "relative", width: "58px", height: `${tileH}px`, borderRadius: "7px", overflow: "hidden", background: "linear-gradient(160deg,#5b6773,#2E3B44)" }}>
                  {f.thumb ? <img src={f.thumb} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                    : f.url && f.kind === "video" ? <video src={f.url + "#t=0.1"} muted playsInline preload="metadata" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} /> : null}
                  {!f.thumb && f.url && f.kind === "image" && <img src={f.url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />}
                  {f.kind === "video" && <span aria-hidden="true" style={{ position: "absolute", left: "50%", top: "50%", transform: "translate(-35%,-50%)", borderLeft: "10px solid rgba(255,255,255,.85)", borderTop: "7px solid transparent", borderBottom: "7px solid transparent" }} />}
                  <button onClick={() => remove(f)} aria-label={`Remove ${f.name}`} title="Remove"
                    style={{ position: "absolute", right: "3px", top: "3px", width: "18px", height: "18px", borderRadius: "50%", background: "rgba(0,0,0,.55)", color: "white", border: "none", padding: 0, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
                    <X size={10} strokeWidth={2.4} />
                  </button>
                </div>
                <span title={f.name} style={{ fontFamily: "'Geist', sans-serif", fontSize: "10.5px", lineHeight: 1.25, color: "#525252", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{f.name}</span>
              </div>
            ))}
            {which === "clips" && (
              <button type="button" onClick={() => open()} aria-label="Add another clip" title="Add another clip" style={{ width: "58px", height: `${tileH}px`, boxSizing: "border-box", borderRadius: "7px", border: "1.5px dashed #D4D4D8", background: "white", color: "#A855F7", cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0 }}>
                <Plus size={18} strokeWidth={2} />
              </button>
            )}
          </div>
        )}
        {which === "photos" && (
          <button type="button" onClick={() => open()} style={{ ...linkBtn, display: "inline-flex" }}>
            <Plus size={13} strokeWidth={2.2} /> Add footage or photos
          </button>
        )}
      </div>
    );
  };
  const tiles = (label: string, list: { key: string; name: string; says: string }[], picked: string, onPick: (k: string) => void) => (
    <>
      <div role="radiogroup" aria-label={label} style={{ display: "flex", flexWrap: "wrap", gap: "12px 10px" }}>
        {list.map((x) => {
          const on = picked === x.key;
          return (
            <button key={x.key} role="radio" aria-checked={on ? "true" : "false"} title={x.says} onClick={() => onPick(x.key)}
              style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "6px", width: "66px", padding: 0, border: "none", background: "none", cursor: "pointer", fontFamily: "'Geist', sans-serif" }}>
              <span aria-hidden="true" style={{ position: "relative", width: "58px", height: "72px", borderRadius: "6px", overflow: "hidden", background: "#F6F4F1", boxShadow: on ? "0 0 0 2px #16A34A" : "0 0 0 1px #E4E6EA", transition: "box-shadow .15s ease" }}>
                <MediaTileArt k={x.key} />
              </span>
              <span style={{ fontSize: "11.5px", lineHeight: 1.25, textAlign: "center", color: on ? "#15803D" : "#4E525A", fontWeight: on ? 600 : 400 }}>{x.name}</span>
            </button>
          );
        })}
      </div>
      {picked && <div style={{ fontFamily: "'Geist', sans-serif", fontSize: "12px", fontWeight: 300, color: "#6C707A", lineHeight: 1.45, marginTop: "8px" }}>{(list.find((x) => x.key === picked) || { says: "" }).says}</div>}
    </>
  );
  const bottomRow = (label: string) => (
    // Flowy decides first, Personalize on the right, greyed until it is built (Karen 2026-10-22).
    <div style={{ display: "flex", alignItems: "center", gap: "12px", flexWrap: "wrap", marginTop: "18px", paddingTop: "14px", borderTop: "1px solid #f4f4f4" }}>
      <MediaFlowyDecides />
      <span style={{ flex: 1 }} />
      <button type="button" aria-disabled="true" title="Coming soon" style={offSm}>{label}</button>
    </div>
  );

  // ── Slides Copy and Graphic Copy, as the Creative Studio draws them (creative-hub-v1.tsx copyEditor ~10392,
  // copyFlowyLink ~10322, copyAskBox ~10335, FLOWY_PILL ~1455, ADD_PILL ~1463): one white box per slide with
  // the cover as Slide 1, each section a row with its mono name on the left, the tools only on the slide being
  // worked on, and Add a slide under the last ──
  const CH_INK = "#171717", CH_ACCENT = "#A855F7", CH_ACCENT_DEEP = "#7E22CE", CH_HAIR = "#E4E6EA", CH_ROW = "#EEF0F3";
  const flowyPill = (busy: boolean): React.CSSProperties => ({
    display: "inline-flex", alignItems: "center", gap: "6px", height: "26px", padding: "0 10px", borderRadius: "999px",
    border: "1px solid #EDEDED", background: "white", boxShadow: "0 1px 2px rgba(22,23,26,0.05)", fontFamily: "'Geist', sans-serif", fontSize: "12px", fontWeight: 500,
    color: CH_ACCENT_DEEP, whiteSpace: "nowrap", flexShrink: 0, cursor: busy ? "not-allowed" : "pointer", opacity: busy ? 0.5 : 1,
  });
  const flowyLink = (c: MediaCard, target: string, hasWords: boolean, label: string) => {
    const busy = !!writing;
    const verb = hasWords ? "Rewrite" : "Write";
    const open = !!ask && ask.card === c.id && ask.target === target;
    return (
      <button type="button" className={busy ? undefined : "fs-flowypill"} aria-label={`${verb} ${label} with Flowy`} aria-expanded={open ? "true" : "false"}
        aria-disabled={busy ? "true" : undefined}
        onMouseDown={(e: any) => e.preventDefault()}
        onClick={(e: any) => { e.stopPropagation(); if (busy) return; setAsk(open ? null : { card: c.id, target }); }}
        style={flowyPill(busy)}>
        <MediaFlowyMark size={14} />{target === "all" ? `${verb} all slides with Flowy` : `${verb} with Flowy`}
      </button>
    );
  };
  const askBox = (c: MediaCard, target: string, hasWords: boolean) => (
    <div style={{ display: "flex", flexDirection: "column", gap: "8px", padding: "10px 12px", borderRadius: "8px", border: `1px solid ${CH_ACCENT}`, background: "white", boxShadow: "0 0 0 3px rgba(168,85,247,0.10)" }}>
      <AutoGrowTextarea autoFocus value={askText} aria-label="What Flowy should know"
        onChange={(e: any) => setAskText(e.target.value)}
        placeholder={hasWords ? "Anything to change? Optional, like shorter or more direct" : "Anything Flowy should know? Optional"}
        style={{ display: "block", width: "100%", boxSizing: "border-box", padding: "2px 0", margin: 0, border: "none", outline: "none", background: "transparent", fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 300, lineHeight: 1.45, color: "#2B2B31", whiteSpace: "pre-wrap" }} />
      <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "8px" }}>
        <button type="button" className="fs-ghost" onClick={() => { setAsk(null); setAskText(""); }}
          style={{ height: "32px", padding: "0 12px", border: "none", borderRadius: "999px", background: "transparent", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, color: "#6C707A", cursor: "pointer" }}>Cancel</button>
        <button type="button" onClick={() => writeSlides(c, target)}
          style={{ display: "inline-flex", alignItems: "center", gap: "6px", height: "32px", padding: "0 14px", border: "none", borderRadius: "999px", background: CH_INK, fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, color: "white", cursor: "pointer" }}>
          <MediaFlowyMark size={13} />{hasWords ? "Rewrite" : "Write"}
        </button>
      </div>
    </div>
  );
  // The Studio's writing state in a slide's box: the wave, "Flowy is writing", three grey lines.
  const writingBox = (
    <div role="status" aria-label="Flowy is writing" style={{ padding: "2px 0" }}>
      <div style={{ display: "flex", alignItems: "center", gap: "9px", marginBottom: "12px" }}>
        <MediaFlowyMark size={18} />
        <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 450, color: CH_ACCENT_DEEP }}>Flowy is writing</span>
      </div>
      {[94, 81, 57].map((w, i) => <span key={w} className="fs-pulse" style={{ display: "block", width: `${w}%`, height: "10px", borderRadius: "5px", background: "#F0F0F2", marginBottom: i < 2 ? "9px" : 0 }} />)}
    </div>
  );
  const pieceName = (p: string) => (p === "CTA" ? "CTA" : p);
  const pieceWord = (p: string) => (p === "CTA" ? "call to action" : p.toLowerCase());
  const slideBoxes = (c: MediaCard) => {
    const single = c.format === "graphic";
    const groups = mediaGroupsOf(c);
    const has = (g: string) => mediaPartsOf(g).some((p) => String(c.pieces[mediaPieceKey(g, p)] || "").trim());
    const anyWords = groups.some(has);
    const done = groups.filter((g) => g !== "closing").every((g) => String(c.pieces[mediaPieceKey(g, "Title")] || "").trim());
    const allTarget = single ? "s1" : "all";
    const middle = groups.filter((g) => /^s\d$/.test(g)).length;
    const activeG = (ask && ask.card === c.id && ask.target !== allTarget ? ask.target : null) || (activeSlide && activeSlide.card === c.id ? activeSlide.g : null);
    const setPieces = (patch: Record<string, string>) => {
      patchCard(c.id, (cc) => ({ pieces: { ...cc.pieces, ...patch } }));
      queuePieces(c, patch);
    };
    // A new slide goes in before the closing, as in the Studio.
    const addSlide = () => {
      if (middle >= MEDIA_MIDDLE.length) return;
      const next = MEDIA_MIDDLE[middle];
      patchCard(c.id, (cc) => {
        const at = cc.groups.indexOf("closing");
        return { groups: at < 0 ? [...cc.groups, next] : [...cc.groups.slice(0, at), next, ...cc.groups.slice(at)] };
      });
      setActiveSlide({ card: c.id, g: next });
    };
    // Taking slide n out moves the later slides' words up one, and clears the last (the Studio's removeCopySlide).
    const removeSlide = (g: string) => {
      const n = Number(g.slice(1));
      const patch: Record<string, string> = {};
      for (let k = n; k <= middle; k++) {
        for (const p of mediaPartsOf(`s${k}`)) patch[mediaPieceKey(`s${k}`, p)] = k < middle ? String(c.pieces[mediaPieceKey(`s${k + 1}`, p)] || "") : "";
      }
      const last = `s${middle}`;
      patchCard(c.id, (cc) => ({ groups: cc.groups.filter((x) => x !== last), pieces: { ...cc.pieces, ...patch } }));
      queuePieces(c, patch);
      setActiveSlide(null);
      if (ask && ask.card === c.id) setAsk(null);
    };
    return sec(single ? "Graphic Copy" : "Slides Copy", req(done ? "ok" : "miss", done ? "Filled" : single ? "Required · A title" : "Required · A title on every slide"), (
      <div style={{ display: "flex", flexDirection: "column", gap: "26px" }}>
        {ask && ask.card === c.id && ask.target === allTarget && <div style={{ marginBottom: "-8px" }}>{askBox(c, allTarget, anyWords)}</div>}
        {groups.map((g) => {
          const tag = single ? "" : mediaSlideTitle(single, groups, g);
          const slideName = tag ? tag.split(" · ")[0] : "Graphic";
          const busy = !!writing && writing.card === c.id && writing.groups.includes(g);
          const active = activeG === g;
          const removable = /^s\d$/.test(g) && middle > 1;
          return (
            <div key={g} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
              {tag && (
                <div style={{ display: "flex", alignItems: "center", gap: "10px", minHeight: "28px" }}>
                  <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: 500, letterSpacing: "-0.005em", color: "#09090B" }}>{tag}</span>
                  <span style={{ flex: 1 }} />
                  {active && flowyLink(c, g, has(g), slideName.toLowerCase())}
                  {active && removable && (
                    <button type="button" className="fs-ghost" aria-label={`Remove ${slideName.toLowerCase()}`} title="Remove this slide" onClick={() => removeSlide(g)}
                      style={{ width: "26px", height: "26px", padding: 0, border: "none", borderRadius: "7px", background: "transparent", color: "#9AA0AB", display: "inline-flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
                      <X size={14} strokeWidth={2} />
                    </button>
                  )}
                </div>
              )}
              {tag && ask && ask.card === c.id && ask.target === g && askBox(c, g, has(g))}
              {busy ? <div style={{ borderRadius: "8px", border: `1px solid ${CH_HAIR}`, background: "white", padding: "12px 14px" }}>{writingBox}</div> : (
                <div onClick={() => { if (!active) setActiveSlide({ card: c.id, g }); }}
                  style={{ borderRadius: "8px", border: `1px solid ${active ? CH_ACCENT : CH_HAIR}`, boxShadow: active ? "0 0 0 3px rgba(168,85,247,0.10)" : "none", background: "white", transition: "border-color .16s ease" }}>
                  {mediaPartsOf(g).map((p, i) => {
                    const k = mediaPieceKey(g, p);
                    return (
                      <div key={k} style={{ display: "flex", alignItems: "flex-start", gap: "12px", minHeight: "40px", padding: "0 12px", borderTop: i ? `1px solid ${CH_ROW}` : "none" }}>
                        <span style={{ flexShrink: 0, width: "68px", paddingTop: "13px", lineHeight: "14px", fontFamily: "'Geist Mono', monospace", fontSize: "10px", fontWeight: 500, letterSpacing: "0.1em", textTransform: "uppercase", color: "#9AA0AB" }}>{pieceName(p)}</span>
                        <AutoGrowTextarea
                          value={c.pieces[k] || ""}
                          onFocus={() => setActiveSlide({ card: c.id, g })}
                          onChange={(e: any) => setPieces({ [k]: e.target.value })}
                          aria-label={`${slideName} ${pieceName(p)}`}
                          placeholder={`No ${pieceWord(p)} yet`}
                          style={{ flex: 1, minWidth: 0, display: "block", boxSizing: "border-box", padding: "10px 0", margin: 0, border: "none", outline: "none", background: "transparent", fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 300, lineHeight: 1.45, color: "#2B2B31", whiteSpace: "pre-wrap" }}
                        />
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
        {!single && (
          <div style={{ display: "flex", alignItems: "center", gap: "12px", flexWrap: "wrap" }}>
            {middle < MEDIA_MIDDLE.length && (
              <button type="button" className="fs-addbtn" onClick={addSlide}
                style={{ display: "inline-flex", alignItems: "center", gap: "8px", padding: "10px 14px", borderRadius: "8px", border: "none", background: "#F4F4F5", fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 500, lineHeight: 1.2, color: CH_INK, whiteSpace: "nowrap", cursor: "pointer" }}>
                <Plus size={14} strokeWidth={2} style={{ flexShrink: 0 }} />Add a slide
              </button>
            )}
            <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12px", fontWeight: 300, color: "#6C707A" }}>
              {middle < MEDIA_MIDDLE.length ? "Up to 10 slides, cover and closing included. A new slide goes in before the closing." : "This carousel has the most slides it can take: 10, cover and closing included."}
            </span>
          </div>
        )}
      </div>
    ), flowyLink(c, allTarget, anyWords, single ? "the graphic" : "all slides"));
  };

  const videoBody = (c: MediaCard) => (
    <>
      {sec("Footage", req(c.clips.length ? "ok" : "miss", c.clips.length ? "Added" : "Required"), footage(c, "clips"))}
      {sec("Edit Type", req(c.editType ? "ok" : "miss", c.editType ? (MEDIA_EDIT_TYPES.find((x) => x.key === c.editType) || { name: "" }).name : "Required · Pick one"),
        tiles("Edit Type", MEDIA_EDIT_TYPES, c.editType, (k) => { patchCard(c.id, { editType: k }); writeOrder({ ...c, editType: k }); }))}
      {bottomRow("Personalize edit")}
    </>
  );
  const staticBody = (c: MediaCard) => {
    const story = c.look === "story";
    const segBtn = (on: boolean): React.CSSProperties => ({ height: "30px", padding: "0 12px", borderRadius: SEGMENT_PILL_RADIUS, border: "none", background: on ? "white" : "transparent", boxShadow: on ? "0 1px 2px rgba(0,0,0,.08)" : "none", fontFamily: "'Geist', sans-serif", fontSize: "13px", fontWeight: 500, color: on ? "#171717" : "#6C707A", cursor: "pointer", whiteSpace: "nowrap" });
    return (
      <>
        {sec("Format", null, (
          <div role="group" aria-label="Format" style={{ display: "inline-flex", gap: "3px", padding: "3px", borderRadius: SEGMENT_TRACK_RADIUS, background: SEGMENT_TRACK }}>
            <button type="button" aria-pressed={c.format === "carousel" ? "true" : "false"} onClick={() => { if (c.format === "carousel") return; patchCard(c.id, { format: "carousel" }); recUpdate(c.recordId, { deliveryStyle: "Carousel" }, "the format"); }} style={segBtn(c.format === "carousel")}>Carousel</button>
            <button type="button" aria-pressed={c.format === "graphic" ? "true" : "false"} onClick={() => { if (c.format === "graphic") return; patchCard(c.id, { format: "graphic" }); recUpdate(c.recordId, { deliveryStyle: "Still Graphic" }, "the format"); }} style={segBtn(c.format === "graphic")}>Single Graphic</button>
          </div>
        ))}
        {sec("Design Style", req(c.look ? "ok" : "miss", c.look ? (MEDIA_LOOKS.find((x) => x.key === c.look) || { name: "" }).name : "Required · Pick one"),
          tiles("Design Style", MEDIA_LOOKS, c.look, (k) => { patchCard(c.id, { look: k }); writeOrder({ ...c, look: k }); }))}
        {slideBoxes(c)}
        {sec("Footage", req(story ? (c.photos.length ? "ok" : "miss") : "", story ? (c.photos.length ? "Added" : "Required for Story") : "Optional"), footage(c, "photos"))}
        <label style={{ display: "flex", alignItems: "flex-start", gap: "10px", marginTop: "16px", padding: "10px 12px", borderRadius: "10px", background: c.copyReady ? "#F0FDF4" : "#FAFAFA", border: `1px solid ${c.copyReady ? "#BBF7D0" : "#ededed"}`, cursor: "pointer", fontFamily: "'Geist', sans-serif", fontSize: "14px", lineHeight: 1.45, color: "#171717" }}>
          <input type="checkbox" checked={c.copyReady} onChange={(e: any) => patchCard(c.id, { copyReady: !!e.target.checked })} style={{ width: "18px", height: "18px", margin: "1px 0 0", accentColor: "#16A34A", flexShrink: 0 }} />
          <span>The copy is ready to design</span>
        </label>
        {bottomRow("Personalize design")}
      </>
    );
  };

  // ── A result on its own card: drawn thumbnails (never pictures), Re-do and Ready to Schedule ──
  const resultBlock = (c: MediaCard, i: number) => {
    const r = c.result!;
    const vid = S.kind === "video";
    const groups = mediaGroupsOf(c);
    const sthumb = (k: number, cover: boolean, big?: boolean) => (
      <div key={k} style={{ position: "relative", width: big ? "96px" : "84px", height: big ? "120px" : "105px", borderRadius: "7px", overflow: "hidden", flexShrink: 0, background: cover ? "#2b2540" : "#F5F1EA", boxShadow: "0 0 0 1px #ece7de", padding: "9px 8px", boxSizing: "border-box" }}>
        <div style={{ height: cover ? "8px" : "6px", borderRadius: "2px", background: cover ? "#fff" : "#2b2540", marginBottom: "4px" }} />
        <div style={{ height: cover ? "8px" : "6px", width: "70%", borderRadius: "2px", background: cover ? "#fff" : "#2b2540", marginBottom: "4px" }} />
        <div style={{ height: "3px", borderRadius: "2px", background: cover ? "rgba(255,255,255,.55)" : "#b9b2a6", marginBottom: "3px" }} />
        <div style={{ height: "3px", width: "80%", borderRadius: "2px", background: cover ? "rgba(255,255,255,.55)" : "#b9b2a6" }} />
        {!big && <span style={{ position: "absolute", right: "6px", bottom: "5px", fontFamily: "'Geist Mono', monospace", fontSize: "8.5px", color: cover ? "rgba(255,255,255,.6)" : "#8b8478" }}>{k + 1}</span>}
      </div>
    );
    const queuedText = r.queued === "captions" ? "Queued to schedule. Flowy writes the captions." : "Queued to schedule.";
    return (
      <div style={{ display: "flex", gap: "12px", alignItems: "flex-start", flexWrap: "wrap", padding: "14px", borderTop: "1px solid #f4f4f4" }}>
        <div className="fs-thinscroll" style={{ display: "flex", gap: "8px", overflowX: "auto", maxWidth: "100%", paddingBottom: "2px" }}>
          {vid ? (
            <div style={{ position: "relative", width: "84px", height: "150px", borderRadius: "9px", overflow: "hidden", flexShrink: 0, background: "linear-gradient(165deg,#56636e,#22303a)" }}>
              <div style={{ position: "absolute", left: "7px", right: "7px", top: "16px", height: "16px", borderRadius: "4px", background: "#fff" }} />
              <span aria-hidden="true" style={{ position: "absolute", left: "50%", top: "54%", transform: "translate(-40%,-50%)", borderLeft: "14px solid rgba(255,255,255,.85)", borderTop: "9px solid transparent", borderBottom: "9px solid transparent" }} />
              <div style={{ position: "absolute", left: "12px", right: "12px", bottom: "34px", height: "5px", borderRadius: "2px", background: "#FACC15" }} />
              <div style={{ position: "absolute", left: "18px", right: "18px", bottom: "26px", height: "4px", borderRadius: "2px", background: "rgba(255,255,255,.9)" }} />
            </div>
          ) : c.format === "carousel" ? groups.map((_, k) => sthumb(k, k === 0)) : sthumb(0, true, true)}
        </div>
        <div style={{ flex: 1, minWidth: "160px", display: "flex", flexDirection: "column", gap: "6px" }}>
          <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "13.5px", fontWeight: 500, color: "#171717" }}>
            {vid ? "Edited video" : c.format === "carousel" ? "Designed carousel" : "Designed graphic"}{r.version > 1 ? ` · Version ${r.version}` : ""}
          </span>
          <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12.5px", color: "#737373", lineHeight: 1.45 }}>
            {vid ? "9:16 · attached to this card" : c.format === "carousel" ? `${groups.length} slides · 4:5 · attached to this card` : "4:5 · attached to this card"}
          </span>
          {r.queued ? (
            <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "12.5px", color: "#047857", lineHeight: 1.45 }}>
              {queuedText}{" "}
              <button type="button" onClick={() => { patchCard(c.id, { result: { ...r, queued: "" } }); say([{ from: "flowy", at: Date.now(), text: `${itemName(i)} is off the schedule queue.` }]); }} style={{ ...linkBtn, fontSize: "12.5px" }}>Undo</button>
            </span>
          ) : c.redo ? (
            // Re-do: a design takes a note on what to change, a video is just cut again (Karen 2026-10-22).
            <div style={{ display: "flex", flexDirection: "column", gap: "8px", marginTop: "4px" }}>
              {vid ? (
                <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "13px", color: "#525252", lineHeight: 1.45 }}>Re-do this video? Flowy cuts it again from the same footage.</span>
              ) : (
                <AutoGrowTextarea autoFocus value={c.redoNote} aria-label="What should change?"
                  onChange={(e: any) => patchCard(c.id, { redoNote: e.target.value })}
                  placeholder="What should change?"
                  style={{ display: "block", width: "100%", boxSizing: "border-box", minHeight: "60px", border: "1px solid #ededed", borderRadius: "10px", padding: "8px 10px", outline: "none", background: "white", fontFamily: "'Geist', sans-serif", fontSize: "14px", lineHeight: 1.45, color: "#171717" }} />
              )}
              <div style={{ display: "flex", justifyContent: "flex-end", gap: "8px", flexWrap: "wrap" }}>
                <button type="button" onClick={() => patchCard(c.id, { redo: false, redoNote: "" })} style={{ ...outlineSm, border: "none", color: "#737373" }}>Cancel</button>
                <button type="button" disabled={!vid && !c.redoNote.trim()}
                  onClick={() => {
                    if (!vid && !c.redoNote.trim()) return;
                    patchCard(c.id, { redo: false, redoNote: "", result: { version: r.version + 1, queued: "" } });
                    say([{ from: "flowy", at: Date.now(), text: vid ? `Re-doing ${itemName(i).toLowerCase()}. The new cut lands on its card.` : `Re-doing ${itemName(i).toLowerCase()} with your note. The new version lands on its card.` }]);
                  }}
                  style={gradSm(!vid && !c.redoNote.trim())}><RotateCcw size={13} strokeWidth={2.2} /> Re-do This One</button>
              </div>
            </div>
          ) : (
            <div style={{ display: "flex", gap: "8px", flexWrap: "wrap", marginTop: "4px" }}>
              <button type="button" onClick={() => { setMenuFor(null); patchCard(c.id, { redo: true }); }} style={outlineSm}><RotateCcw size={13} strokeWidth={2.2} /> Re-do</button>
              {/* The Add to Production split button's look: its list opens above it. */}
              <div ref={menuFor === c.id ? menuWrapRef : undefined} style={{ position: "relative", display: "inline-flex", borderRadius: "8px", boxShadow: "0 6px 16px -8px rgba(168,85,247,0.7)" }}>
                <button type="button" aria-haspopup="menu" aria-expanded={menuFor === c.id ? "true" : "false"} onClick={() => setMenuFor(menuFor === c.id ? null : c.id)}
                  style={{ ...gradSm(), padding: "0 10px 0 12px" }}>
                  <Check size={13} strokeWidth={2.4} /> Ready to Schedule
                  <ChevronUp size={14} strokeWidth={2.4} style={{ marginLeft: "2px", transform: menuFor === c.id ? "rotate(180deg)" : "none", transition: "transform 0.18s ease" }} />
                </button>
                {menuFor === c.id && (
                  <div role="menu" style={{ position: "absolute", right: 0, bottom: "38px", zIndex: 40, minWidth: "230px", background: "white", border: "1px solid #ededed", borderRadius: "12px", overflow: "hidden", boxShadow: "0 1px 2px rgba(22,23,26,.04),0 12px 28px -16px rgba(30,32,40,.28)", animation: "fsBubbleIn 0.16s cubic-bezier(0.16,1,0.3,1) both" }}>
                    <button role="menuitem" className="fs-menu-row" style={menuRow}
                      onClick={() => { setMenuFor(null); patchCard(c.id, { result: { ...r, queued: "queue" } }); say([{ from: "flowy", at: Date.now(), text: `${itemName(i)} is queued to schedule.` }]); }}>
                      <Calendar size={15} strokeWidth={2} style={{ color: "#A855F7" }} /> Queue
                    </button>
                    <button role="menuitem" className="fs-menu-row" style={{ ...menuRow, borderTop: "1px solid #f4f4f4" }}
                      onClick={() => { setMenuFor(null); patchCard(c.id, { result: { ...r, queued: "captions" } }); say([{ from: "flowy", at: Date.now(), text: `${itemName(i)} is queued, and I'm writing its captions.` }]); }}>
                      <MessageSquare size={15} strokeWidth={2} style={{ color: "#A855F7" }} /> Queue and Create Captions
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  };

  const card = (c: MediaCard, i: number) => {
    const m = mediaMissing(S.kind, c);
    const w = mediaListWords(m);
    const working = !!S.working && S.working.ids.includes(c.id);
    const tag = working ? <span style={runPill}>{S.kind === "video" ? "Editing" : "Designing"}</span>
      : c.result ? <span style={okPill}>{c.result.queued ? "Queued" : "Ready to review"}</span>
      : !m.length ? <span style={okPill}>Ready</span>
      : <span style={greyPill} title={`Needs ${w}`}>{w.length <= (isDesktop ? 26 : 16) ? `Needs ${w}` : `Needs ${m.length} things`}</span>;
    const sub = S.kind === "video"
      ? `${c.clips.length ? `${c.clips.length} ${c.clips.length === 1 ? "clip" : "clips"}` : "No footage yet"}${c.editType ? ` · ${(MEDIA_EDIT_TYPES.find((x) => x.key === c.editType) || { name: "" }).name}` : ""}`
      : `${c.format === "carousel" ? `Carousel · ${c.groups.length} slides` : "Single Graphic"}${c.look ? ` · ${(MEDIA_LOOKS.find((x) => x.key === c.look) || { name: "" }).name}` : ""}`;
    const editable = !c.result && !working;
    return (
      <div key={c.id} style={{ position: "relative", zIndex: menuFor === c.id ? 5 : undefined, background: "white", border: "1px solid #ededed", borderRadius: "14px", minWidth: 0 }}>
        <button type="button" onClick={() => patchCard(c.id, { open: !c.open })} aria-expanded={c.open ? "true" : "false"} disabled={!editable}
          style={{ display: "flex", alignItems: "center", gap: "10px", width: "100%", padding: "13px 14px", background: "none", border: "none", textAlign: "left", cursor: editable ? "pointer" : "default", fontFamily: "'Geist', sans-serif", color: "#171717", boxSizing: "border-box" }}>
          {/* The name over its summary, so a phone keeps both readable beside the status tag. */}
          <span style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: "1px" }}>
            <span style={{ fontSize: "14px", fontWeight: 600, lineHeight: 1.35 }}>{itemName(i)}</span>
            <span style={{ fontSize: "12.5px", lineHeight: 1.35, color: "#737373", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{sub}</span>
          </span>
          {tag}
          {editable && <ChevronDown size={15} strokeWidth={2} style={{ color: "#a3a3a3", flexShrink: 0, transform: c.open ? "rotate(180deg)" : "none", transition: "transform 0.15s ease" }} />}
        </button>
        {c.result && showResults && !working && resultBlock(c, i)}
        {c.open && editable && (
          <div style={{ padding: "2px 14px 16px", borderTop: "1px solid #f4f4f4" }}>
            {S.kind === "video" ? videoBody(c) : staticBody(c)}
          </div>
        )}
      </div>
    );
  };

  const hasResults = showResults && S.cards.some((c) => c.result);
  const unqueued = S.cards.filter((c) => c.result && !c.result.queued);
  return (
    <>
      {/* The Studio's hovers for the copy section's buttons (creative-hub-v1.tsx ~4919-4981). */}
      <style>{`.fs-flowypill:hover{background:#FAF5FF !important;border-color:rgba(168,85,247,0.45) !important}.fs-addbtn:hover{background:#E9E9EC !important}.fs-ghost:hover{background:#F4F4F5 !important}@keyframes fsPulse{0%,100%{opacity:1}50%{opacity:.45}}.fs-pulse{animation:fsPulse 1.4s ease-in-out infinite}`}</style>
      {S.log.map(flowyText)}
      {question}
      {S.step === "cards" && (
        <>
          {/* Flowy's reply first, then the cards under it (Karen, 2026-10-23). The cards wait until the line is in. */}
          {S.after.slice(0, 1).map(flowyText)}
          <div className="strat-bubble-in" style={{ display: "flex", flexDirection: "column", gap: "12px", margin: "4px 0 16px", animationDelay: S.after[0] && S.after[0].at > 0 && Date.now() - S.after[0].at < 2500 ? "0.9s" : "0s" }}>
            {S.cards.map(card)}
          </div>
          {S.after.slice(1).map((t, i) => flowyText(t, i + 1))}
          {S.working && (
            <div style={{ marginBottom: "14px" }}>
              <StepProgress
                steps={S.working.ids.map((id, k) => ({ key: id, label: `${S.kind === "video" ? "Editing" : "Making"} ${itemName(S.cards.findIndex((c) => c.id === id)).toLowerCase()}`, state: (k < S.working!.idx ? "done" : k === S.working!.idx ? "active" : "waiting") as any }))}
                activeStartedAt={S.working.startedAt}
                note="Each one lands on its own card when it's done. You can keep working."
              />
            </div>
          )}
          {hasResults && !S.working && (
            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: "10px", margin: "4px 0 16px" }}>
              {S.redoAll ? (
                <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "8px", flexWrap: "wrap" }}>
                  <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "13.5px", color: "#525252" }}>{S.cards.length === 2 ? "Re-do both?" : `Re-do all ${S.cards.length}?`}</span>
                  <button type="button" onClick={() => setState((s) => ({ ...s, redoAll: false }))} style={{ ...outlineSm, border: "none", color: "#737373" }}>Cancel</button>
                  {/* Re-do All covers every item, queued ones too: once wired, a re-do moves the record back to To Edit and into the editing queue, so it comes off the schedule queue. */}
                  <button type="button" onClick={() => setState((s) => ({ ...s, redoAll: false, after: [...s.after, { from: "user", text: "Re-do All", at: Date.now() }, { from: "flowy", at: Date.now(), text: s.cards.some((c) => c.result?.queued) ? `Re-doing ${s.cards.length === 2 ? "both" : `all ${s.cards.length}`}, queued ones too. They come off the schedule queue and the new versions land on their cards.` : `Re-doing ${s.cards.length === 2 ? "both" : `all ${s.cards.length}`}. The new versions land on their cards.` }],
                    cards: s.cards.map((c) => (c.result ? { ...c, redo: false, redoNote: "", result: { version: c.result.version + 1, queued: "" as const } } : c)) }))} style={gradSm()}>Re-do All</button>
                </div>
              ) : (
                <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "8px", flexWrap: "wrap" }}>
                  <ReplyChip onClick={() => { setMenuFor(null); setState((s) => ({ ...s, redoAll: true })); }}>Re-do All</ReplyChip>
                  <ReplyChip primary disabled={!unqueued.length} onClick={() => setState((s) => ({ ...s, after: [...s.after, { from: "user", text: "Send All to Schedule", at: Date.now() }, { from: "flowy", at: Date.now(), text: (() => { const n = s.cards.filter((c) => c.result && !c.result.queued).length; return s.cards.length === 1 ? "It's queued to schedule." : n === s.cards.length ? (n === 2 ? "Both are queued to schedule." : `All ${n} are queued to schedule.`) : `${n} more queued to schedule. All ${s.cards.length} are on the queue now.`; })() }],
                    cards: s.cards.map((c) => (c.result && !c.result.queued ? { ...c, redo: false, result: { ...c.result, queued: "queue" as const } } : c)) }))}>Send All to Schedule</ReplyChip>
                </div>
              )}
              <button type="button" onClick={startOver} style={{ ...linkBtn, fontSize: "13px" }}>Start Over</button>
            </div>
          )}
          {!hasResults && !S.working && (
            <div style={{ display: "flex", justifyContent: "flex-end", paddingBottom: "14px" }}>
              <button type="button" onClick={startOver} style={{ ...linkBtn, fontSize: "13px" }}>Start Over</button>
            </div>
          )}
        </>
      )}
      {/* The chat box stays greyed at the bottom through this route. Above it, while the cards are set up, how many
          are ready and the one button that sends them. */}
      <div aria-hidden="true" style={{ height: "20px", flexShrink: 0 }} />
      <div style={railDockStyle(isDesktop)}>
        {S.step === "cards" && !hasResults && !S.working && (
          <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-end", gap: "12px", flexWrap: "wrap", marginBottom: "10px" }}>
            <span style={{ fontFamily: "'Geist', sans-serif", fontSize: "13px", color: "#737373", textAlign: "right" }}>
              {allReady ? `All ${S.cards.length} ready` : <><b style={{ color: "#171717" }}>{readyCount}</b> of <b style={{ color: "#171717" }}>{S.cards.length}</b> ready</>}
            </span>
            <GradientButton onClick={go} disabled={!allReady}>{goLabel}</GradientButton>
          </div>
        )}
        <RailComposer value="" onChange={() => {}} onSend={() => {}} placeholder={S.kind === "video" ? "Chat opens with your first video" : "Chat opens with your first design"} off isDesktop={isDesktop} />
      </div>
      {picker && (() => {
        const pc = S.cards.find((c) => c.id === picker.cardId);
        if (!pc) return null;
        const list = pc[picker.which];
        return (
          <MediaPickerSheet
            key={picker.cardId + picker.which}
            title={picker.which === "clips" ? "Add Footage" : "Add Footage or Photos"}
            subtitle={itemName(S.cards.indexOf(pc))}
            only={picker.which === "clips" ? "video" : "any"}
            onCard={list.map((f) => f.uploadId || f.mediaRowId || "").filter(Boolean)}
            recordId={pc.recordId}
            fileTypeFor={(k) => (picker.which === "clips" ? "Raw Footage" : k === "video" ? "Video" : "Image")}
            dropped={picker.files}
            isDesktop={isDesktop}
            onClose={() => setPicker(null)}
            onPick={(got) => {
              const which = picker.which;
              setPicker(null);
              if (got.length) {
                patchCard(pc.id, (cc) => ({ [which]: [...cc[which], ...got] } as any));
                attachToRecord(pc.id, which, got);
              }
            }}
          />
        );
      })()}
    </>
  );
}

// The rail's warning modal (§6): shared shell for Discard and Regenerate.
// The writing screen's progress (Karen 2026-09-13): every part of the script
// with its state, a live timer on the part being written so it is plainly
// still working, and a plain note when a part runs long or is being written
// again. The timer lives in here so only this box re-renders every second.
// A step list with a live clock on the step that is running (Karen
// 2026-09-13): used by the topics hold and the writing screen, so waiting
// always looks the same and always shows something moving. The clock lives in
// here so only this box re-renders every second. `note` always shows;
// `longNote` shows once the running step passes 75 seconds.
function StepProgress({ steps, activeStartedAt, note, longNote, delayS = 0 }: {
  steps: { key: string; label: string; state: "done" | "active" | "waiting" | "failed"; detail?: string }[];
  activeStartedAt: number;
  note?: string;
  longNote?: string;
  delayS?: number;
}) {
  const running = steps.some((s) => s.state === "active");
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    if (!running) return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [running]);
  const elapsed = running && activeStartedAt ? Math.max(0, Math.floor((now - activeStartedAt) / 1000)) : 0;
  const clock = `${Math.floor(elapsed / 60)}:${String(elapsed % 60).padStart(2, "0")}`;
  const line = note || (running && longNote && elapsed >= 75 ? longNote : "");
  return (
    <div
      className="strat-bubble-in"
      style={{
        // The column's full width, so it lines up with the chat box under it (Karen 2026-10-22).
        animationDelay: `${delayS}s`, margin: "2px 0 4px",
        background: "white", border: "1px solid #ededed", borderRadius: "12px", padding: "6px 14px",
      }}
    >
      {steps.map((s) => (
        <div key={s.key} style={{ display: "flex", alignItems: "center", gap: "10px", padding: "7px 0" }}>
          <span style={{ width: "18px", height: "18px", flexShrink: 0, display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
            {s.state === "done" ? (
              <span style={{ width: "18px", height: "18px", borderRadius: "50%", background: "#16A34A", display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
                <Check size={11} strokeWidth={3} color="white" />
              </span>
            ) : s.state === "failed" ? (
              <AlertTriangle size={16} strokeWidth={2} style={{ color: "#DC2626" }} />
            ) : s.state === "active" ? (
              <span style={{ width: "10px", height: "10px", borderRadius: "50%", background: "#A855F7", animation: "fsTypingDot 1.2s ease-in-out infinite" }} />
            ) : (
              <span style={{ width: "12px", height: "12px", borderRadius: "50%", border: "1.5px solid #D4D4D4", boxSizing: "border-box" }} />
            )}
          </span>
          <span style={{
            flex: 1, fontFamily: "'Geist', sans-serif", fontSize: "13.5px",
            color: s.state === "waiting" ? "#A3A3A3" : "#171717", fontWeight: s.state === "active" ? 500 : 400,
          }}>
            {s.label}
          </span>
          {s.state === "active" && (
            <span style={{ fontFamily: "'Geist Mono', monospace", fontSize: "11px", color: "#A3A3A3", flexShrink: 0 }}>
              {s.detail ? `${s.detail} · ` : ""}{activeStartedAt ? clock : ""}
            </span>
          )}
        </div>
      ))}
      {line && (
        <div style={{
          borderTop: "1px solid #f4f4f4", marginTop: "2px", padding: "8px 0 6px",
          fontFamily: "'Geist', sans-serif", fontSize: "12.5px", lineHeight: 1.45, color: "#737373",
        }}>
          {line}
        </div>
      )}
    </div>
  );
}

// "Add your own idea" on the topics step (Karen 2026-09-13): the founder types
// or says an idea, and Flowy files it under the closest topic in the brand's
// bank, writes its stance from their words, and adds it to the list as a card.
// The box of the Script from Idea path (Karen 2026-09-16): type it, paste a
// link, or record it. One box, no stance, no format.
function IdeaBriefComposer({ text, onText, onNext }: { text: string; onText: (v: string) => void; onNext: () => void }) {
  const voice = useVoiceNote((spoken) => onText(joinSpoken(text, spoken)));
  return (
    <div style={{ marginTop: "10px", background: "white", border: "1px solid #ededed", borderRadius: "14px", padding: "12px 14px 14px" }}>
      <div style={{ background: "white", border: "1px solid #ededed", borderRadius: "10px", overflow: "hidden" }}>
        <AutoGrowTextarea
          value={text}
          onChange={(e: any) => onText(e.target.value)}
          placeholder="Type it, paste a link, or tap the mic."
          maxHeight={260}
          style={{
            width: "100%", boxSizing: "border-box", border: "none", outline: "none", background: "transparent",
            padding: "10px 13px 4px", fontFamily: "'Geist', sans-serif", fontSize: "15px", lineHeight: 1.55, color: "#171717",
          }}
        />
        <VoiceMicButton state={voice.state} secs={voice.secs} onToggle={voice.toggle} label="Record your idea" />
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "12px" }}>
        <GradientButton onClick={onNext} disabled={!text.trim() || voice.state !== "idle"}>Continue</GradientButton>
      </div>
    </div>
  );
}

// Start From an Idea, as a chat (Karen 2026-10-23, after Create Media): Flowy asks what to talk about, the
// answer comes through the chat box (typed or recorded), a TikTok or Instagram post in it is the inspiration
// post, then how many scripts and which format. Each idea folds into a small card, and the cards go to the
// same filing as the old idea cards (startFromIdeaCards), so what is sent and written is unchanged.
type IdeaPick = "auto" | "talking" | "silent" | "carousel" | "single";
type IdeaStep = "talk" | "link" | "count" | "format" | "more" | "topic";
// A line of the idea chat. A user line keeps the idea as it was before that answer, so Go back can undo it.
type IdeaLine = { from: "flowy" | "user"; text: string; link?: string; step?: IdeaStep; at: number; before?: IdeaCardDraft | null };
// `log` is the idea's own questions and answers, kept for the saved conversation.
type IdeaCardDraft = { id: string; text: string; link: string; count: number; pick: IdeaPick; log?: IdeaLine[] };
// The idea chat: the question being asked (its Flowy lines), the answers so far for the idea being asked
// about, that idea, whether it is an edit of a card, and the cards still waiting on a main point.
type IdeaChat = { step: IdeaStep; ask: string[]; log: IdeaLine[]; draft: IdeaCardDraft | null; editing: boolean; topicFor: string[] };
const IDEA_PICKS: Record<"video" | "graphic", { value: IdeaPick; label: string }[]> = {
  video: [{ value: "auto", label: "Let Flowy Choose" }, { value: "talking", label: "Talking Video" }, { value: "silent", label: "No-talking Video" }],
  graphic: [{ value: "auto", label: "Let Flowy Choose" }, { value: "carousel", label: "Carousel" }, { value: "single", label: "Single Graphic" }],
};
// The inspiration post (Karen 2026-10-19): a TikTok or Instagram post, the two the idea flow can read.
const isPostLink = (u: string): boolean => {
  const m = String(u || "").trim().match(/^https?:\/\/([^/?#\s]+)(\S*)$/i);
  if (!m) return false;
  const host = m[1].toLowerCase();
  const path = m[2].toLowerCase();
  if (/^(vm|vt)\.tiktok\.com$/.test(host)) return true;
  if (/(^|\.)tiktok\.com$/.test(host)) return /\/(video|photo)\/|^\/t\//.test(path);
  if (/(^|\.)instagram\.com$/.test(host)) return /\/(p|reel|reels|tv)\//.test(path);
  return false;
};
const newIdeaCard = (): IdeaCardDraft => ({ id: "idea-" + Math.random().toString(36).slice(2, 9), text: "", link: "", count: 1, pick: "auto" });
const IDEA_TALK_ASK = ["What do you want to talk about?", "Type it or record it below. Add the post that inspired it, if there is one."];
const IDEA_MORE_ASK = ["Anything else to talk about?"];
const newIdeaChat = (): IdeaChat => ({ step: "talk", ask: IDEA_TALK_ASK, log: [], draft: null, editing: false, topicFor: [] });
const ideaFirstLine = (t: string, max = 80) => {
  const l = String(t || "").split("\n").map((x) => x.trim()).find(Boolean) || "";
  return l.length > max ? l.slice(0, max - 1).trimEnd() + "…" : l;
};
const ideaPickLabel = (family: "video" | "graphic", pick: IdeaPick) => (IDEA_PICKS[family].find((p) => p.value === pick) || IDEA_PICKS[family][0]).label;
const ideaCardSub = (family: "video" | "graphic", c: IdeaCardDraft) => `${c.count} script${c.count === 1 ? "" : "s"} · ${ideaPickLabel(family, c.pick)}`;
const ideaWriteLabel = (total: number) => (total === 1 ? "Write My Script" : `Write My ${total} Scripts`);
const ideaPostName = (u: string) => (/tiktok\.com/i.test(u) ? "TikTok Post" : "Instagram Post");
// A sent message pulled apart: the first TikTok or Instagram post is the inspiration post, a link that is no
// post is taken out and named back, and the words are what is left. Words with no link are kept exactly as sent.
const splitIdeaMessage = (raw: string): { text: string; shown: string; post: string; bad: string[] } => {
  const urls = Array.from(String(raw || "").matchAll(/https?:\/\/[^\s)]+/g)).map((m) => m[0]);
  let text = raw, shown = raw, post = "";
  const bad: string[] = [];
  const tidy = (s: string) => s.replace(/[ \t]{2,}/g, " ").replace(/[ \t]*\n[ \t]*/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  for (const u of urls) {
    const clean = u.replace(/[.,;:!?]+$/, "");
    if (isPostLink(clean)) {
      if (post) continue;
      post = clean;
      text = text.replace(clean, " ");
      shown = shown.replace(clean, " ");
    } else {
      bad.push(clean);
      text = text.replace(clean, " ");
    }
  }
  if (post || bad.length) text = tidy(text);
  if (post) shown = tidy(shown);
  return { text: text.trim(), shown: shown.trim(), post, bad };
};
// What to ask about a card the filing found nothing to talk about in (Karen 2026-10-21).
const ideaTopicAsk = (c?: IdeaCardDraft | null): string[] => [
  c && ideaFirstLine(c.text) ? `I need a little more on “${ideaFirstLine(c.text, 60)}”.` : "I need a little more on one of your ideas.",
  "What's the main point you want to make?",
];
// One idea's questions and answers, as saved steps of the conversation (the Flowy lines, then the answer).
const ideaLogSteps = (log: IdeaLine[]): { kind: string; flowy: string[]; user: string }[] => {
  const out: { kind: string; flowy: string[]; user: string }[] = [];
  let fl: string[] = [];
  let kind = "";
  for (const l of log) {
    if (l.from === "flowy") {
      if (!fl.length) kind = "idea" + (l.step ? l.step.charAt(0).toUpperCase() + l.step.slice(1) : "");
      fl.push(threadClip(l.text));
    } else {
      out.push({ kind: kind || "idea", flowy: fl, user: threadClip([l.text, l.link || ""].filter(Boolean).join("\n")) });
      fl = []; kind = "";
    }
  }
  return out;
};
const escIdeaHtml = (s: string) => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
// The idea step as it stays in the thread once the scripts are on their way: the cards, then Flowy's question
// (the tap shows under it as the answer bubble). Drawn the way the live cards look, with no buttons.
const ideaThreadHtml = (cards: IdeaCardDraft[], family: "video" | "graphic") => {
  const rows = cards.map((c) => `<div style="background:#FFFFFF;border:1px solid #ededed;border-radius:14px;padding:13px 14px;font-family:'Geist',sans-serif;min-width:0">`
    + `<div style="font-size:14px;font-weight:600;line-height:1.35;color:#171717;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escIdeaHtml(ideaFirstLine(c.text))}</div>`
    + `<div style="font-size:12.5px;line-height:1.35;color:#737373;margin-top:1px">${escIdeaHtml(ideaCardSub(family, c) + (c.link ? " · " + ideaPostName(c.link) : ""))}</div></div>`).join("");
  return `<div style="display:flex;flex-direction:column;gap:12px;margin:4px 0 16px">${rows}</div>`
    + `<div style="max-width:640px;margin:0 0 12px;font-family:'Geist',sans-serif;font-size:15px;font-weight:400;line-height:1.6;color:#171717">${escIdeaHtml(IDEA_MORE_ASK[0])}</div>`;
};

function OwnIdeaComposer({ text, onText, state, failWhat, startedAt, onAdd, onClose, supportSubject }: {
  text: string;
  onText: (v: string) => void;
  state: "idle" | "adding" | "failed";
  failWhat: "file" | "stance";
  startedAt: number;
  onAdd: () => void;
  onClose: () => void;
  supportSubject: string;
}) {
  const voice = useVoiceNote((spoken) => onText(joinSpoken(text, spoken)));
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    if (state !== "adding") return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [state]);
  const elapsed = state === "adding" && startedAt ? Math.max(0, Math.floor((now - startedAt) / 1000)) : 0;
  const clock = `${Math.floor(elapsed / 60)}:${String(elapsed % 60).padStart(2, "0")}`;
  return (
    <div style={{
      marginTop: "10px", background: "white", border: "1px solid #ededed", borderRadius: "14px",
      padding: "12px 14px 14px", animation: "fsBubbleIn 0.18s cubic-bezier(0.16,1,0.3,1) both",
    }}>
      <div style={{ display: "flex", alignItems: "center", marginBottom: "8px" }}>
        <span style={{
          display: "inline-flex", alignItems: "center", gap: "6px",
          fontFamily: "'Geist Mono', monospace", fontSize: "10.5px", fontWeight: 600,
          letterSpacing: "0.09em", textTransform: "uppercase", color: "#16171A",
        }}>
          <Lightbulb size={12} strokeWidth={2.2} style={{ color: "#6366F1" }} /> Your idea
        </span>
        <span style={{ flex: 1 }} />
        {state !== "adding" && (
          <button
            onClick={onClose}
            aria-label="Close"
            style={{ width: "24px", height: "24px", background: "transparent", border: "none", cursor: "pointer", color: "#737373", padding: 0 }}
          >
            <X size={14} strokeWidth={2} />
          </button>
        )}
      </div>
      {state === "adding" ? (
        <>
          <div style={{ display: "flex", alignItems: "center", gap: "10px", padding: "6px 0" }}>
            <span style={{ width: "10px", height: "10px", borderRadius: "50%", background: "#A855F7", flexShrink: 0, animation: "fsTypingDot 1.2s ease-in-out infinite" }} />
            <span style={{ flex: 1, fontFamily: "'Geist', sans-serif", fontSize: "13.5px", lineHeight: 1.45, color: "#171717" }}>
              Finding where this fits in your topics, then writing your stance.
            </span>
            <span style={{ fontFamily: "'Geist Mono', monospace", fontSize: "11px", color: "#A3A3A3" }}>{clock}</span>
          </div>
          <div style={{ marginTop: "2px", fontFamily: "'Geist', sans-serif", fontSize: "12px", color: "#A3A3A3" }}>
            It shows up in your list in about a minute.
          </div>
        </>
      ) : (
        <>
          <div style={{ background: "white", border: "1px solid #ededed", borderRadius: "10px", overflow: "hidden" }}>
            <AutoGrowTextarea
              value={text}
              onChange={(e: any) => onText(e.target.value)}
              placeholder="What do you want to talk about? A question you keep getting, an opinion, something that happened."
              maxHeight={220}
              style={{
                width: "100%", boxSizing: "border-box", border: "none", outline: "none", background: "transparent",
                padding: "10px 13px 4px", fontFamily: "'Geist', sans-serif", fontSize: "15px", lineHeight: 1.55, color: "#171717",
              }}
            />
            <VoiceMicButton state={voice.state} secs={voice.secs} onToggle={voice.toggle} label="Record your idea" />
          </div>
          {state === "failed" && (
            <div style={{ marginTop: "8px", fontFamily: "'Geist', sans-serif", fontSize: "12.5px", lineHeight: 1.45, color: "#B45309" }}>
              {failWhat === "stance"
                ? "Your idea is saved. Flowy couldn't write your stance for it just now, so try again."
                : "Flowy couldn't add that just now. Your words are still here, so try again."}
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "12px" }}>
            <GradientButton onClick={onAdd} disabled={!text.trim() || voice.state !== "idle"}>
              {state === "failed" ? "Try Again" : "Add It"}
            </GradientButton>
          </div>
          {state === "failed" && <RailSupportLine subject={supportSubject} />}
        </>
      )}
    </div>
  );
}

// The filming choice as a slider with three stops (Karen 2026-09-13): every
// video batch films something, so the question is how much. Since 2026-10-10
// each stop is time on camera for the whole batch (FILMING_BUDGET_MIN), weighed
// against the Formats table's filming minutes, approximately.
const FILM_STOPS: { value: FilmTilt; label: string; hint: string }[] = [
  { value: "none", label: "Under 30 min", hint: "About half an hour on camera for the whole batch, so mostly formats that are quick to film." },
  { value: "some", label: "About 1 hour", hint: "About an hour on camera for the whole batch." },
  { value: "full", label: "More than 1 hour", hint: "Camera time is not a limit this round." },
];
function FilmSlider({ index, onChange }: { index: number; onChange: (i: number) => void }) {
  const trackRef = useRef<HTMLDivElement | null>(null);
  const dragging = useRef(false);
  const last = FILM_STOPS.length - 1;
  const pickAt = (clientX: number) => {
    const el = trackRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    if (!r.width) return;
    const rel = Math.min(1, Math.max(0, (clientX - r.left - 12) / (r.width - 24)));
    onChange(Math.round(rel * last));
  };
  const at = (i: number) => `calc(12px + (100% - 24px) * ${i / last})`;
  return (
    <div style={{ marginTop: "24px" }}>
      <div
        ref={trackRef}
        onPointerDown={(e: any) => {
          dragging.current = true;
          try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* not supported */ }
          pickAt(e.clientX);
        }}
        onPointerMove={(e: any) => { if (dragging.current) pickAt(e.clientX); }}
        onPointerUp={() => { dragging.current = false; }}
        onPointerCancel={() => { dragging.current = false; }}
        style={{ position: "relative", height: "36px", cursor: "pointer", touchAction: "none" }}
      >
        <div style={{ position: "absolute", left: "12px", right: "12px", top: "17px", height: "3px", borderRadius: "2px", background: "#E5E5E5" }} />
        <div style={{ position: "absolute", left: "12px", top: "17px", height: "3px", borderRadius: "2px", background: BRAND_GRADIENT, width: `calc((100% - 24px) * ${index / last})`, transition: "width 0.16s ease" }} />
        {FILM_STOPS.map((s, i) => (
          <span key={s.value} style={{
            position: "absolute", top: "13px", left: at(i), width: "11px", height: "11px", marginLeft: "-5.5px",
            borderRadius: "50%", background: i <= index ? "#A855F7" : "#D4D4D4",
          }} />
        ))}
        <span style={{
          position: "absolute", top: "6px", left: at(index), width: "25px", height: "25px", marginLeft: "-12.5px",
          borderRadius: "50%", background: "white", border: "2px solid #A855F7", boxSizing: "border-box",
          boxShadow: "0 2px 8px rgba(168,85,247,0.35)", transition: "left 0.16s ease",
        }} />
      </div>
      <div style={{ display: "flex", marginTop: "4px" }}>
        {FILM_STOPS.map((s, i) => (
          <button
            key={s.value}
            onClick={() => onChange(i)}
            style={{
              flex: 1, background: "transparent", border: "none", padding: "4px 0", cursor: "pointer",
              fontFamily: "'Geist', sans-serif", fontSize: "12.5px", fontWeight: i === index ? 600 : 400,
              color: i === index ? "#A855F7" : "#737373",
              textAlign: i === 0 ? "left" : i === last ? "right" : "center",
            }}
          >
            {s.label}
          </button>
        ))}
      </div>
    </div>
  );
}

// "Contact support" on the rail: the settled support route, the email form at
// hello@flowshift.io, with what went wrong already in the subject.
function RailSupportLine({ subject }: { subject: string }) {
  return (
    <div style={{
      display: "flex", justifyContent: "flex-end", alignItems: "center", gap: "5px", marginTop: "12px",
      fontFamily: "'Geist', sans-serif", fontSize: "12.5px", color: "#737373",
    }}>
      Still not working?
      <a
        href={`mailto:hello@flowshift.io?subject=${encodeURIComponent(subject)}`}
        style={{ color: "#A855F7", fontWeight: 500, textDecoration: "none" }}
      >
        Contact support
      </a>
    </div>
  );
}

function RailModal({
  title, body, cta, cancelLabel = "Cancel", onCancel, onConfirm,
}: {
  title: string; body: string; cta: string; cancelLabel?: string;
  onCancel: () => void; onConfirm: () => void;
}) {
  return createPortal(
    <>
      {/* Block styles don't reach portals — carry the keyframes along. */}
      <style>{`
        @keyframes fsDimIn { from { opacity: 0 } to { opacity: 1 } }
        @keyframes fsBubbleIn { from { opacity: 0; transform: translateY(5px) } to { opacity: 1; transform: translateY(0) } }
      `}</style>
      <div
        onClick={onCancel}
        style={{
          position: "fixed", inset: 0, zIndex: 10060, background: "rgba(23,23,23,0.42)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: "24px",
          animation: "fsDimIn 0.16s ease both",
        }}
      >
        <div
          onClick={(e: any) => e.stopPropagation()}
          style={{
            maxWidth: "380px", width: "100%", background: "white", borderRadius: "16px",
            padding: "22px 22px 18px", boxShadow: "0 30px 70px -24px rgba(30,32,40,0.5)",
            animation: "fsBubbleIn 0.18s cubic-bezier(0.16,1,0.3,1) both",
          }}
        >
          <div style={{
            width: "34px", height: "34px", borderRadius: "50%", background: "#FEF2F2",
            display: "flex", alignItems: "center", justifyContent: "center", marginBottom: "12px",
          }}>
            <AlertTriangle size={18} strokeWidth={2} style={{ color: "#DC2626" }} />
          </div>
          <div style={{ fontFamily: "'Geist', sans-serif", fontSize: "16px", fontWeight: 600, letterSpacing: "-0.01em", color: "#171717", marginBottom: "8px" }}>
            {title}
          </div>
          <div style={{ fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 350, lineHeight: 1.5, color: "#525252", marginBottom: "18px" }}>
            {body}
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: "8px" }}>
            <button
              onClick={onCancel}
              style={{
                height: "40px", padding: "0 16px", borderRadius: "8px", whiteSpace: "nowrap",
                background: "white", border: "1px solid #ededed", color: "#171717",
                fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 500, cursor: "pointer",
              }}
            >
              {cancelLabel}
            </button>
            <button
              onClick={onConfirm}
              style={{
                height: "40px", padding: "0 16px", borderRadius: "8px", whiteSpace: "nowrap",
                background: "#DC2626", border: "none", color: "white",
                fontFamily: "'Geist', sans-serif", fontSize: "14px", fontWeight: 600, cursor: "pointer",
              }}
            >
              {cta}
            </button>
          </div>
        </div>
      </div>
    </>,
    document.body,
  );
}